quests[28078] = { id = 28078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Haupttor von Stratholme", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Haupttor von Stratholme nördlich vom Pestwald zu reisen!\n\nDer Schreckenslord Balnazzar hat Kreuzfahrer des scharlachroten Kreuzzugs getötet und sie als Auferstandende wiederbelebt! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.", sourceObjective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28079] = { id = 28079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Haupttor von Stratholme", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Haupttor von Stratholme nördlich vom Pestwald zu reisen!\n\nDer Schreckenslord Balnazzar hat Kreuzfahrer des scharlachroten Kreuzzugs getötet und sie als Auferstandende wiederbelebt! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.", sourceObjective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28080] = { id = 28080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Dienstbotentor von Stratholme", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Dienstbotentor von Stratholme nordwestlich des Nordpassturms zu reisen!\n\nBaron Aurius Totenschwur, ehemaliger Paladin der Silbernen Hand und kürzlich wiederbelebter Sohn von niemand Geringerem als Baron Totenschwur selbst, führt nun die restlichen Streitmächte der Geißel an! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.", sourceObjective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28081] = { id = 28081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Dienstbotentor von Stratholme", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Dienstbotentor von Stratholme, nordwestlich des Nordpassturms zu reisen!\n\nBaron Aurius Totenschwur, ehemaliger Paladin der Silbernen Hand und kürzlich wiederbelebter Sohn von niemand Geringerem als Baron Totenschwur selbst, führt nun die restlichen Streitmächte der Geißel an! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.", sourceObjective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28082] = { id = 28082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scholomance", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich nach Scholomance östlich von Andorhal zu reisen!\n\nRas Frostraunen und Dunkelmeister Gandling sind noch immer damit beschäftigt, mächtige Zauberer für die Geißel auszubilden! Falls Ihr interessiert seid, begebt Euch nach Scholomance und sprecht mit Weldon Barov, dem letzten lebenden Sohn der Barovfamilie und rechtmäßiger Erbe der umliegenden Ländereien.", sourceObjective = "Sprecht mit Weldon Barov.", sourceObjectiveStatus = "unverified-source-field" }
quests[28083] = { id = 28083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer gesucht: Scholomance", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich nach Scholomance östlich von Andorhal zu reisen!\n\nRas Frostraunen und Dunkelmeister Gandling sind noch immer damit beschäftigt, mächtige Zauberer für die Geißel auszubilden! Falls Ihr interessiert seid, begebt Euch nach Scholomance und sprecht mit Alexi Barov, einem der letzten Erben des Reichtums der Barovfamilie und unser Kontakt in der dunklen Schule.", sourceObjective = "Sprecht mit Alexi Barov.", sourceObjectiveStatus = "unverified-source-field" }
quests[28084] = { id = 28084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Krom'gar", sourceObjective = "Ihr habt jetzt Zugang zum Vorratslager der Krom'gar, {name}! Für ein geringes Entgelt verkaufe ich Euch Kampfausrüstung, die Euch beim Vernichten Eurer Feinde dienlich sein wird! Es hängt von Eurem Rang in der Armee ab, welche Waren ich Euch verkaufen kann. Besucht mein Geschäft, wann immer Ihr einen neuen Rang erhaltet.\n\nLOK'TAR OGAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[28085] = { id = 28085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Steilhang", description = "Vielen Dank für Eure Hilfe, {name}. Ihr solltet Euch mit Pao'ka Bergrausch in Steilhang unterhalten, südlich von hier.\n\nVielleicht weiß er, wo sich die Ältestengreisin befindet?", sourceObjective = "Sprecht mit Pao'ka Bergrausch in Steilhang in Tausend Nadeln.", completion = "Ich weiß nichts von Magatha, der Ältestengreisin. Ich weiß aber, dass der Schattenhammer den Steilhang zerstört.\n\nKönnt Ihr mir dabei helfen, sie aufzuhalten, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[28086] = { id = 28086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit die Wyverlinge!", description = "Die Fallensteller arbeiten daran, alle jungen Windreiter zusammenzutrommeln. {name}, könnt Ihr Euch der Sache annehmen und die Wyverlinge befreien?", sourceObjective = "Befreit 12 Steilhangwyverlinge.", completion = "Sie sind so wertvoll. Eines Tages werden sie auch stark sein, aber bis dahin müssen sie beschützt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28087] = { id = 28087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod allen Fallenstellern!", description = "Für die dreckigen Fallensteller der Schattenhämmer haben wir nur eines übrig: den Tod!\n\nBringt mir ihre Netze, {name}.", sourceObjective = "Sammelt 8 Netze der Fallensteller.", progress = "Welcher Wahnsinn kann jemanden dazu bringen, so grauenvolle Taten zu vollbringen?", completion = "Ab dem heutigen Tage werden keine Fallen mehr hier zu finden sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[28088] = { id = 28088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Freilassung von Klingenherz", description = "Der Schattenhammer hält das Alphamännchen von Steilhang fest. Ihr müsst Euch nach Osten begeben und Klingenherz befreien, bevor das Rudel seinen Anführer verliert.", sourceObjective = "Befreit Klingenherz von allen Ketten, die ihn festhalten.", completion = "Der große Klingenherz ist eine majestätische Kreatur. Er hat mir von seiner Dankbarkeit und Wertschätzung für Euch berichtet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28089] = { id = 28089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Das Vorgebirge des Hügellands!", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands zu melden. Die Kriegsmaschinerie der Verlassenen bewegt sich immer weiter vorwärts und sichert Lordaeron für die Horde!\n\nUm das Südwachttor zu erreichen, müsst Ihr der Straße in Richtung Süden durch den Silberwald folgen und die östliche Abzweigung nehmen, die ins Vorgebirge des Hügellands führt.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", sourceObjective = "Meldet Euch bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands.", completion = "Ich habe mich schon gefragt, wann die Verstärkung eintreffen würde. Macht Euch bereit, {name}. Zeit, etwas Gerechtigkeit walten zu lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28090] = { id = 28090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvolle Waren", description = "Die Tore weiter unten im Canyon sind geschlossen. Wir haben ausgekundschaftet, dass es eine Art Stein gibt, den sie in Kisten in ihren Karawanen mitführen, und zum Öffnen der Tore benutzen.\n\nGeht dort hinunter und durchsucht die Leichen der Wachen nach einem Truhenschlüssel. Wenn Ihr ihn findet, benutzt ihn bei einer der großen Truhen auf den Karawanenwagen und bringt den Torstein zu mir zurück.", sourceObjective = "Bergt einen Torstein der Zwielichtkarawane. Die Speerwächter sollten Schlüssel bei sich tragen, die Euch Zugang zu den Truhen mit den Torsteinen verschaffen.", progress = "Wisst Ihr, wir könnten die Tore wahrscheinlich einfach aufsprengen, aber wie wir unseren Sprengmeister kennen, sollten wir das Risiko lieber nicht eingehen.", completion = "Gut gemacht!\n\nSieht nicht nach etwas Besonderem aus, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[28091] = { id = 28091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichte Aufgabe", description = "Der Hinterhalt ging problemlos vonstatten. Die meisten Wachen sind tot, aber einige sitzen immer noch bei den Wagen fest.\n\nIhr könnt sie genau im Westen in dem Canyon unter uns sehen. Geht dorthin und erledigt sie, damit wir diesen Angriff ins Rollen bringen können.", sourceObjective = "Tötet 8 Zwielichtspeerwärter.", completion = "Ausgezeichnet. Jetzt können wir unsere Bodentruppen in Richtung Grim Batol in Bewegung setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28092] = { id = 28092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn der Schlüssel passt", description = "Die Wyrms haben den Kampf bereits in den Himmel über Grim Batol getragen. Jetzt ist es an uns, unsere Leute auf dem Boden dorthin zu bewegen und die Tore zu sichern.\n\nIhr sollt wissen, was auf dem Spiel steht, {class}. Grim Batol ist die Quelle der Verstärkung für den Schattenhammer im ganzen Hochland. Wenn wir das hier nicht unterbinden, werden wir die Kämpfe, die vor uns liegen, nicht gewinnen können.\n\nIch schicke die Goblinschwadron mit Euch. Erreicht das Tor im Südosten und öffnet es. Flick sollte weitere Anweisungen für Euch haben, wie es ab da weiter geht.", sourceObjective = "Führt die Goblinschwadron zu dem geschlossenen Tor des Drachenmals.\n\nWenn Ihr die Goblinschwadron verliert, kehrt zu Kriegsfürst Krogg zurück, damit Ihr neue Truppen zugeteilt bekommt.", progress = "Bleibt in Bewegung. Wir müssen das Tor öffnen.", completion = "Es klappt doch immer wieder aufs Neue.", sourceObjectiveStatus = "unverified-source-field" }
quests[28093] = { id = 28093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordringen", description = "Bis jetzt war das gute Arbeit. Wir sollten den Eingang zu Grim Batol direkt hinter dem nächsten Tor finden.\n\nIch habe Befehle, den Eingang zu sichern und der Verstärkung den Weg zu verstellen, während der Rest unserer Leute durch den Pfad, den wir durch den Canyon freigemacht haben, vorwärts drängt. Ich glaube, wir werden es bald geschafft haben, vielleicht kann ich Ticker dann ein wenig mehr Spaß gönnen.\n\nMachen wir uns auf den Weg hinunter in den Canyon im Südwesten - wir sollten das nächste Tor recht schnell finden.", sourceObjective = "Führt die Goblinschwadron am nördlichen Tor des Drachenmals vorbei zum Eingang von Grim Batol.\n\nWenn Ihr die Goblinschwadron verliert, kehrt zu Kriegsfürst Krogg zurück, damit Ihr neue Truppen zugeteilt bekommt.", completion = "Das Tor ist frei. Sobald Eure Leute den Canyon durchquert haben, werden wir mit Euren Anführern über den nächsten Schritt sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28094] = { id = 28094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg ebnen", description = "Meine Befehle lauten, Euch nach Süden durch die Tore des Drachenmals zum Eingang von Grim Batol zu begleiten. Wir sollen einen Weg freimachen, damit der Rest der Männer uns folgen und den Eingang sichern kann.\n\nÜbersetzung: Tötet alles, das sich bewegt und schämt Euch nicht, wenn Ihr Spaß dabei habt.\n\nDie Jungs werden langsam unruhig. Auf geht's.", sourceObjective = "Tötet 30 Kultisten des Schattenhammers entlang der Wyrmbiege, während Ihr Euch zum Eingang von Grim Batol durchkämpft.", completion = "Es sieht beinahe leicht aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28096] = { id = 28096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beamtenmikado", description = "Wer sich zuerst bewegt, hat verloren, <mein Lieber/meine Liebe>. Nur so kann man es als hochrangiger Offizier der Verlassenen zu etwas bringen. Ja, das hier ist in der Tat das gute Leben und Ihr werdet es leben!\n\nIch möchte, dass Ihr diese Befehle nehmt und sie an die kleinen Anfänger ausgebt, die hier vorbeikommen und nach Arbeit suchen. Wem Ihr was gebt, ist Euch überlassen.\n\nWenn Ihr bereit seid, steigt auf mein braves Skelettross auf - damit man Euch nicht übersieht - und fangt an, das Leben zu leben! Was bedeutet, einfach hier herumzustehen und zu warten.", sourceObjective = "Gebt 3 Quests aus.", progress = "Na, wie ist der \"Schreibtischjob\" so?", completion = "Na, wie war's? So, wie Ihr es Euch immer vorgestellt hattet? Aufregend, nicht wahr?\n\nNein?\n\n<Darthalia seufzt.>\n\nIch sehe, dass Ihr ein wahrer Held seid. Ihr braucht Action. Ich denke, ein \"Schreibtischjob\" ist nichts für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28097] = { id = 28097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tore von Grim Batol", description = "Krogg hat den Angriff begonnen, um durch den Canyon zu drängen. Er ist kurz hinter dem Tor im Südosten.\n\nIch werde die Schwadron zusammenrufen, damit wir uns dem Angriff anschließen. Wir treffen Euch dort unten.", sourceObjective = "Sprecht mit Kriegsfürst Krogg in der Wyrmbiege.", completion = "Der Canyon ist gut geschützt, aber die Ablenkung, die die Drachen liefern, dürfte reichen, damit wir durchbrechen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28098] = { id = 28098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Himmelsmeister der Schatten", description = "Richtofen der Schattenhimmelsmeister befindet sich oben und über Zwielichthorst südöstlich von hier. Es ist egal, was wir hier unten tun - wenn wir ihn nicht ausschalten, wird alle Hoffnung für Steilhang verloren sein.\n\nKlingenherz ist zwar zu schwer verletzt, um Euch im Kampf zu helfen, aber er kann Euch zum Horst fliegen. Der Rest liegt dann bei Euch, {name}.\n\nIch wünsche Euch viel Glück.", sourceObjective = "Fliegt mit Klingenherz nach Zwielichthorst und bekämpft Schattenhimmelsmeister Richtofen.", completion = "Die Wyverlinge haben das gemacht? Sie müssen Euch sehr schätzen, dafür dass Ihr sie befreit habt.\n\nIch danke Euch, {name}. Ihr habt den Steilhang gerettet!", sourceObjectiveStatus = "unverified-source-field" }
quests[28099] = { id = 28099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasha'krak", description = "Nach den Informationen, die Ihr geliefert habt, denke ich, dass einer der Handlanger des \"Erzherzogs\" seinen Blick bereits auf die Thoriumspitze gerichtet hat.\n\nSein Name ist Rasha'krak und er patrouilliert entlang der Lavaseen südlich von uns. Er sieht so aus wie die latenten Feuerelementare, die in der Nähe wüten. Es gibt aber einen kleinen Unterschied: die Armschienen der Bindung, die er an seinen Handgelenken trägt.\n\nFindet ihn und bringt mir diese Armschienen, {name}. Ich brauche einen Beweis dafür, dass wir uns in Gefahr befinden, bevor wir uns auf Kriege mit den Elementaren einlassen.", sourceObjective = "Beschafft Rasha'kraks Armschienen der Bindung.", progress = "Ich werde nicht gegen Elementare kämpfen, bis wir bewiesen haben, dass sie eine Bedrohung für uns sind.", completion = "Leider ist es so, wie ich vermutet hatte. Diese Armschienen tragen die unauslöschlichen Zeichen des Feuerlords und seiner Handlanger.\n\nAlso gut. Da sich weder Streitkräfte der Horde noch der Allianz in der Nähe dieser gottverlassenen Schlucht befinden, bleibt es an der Thoriumbruderschaft hängen, diesen Erzherzog aufzuhalten, bevor er noch mehr Böses verbreitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[28100] = { id = 28100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein sprechendes Totem", description = "Das Furbolgdorf im Süden ist die Heimat der Totenwaldfelle, die Todfeinde der Holzschlundfeste sind. Sie sind verderbt und widerwärtig, wie so vieles andere. Die Fäulnis des Waldes hat sie in den Wahnsinn getrieben.\n\nNun ist allerdings etwas Außergewöhnliches in der Nähe des Lagers geschehen. Reisende, die hier vorbeikamen, haben gesagt, dass das Totem an der Straße zu ihnen gesprochen hat.\n\nIch habe noch nie etwas gehört, wenn ich mich ihm genähert habe. Vielleicht spricht es mit Euch, {name}? Vielleicht könnt Ihr für mich herausfinden, was dort vor sich geht.", sourceObjective = "Sprecht mit dem Totem von Ruumbo in der Nähe des Lagers der Totenwaldfelle.", completion = "Ihr da... ja, Ihr! Ich habe Euch, {race}, als meinen Champion erwählt! Ihr werdet die Arbeit von Ruumbo verrichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[28101] = { id = 28101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias' Befehl", description = "Die Ereignisse in letzter Zeit machen es noch offensichtlicher, dass es zur Absicherung unseres Volkes nicht ausreicht, hier einfach nur auszuharren und sporadische Angriffe auf Grim Batol auszuführen - geschweige denn, dass wir Grim Batol zurückerobern könnten. Wir müssen aggressiver sein und sie mitten ins Herz treffen.\n\nIch habe zugestimmt, Eurem Kommandanten Drachen zur Unterstützung zu senden. Sie hatten ohnehin schon über einem Plan gebrütet, wie man auf Grim Batol losschlagen kann, also solltet Ihr Eure Aufmerksamkeit zunächst einmal darauf konzentrieren.\n\nIhr solltet Mathias Shaw am Drachenmalpass im Canyon südlich unter uns finden.", sourceObjective = "Sprecht mit Meister Mathias Shaw am Drachenmalpass.", completion = "Die roten Drachen sind bereit, zu helfen! Das war sicher nicht leicht. Die Allianz dankt Euch.\n\nAls die Drachen sich mit uns in Verbindung setzten, hatten wir bereits einen Plan ausgearbeitet, eine Zwielichtkarawane aus dem Hinterhalt heraus anzugreifen. Jetzt helfen sie uns, deren Rückzug zu unterbinden.\n\nDer Kampf tobt noch immer. Ihr könnt auf jeden Fall helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28102] = { id = 28102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekämpft die Macht", description = "Es ist Zeit für den entscheidenden Schlag gegen die Jadefeuer!\n\nWenn Ihr bereit seid, durch ihre verderbte Barriere zu brechen und ihrem Anführer den Kampf anzusagen, würde ich Euch auch darum bitten, uns gegen die niederen Satyrn zu unterstützen. Unsere Druiden kämpfen erbittert, aber Eure Stärke könnte helfen, die Schlacht zu unseren Gunsten zu wenden.\n\nZeigt den Jadefeuersatyrn, dass Ihre Macht nicht länger die Vorherrschaft über diese Lande hat!", sourceObjective = "Tötet 8 Jadefeuerschurken oder Jadefeuerschattenpirscher in den Ruinen von Constellas.", completion = "Einige der verbliebenen Satyrn sind in die Tiefen der Wälder geflohen, aber sie haben schwere Verluste erlitten. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28103] = { id = 28103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichte Aufgabe", description = "Der Hinterhalt ging problemlos vonstatten. Die meisten Wachen sind tot, aber einige sitzen immer noch bei den Wagen fest.\n\nGeht dorthin und erledigt sie, damit wir diesen Angriff ins Rollen bringen können.", sourceObjective = "Tötet 8 Zwielichtspeerwärter.", completion = "Ausgezeichnet. Jetzt können wir unsere Bodentruppen in Richtung Grim Batol in Bewegung setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28104] = { id = 28104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvolle Waren", description = "Die Tore weiter unten im Canyon sind geschlossen. Wir haben ausgekundschaftet, dass es eine Art Stein gibt, den sie in Kisten in ihren Karawanen mitführen, und zum Öffnen der Tore benutzen.\n\nGeht dort hinunter und durchsucht die Leichen der Wachen nach einem Truhenschlüssel. Wenn Ihr ihn findet, benutzt ihn bei einer der großen Truhen auf den Karawanenwagen und bringt den Torstein zu mir zurück.", sourceObjective = "Bergt einen Torstein der Zwielichtkarawane. Die Speerwächter sollten Schlüssel bei sich tragen, die Euch Zugang zu den Truhen mit den Torsteinen verschaffen.", progress = "Sie sind ein wenig zu selbstbewusst geworden. Das scheint zunehmend der Grund für den Untergang der mächtigsten Armeen zu sein.", completion = "Gut gemacht!\n\nSieht nicht nach etwas Besonderem aus, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[28105] = { id = 28105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kavem der Gefühllose", description = "Kavem war schon grausam genug, bevor die Neferset sich Todesschwinge verschrieben haben. Sein Vergnügen, anderen Schmerzen zuzufügen, grenzt inzwischen an Wahnsinn.\n\nEr hat jetzt die Schlüssel für unsere Fesseln.\n\nEr haust in dem Gebäude neben uns zu meiner Rechten.\n\nFindet ihn und nehmt seinen Schlüssel an Euch. Zögert nicht und erweist ihm keine Gnade. Er würde Euch die Kehle aufschlitzen und sich nichts dabei denken.", sourceObjective = "Beschafft den Schlüssel aus Neferset von Kavem dem Gefühllosen.", progress = "Ihr seid wieder da. Habt Ihr den Schlüssel?", completion = "Ausgezeichnet, {name}. Bald werden wir hier herauskommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28106] = { id = 28106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tore von Grim Batol (NICHT LÖSCHEN. NICHT ALS VERALTET FLAGGEN)" }
quests[28107] = { id = 28107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg ebnen", description = "Meine Befehle lauten, Euch nach Süden durch die Tore des Drachenmals zum Eingang von Grim Batol zu begleiten. Wir sollen einen Weg freimachen, damit der Rest der Männer uns folgen und den Eingang sichern kann.\n\nÜbersetzung: Tötet alles, was sich bewegt und schämt Euch nicht, wenn Ihr Spaß dabei habt.\n\nDie Jungs werden langsam unruhig. Auf geht's.", sourceObjective = "Tötet 30 Kultisten des Schattenhammers entlang der Wyrmbiege, während Ihr Euch zum Eingang von Grim Batol durchkämpft.", completion = "Es sieht beinahe leicht aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28108] = { id = 28108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn der Schlüssel passt", description = "Die Wyrms haben den Kampf bereits in den Himmel über Grim Batol getragen. Jetzt ist es an uns, unsere Leute auf dem Boden dorthin zu bewegen und die Tore zu sichern.\n\nIch will, dass Ihr wisst, was auf dem Spiel steht, {class}. Grim Batol ist die Quelle der Verstärkung für den Schattenhammer im ganzen Hochland. Wenn wir sie hier nicht aufhalten, werden wir die Kämpfe, die vor uns liegen, nicht gewinnen können.\n\nIch schicke eine Schwadron aus Hochstade mit Euch. Erreicht das Tor im Südosten und öffnet es. Euer Hauptmann sollte weitere Anweisungen für Euch haben, wie es ab da weiter geht.", sourceObjective = "Führt die Schwadron aus Hochstade zu dem geschlossenen Tor des Drachenmals.\n\nWenn Ihr Eure Schwadron verliert, kehrt zu Meister Mathias Shaw zurück, damit Ihr neue Truppen zugeteilt bekommt.", progress = "Bleibt in Bewegung. Wir müssen das Tor öffnen.", completion = "Wie eine gut geölte Kriegsmaschine.", sourceObjectiveStatus = "unverified-source-field" }
quests[28109] = { id = 28109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordringen", description = "Bis jetzt war das gute Arbeit.\n\nWir sollten den Eingang zu Grim Batol direkt hinter dem nächsten Tor finden. Ich habe Befehle, den Eingang zu sichern und der Verstärkung den Weg zu verstellen, während der Rest unserer Leute durch den Pfad, den wir durch den Canyon freigemacht haben, vorwärts drängt.\n\nMachen wir uns auf den Weg hinunter in den Canyon im Südwesten - wir sollten das nächste Tor recht schnell finden.", sourceObjective = "Führt Eure Schwadron an dem nördlichen Tor des Drachenmals vorbei zum Eingang von Grim Batol.\n\nWenn Ihr die Schwadron verliert, kehrt zu Meister Mathias Shaw zurück, damit Ihr neue Truppen zugeteilt bekommt.", progress = "Willkommen, {race}.", completion = "Das Tor ist frei! Sobald Eure Leute durch den Canyon hindurch sind, werden wir mit Euren Anführern über den nächsten Schritt sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28111] = { id = 28111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am Azurschacht", description = "Die Produktivität unserer Spinnenfarm am Azurschacht hat einen Stillstand erreicht. Hauptmann Keyton hat uns darum gebeten, sofort Hilfe zu schicken. Keyton behauptet, dass die Minenspinnen sich weigern, Befehlen zu gehorchen, und durchdrehen. Außerdem plündert eine Gruppe Küstenmurlocs unsere Vorräte. Könnt Ihr dort hinuntergehen und den Sachen nachgehen? Helft Keyton und dem Spinnenhändler, {name}.\n\nIhr findet den Azurschacht im Südosten in der Nähe der Küste.", sourceObjective = "Meldet Euch bei Hauptmann Keyton am Azurschacht im Vorgebirge des Hügellands.", completion = "Wir stecken ein wenig in der Klemme, {class}. Die Spinnen von Sarus werden ein wenig dreist, weil wir sie seit Tagen nicht füttern konnten. Wenn wir fortgehen, werden die Murlocs unseren Außenposten übernehmen! Schlimmer noch, Aufseher Stillwasser drüben an den Schlickfeldern verlangt, dass wir ihm noch mehr Menschen schicken! Er ist unersättlich! Wir brauchen Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[28112] = { id = 28112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus der Verlorenen Stadt", description = "Alles ist bereit! Löst meine Ketten und befreit Eure Freunde.\n\nWir müssen uns beeilen, bevor der Neferset-Abschaum bemerkt, dass wir etwas vorhaben!\n\nWenn wir es schaffen, begebt Euch zu meinem Bruder, König Phaoris, für eine Belohnung.", sourceObjective = "Befreit Prinz Nadun und sprecht mit König Phaoris in Ramkahen in Uldum.", completion = "Es stimmt also? Ein Außenstehender hat Prinz Nadun vor den Neferset gerettet? \n\nWir stehen wirklich in Eurer Schuld, Fremder.", sourceObjectiveStatus = "unverified-source-field" }
quests[28113] = { id = 28113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unzerstörbare zerstören", description = "Mit der Klaue sind wir bereit, die Verteidigung der Jadefeuersatyrn zu durchbrechen.\n\nBegebt Euch in die Ruinen im Nordwesten. Hinter der Frontlinie der Satyrn werdet Ihr einen engen Pfad finden, der zu ihrem verderbten Mondbrunnen führt. Eine riesige Wand aus dämonischen Flammen blockiert den Pfad, aber die Klaue des Tichondrius sollte sie bannen können.\n\nHinter der Barriere findet Ihr den Anführer dieser Streitkräfte, Xavathras, der den verderbten Mondbrunnen bewacht. Tötet ihn, sobald Ihr das Hindernis überwunden habt!", sourceObjective = "Tötet Xavathras.", completion = "Seht Ihr, was man mit ein bisschen Zusammenarbeit erreichen kann?\n\nIch werde dafür sorgen, dass die Klaue Leuten übergeben wird, die genug Verantwortungsbewusstsein haben, um so etwas aufzubewahren... das heißt, sofern sie nicht zerstört werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[28114] = { id = 28114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großartige Ernte", description = "Genau südöstlich vom Südwachttor findet Ihr unsere Operation zur Zähmung von Spinnen. Im Laufe der Jahre haben wir eine enge Verbindung zu Spinnen des Hügellandes aufgebaut und haben es geschafft, die hübschen kleinen Tierchen zu zähmen und zu züchten. Jetzt sind die Spinnen für uns normale Haustiere und Nutztiere für den Kampf! Es sind so vielseitige Kreaturen!\n\nIhr müsst für mich auf die Felder im Südosten gehen und vorsichtig Eier einsammeln, die in Bären ausgebrütet werden. Liefert die Ernte bei Sarus an der Mine ab.", sourceObjective = "Sammelt 60 Krabblereier ein.", progress = "Habt Ihr meine Ernte mitgebracht?", completion = "Wunderbar! Nun müssen diese Eier nur noch in eine hübsche, dunkle Nische innerhalb der Mine gelegt werden und dann kann das Wunder des Lebens geschehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28115] = { id = 28115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Zenit überschritten", description = "Bären sind seelenlose Tiere, die auf diese Welt gesetzt wurden, um uns zu quälen. Nur dem Einfallsreichtum der Verlassenen haben wir es zu verdanken, dass wir einen Weg gefunden haben, um die Bären nutzbar zu machen, damit sie einem Zweck dienen! Wir benutzen die Bären auf unserer Spinnenfarm als lebendige Nährquellen für die Eier. Unsere Spinnen legen ihre Eier in das Fleisch der Bären und die Eier ernähren sich von dem Fleisch und dem Blut der Tiere.\n\nNachdem sie ihren Zweck erfüllt haben, müssen die Monster eingeschläfert werden. Reist nach Südosten und tötet die infizierten Bären, die ihren Lebenszenit überschritten haben.", sourceObjective = "Tötet 8 infizierte Bären.", completion = "Die Bärengötter sind grausame Herren. Sie werden diese Welt weiterhin bis ans Ende aller Tage mit Bären bevölkern. Es ist unser Recht als zivilisierte Menschen, uns diese Plagegeister zunutze zu machen - zum Nutzen aller!", sourceObjectiveStatus = "unverified-source-field" }
quests[28116] = { id = 28116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klageveilchen", description = "Wir müssen uns sorgfältig vorbereiten, bevor wir Jaedenar angreifen. Die Magie der Hexenmeister und Dämonen in Jaedenar ist stark und wir werden unsere eigenen Schutzzauber benötigen, bevor wir hineingehen.\n\nWir benötigen nur noch eine letzte Zutat: Klageveilchen, die in den Hügeln nordwestlich des feindlichen Lagers wachsen.\n\nSammelt die Klageveilchen und trefft Euch dann mit meinem Feldassistenten. Er wird Euch sagen, was als nächstes zu tun ist.", sourceObjective = "Sammelt 8 Klageveilchen.", progress = "Habt Ihr die Klageveilchen schon finden können, {name}? Wir brauchen sie so schnell es geht.", completion = "Wunderbar. Greta hat eine weise Entscheidung getroffen, als sie Euch gebeten hat, diese Aufgabe zu übernehmen. Ich werde die Kräuter umgehend verarbeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[28117] = { id = 28117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tiefen säubern", description = "Wie schön, Euch zu sehen, {name}. Jetzt da wir Tol Barad eingenommen haben, fängt die Schlacht erst an.\n\nGleich östlich von hier haben wir einen Zellenblock entdeckt, den Ihr ausräumen müsst. Er steckt zum Bersten voll mit Geistern, die seit Ewigkeiten dort eingesperrt sind.\n\nBeseitigt so viele wie möglich und meldet Euch dann bei mir.", sourceObjective = "Ihr habt den Auftrag, 9 Geister beliebigen Typs in den Verfluchten Tiefen gleich östlich der Baradinfestung zu töten.", completion = "Ihr seid lebendig davongekommen? Ihr seid stärker als ich es bin, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28118] = { id = 28118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Erzmagier", description = "Seit wir auf Tol Barad gelandet sind, versuchen wir, den Zellenblock in den Verfluchten Tiefen auszuräumen. Jedes Mal, wenn wir uns nähern, taucht dieser Erzmagier auf und drängt uns zurück.\n\nJetzt, da wir die Insel eingenommen haben, ist es an der Zeit, es noch einmal zu versuchen. Begebt Euch dorthin und bringt mir seinen Stab zum Beweis, dass Ihr den Auftrag erledigt habt.", sourceObjective = "Ihr müsst Erzmagier Galus töten und mit seinem Stab aus den Verfluchten Tiefen östlich der Baradinfestung zurückkehren.", progress = "Konntet Ihr den Erzmagier beseitigen?", completion = "Galus ist tot? Fantastische Arbeit, {name}. Jetzt können wir die Putzkolonne dort hinunterschicken und den Zellenblock für neue Gefangene vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28119] = { id = 28119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinheit aus Verderbnis", description = "Die Blumen, die Ihr mir gebracht habt, waren die Hauptzutat.\n\nSchutzbarrieren umgeben die Schattenfeste und werden von dämonischen Kohlenpfannen aufrechterhalten. Wenn wir den Schattenrat aus dem Teufelswald vertreiben wollen, müssen diese Kohlenpfannen erlöschen.\n\nDiese Phiole enthält Klageveilchen und die Magie der Wildnis. Füllt sie am verderbten Mondbrunnen im Zentrum von Jaedenar und kehrt zu mir zurück.", sourceObjective = "Füllt die leere Feldflasche mit Wasser aus dem verderbten Mondbrunnen im Zentrum von Jaedenar.", progress = "Habt ihr das Wasser aus dem verderbten Mondbrunnen?", completion = "Das reicht vollkommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28120] = { id = 28120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Vergangenheit lernen", description = "Jetzt, da wir auf dieser elenden Insel endlich Fuß gefasst haben, können wir Untersuchungen beginnen, wie sie in diesen Zustand geraten ist. Einige unserer Truppen haben Tagebücher am Eingang zum Zellblock östlich von hier in den Verfluchten Tiefen entdeckt.\n\nDiese Tagebücher sind für unsere ältesten Schreiber im Basislager von besonderem Interesse. Ihr müsst vier von den Tagebüchern finden und so schnell Ihr könnt zu mir zurückbringen.\n\n{name}, seid vorsichtig dort unten, da wimmelt es nur so vor Untoten.", sourceObjective = "Man hat Euch gebeten, vier verstaubte Gefängistagebücher aus den Verfluchten Tiefen östlich der Baradinfestung zu bergen.", progress = "Konntet Ihr die Tagebücher bergen? Berichten zufolge wurden sie sowohl innerhalb, als aus auch außerhalb der Zellen dort unten gesehen.", completion = "Diese Tagebücher sind in ausgezeichnetem Zustand, {name}. Wir werden sofort anfangen, sie zu entschlüsseln. Nur die Zeit wird zeigen, welche Geheimnisse sie bergen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28121] = { id = 28121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streitkräfte von Jaedenar", description = "Der Schattenrat hält die Verderbnis dieser Lande aufrecht. Bei Jaedenar im Nordwesten verehren sie die Dämonen der Brennenden Legion und arbeiten daran, den Weg für die Rückkehr ihrer Herren in diese Welt vorzubereiten.\n\nDas Gebiet wird von Hunden, Wächtern, Adepten und Kultisten von Jaedenar patrouilliert - Schlägern, die die Augen für die noch boshafteren Streitkräfte unter ihnen offenhalten. Sie werden die ersten sein, die sterben, damit diese Wälder nicht länger leiden müssen.", sourceObjective = "Tötet 12 Soldaten von Jaedenar.", completion = "Gut, {name}! Jetzt, da ihre Zahlen zurückgehen, können wir bald unseren Angriff auf ihre Truppen tief in der Schattenfeste starten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28122] = { id = 28122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein riesiges Problem", description = "Endlich haben wir diesen gottverdammten Fels eingenommen und dann treibt so ein riesiger Ettin hier sein Unwesen und schaltet unsere Wachpatrouillen aus!\n\n{name}, trommelt ein paar Verbündete zusammen und erledigt den Ettin. Wir können nicht zulassen, dass die Bestie hier alles verwüstet.\n\nSeid auf der Hut, von der Front wird gemeldet, dass er mit einem riesigen Baum bewaffnet ist. Und er hat keine Skrupel, ihn einzusetzen.", sourceObjective = "Ihr wurdet beauftragt, Problim zu töten, einen Riesenettin, der die Wege von Tol Barad unsicher macht.", completion = "Ihr habt ihn tatsächlich getötet?! Ich kann es kaum glauben!", sourceObjectiveStatus = "unverified-source-field" }
quests[28123] = { id = 28123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dämonenkette", description = "Narkrall hat mir das Geheimnis seines Einflusses über die Drachen in dieser Gegend verraten. Ich dachte, die Dämonenkette wäre ein Mythos, aber er hatte sie die ganze Zeit.\n\nUnd jetzt ist der Narr dabei, sie zu verlieren.\n\nSein Leben bedeutet mir nichts, aber die Drachenmalorcs können es sich nicht leisten, das Artefakt zu verlieren. Folgt ihm nach Norden zu Donnermar. In der Stadt wird Chaos herrschen, also könnt Ihr vielleicht unbemerkt landen. Kehrt mit der Dämonenkette zu mir zurück, selbst, wenn Ihr sie Narkralls Leiche entreißen müsst.\n\nFindet das Artefakt, {name}.", sourceObjective = "Bringt die Dämonenkette an Euch.", progress = "Habt Ihr sie? Ja? Das Schicksal Drachenmals hängt von der Dämonenkette ab.", completion = "<Zaela nimmt die blutbespritzte Kette und wickelt sie um ihre Hand und ihr Handgelenk.>\n\nWenn die Geschichten wahr sind, {name}, war es diese Kette, an der Todesschwinge einst die Dämonenseele angebunden hatte, die nach seinem Befehl erschaffen worden war, um die anderen Drachenschwärme unter seine Kontrolle zu bringen. Die Dämonenseele wurde bereits vor langer Zeit zerstört, aber vielleicht enthält dieser Klumpen Elementiumerz noch Reste dieser Kraft...\n\nIhr habt heute Großes geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28124] = { id = 28124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter zum Bollwerk", description = "{name}, als sich die Wyverlinge um den Himmelsmeister gekümmert haben, kam Lakota Windweise vorbei. Sie sagte mir, sie möchte Euch in Schattenbollwerk treffen, östlich von hier.\n\nIch glaube, Magatha Grimmtotem wird dort festgehalten.", sourceObjective = "Sprecht mit Lakota Windweise in Schattenbollwerk in Tausend Nadeln.", completion = "Ich bin froh, dass Ihr kommen konntet.\n\nKümmert Euch nicht um mein Aussehen. Es schien weise, meine Kleidung entsprechend anzupassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28125] = { id = 28125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was zum Anziehen", description = "Ich habe eine Idee, wie wir Euch in die Nähe der Anführer bekommen können, ohne dass man Euch gleich tötet. Zuerst braucht Ihr aber etwas zum Anziehen.\n\nIch schlage vor, dass Ihr von dort vorne eine ihrer Rüstungen schnappt.", sourceObjective = "Sammelt 10 Teile Schattenhammerrüstungen.", progress = "Wie viele Rüstungsteile konntet Ihr finden?\n\nFür Eure nächste Aufgabe solltet Ihr wirklich gut verkleidet sein.", completion = "<Lakota sieht über den Zustand der Rüstung besorgt aus, besonders über die vielen Blutflecken.>\n\nIhr habt auch wirklich sorgfältig geschaut, {name}? Naja, das wird reichen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28126] = { id = 28126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flammen des Schutzes ersticken", description = "Die Kohlenpfannen sind überall in der Schattenfeste verteilt.\n\nBetretet den Tunneleingang zur Schattenfeste und folgt den unterirdischen Korridoren. Löscht jede einzelne Flamme der Kohlenpfannen und der Schutz, den der Rat eingerichtet hat, wird für mindestens eine Weile zusammenbrechen.", sourceObjective = "Benutzt das gereinigte Wasser aus dem Mondbrunnen, um die vier Kohlenpfannen des Schutzes in der Schattenfeste zu löschen.", completion = "Jetzt, da die Kohlenpfannen gelöscht sind, können die Druiden des Smaragdkreises die Schattenfeste betreten und die restlichen Kultisten beseitigen. Mit der Zeit kann dieser Ort vielleicht wieder als der Grabhügel genutzt werden, der er einst war.\n\nIhr habt meinen Dank, {name}. Bitte, nehmt diese Belohnung an.", sourceObjectiveStatus = "unverified-source-field" }
quests[28127] = { id = 28127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brecht sie aus", description = "Magatha ist nicht die einzige Gefangene des Schattenhammers.\n\nWährend Ihr in ihrem Lager im Süden seid, solltet Ihr so vielen wie möglich beim Ausbruch helfen.", sourceObjective = "Rettet 5 Bollwerkgefangene von den Zwielichtkerkermeistern.", completion = "Ihr gebt so viel, ohne etwas zurückzuverlangen.\n\nDie Bevölkerung von Tausend Nadeln ist dankbar, und ich bin es auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28128] = { id = 28128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der innere Kreis", description = "Jetzt, da ihre äußeren Wächter fort sind, sind die höheren Mitglieder des Schattenrates dran.\n\nTief in den verderbten Grabhügeln findet Ihr mächtige Hexenmeister, Jäger, Vollstrecker, Dunkelwirker und Legionäre von Jaedenar.\n\nSie müssen besiegt werden, wenn diese Lande gerettet werden sollen!", sourceObjective = "Tötet 12 Verteidiger in der Schattenfeste.", completion = "Die Säuberung der Schattenfeste wird lange dauern und viel Anstrengung erfordern, aber ohne Euren Sieg gegen den Schattenrat, wäre sie überhaupt nicht möglich. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28129] = { id = 28129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dämonenprinz", description = "Die Jadefeuersatyrn, die so viel vom Teufelswald überrannt haben, arbeiten direkt mit dem Schattenrat zusammen.\n\nDiese Satyrn sind direkt dem uralten und mächtigen Prinz Xavalis unterstellt. Einige sagen, er ist der Sohn von Xavius, dem ersten Satyr, und von Sargeras höchstpersönlich gesegnet. \n\nEgal, welchen Ursprungs er ist, er muss sterben, wenn wir die Satyrn der Jadefeuerregion zerschlagen und unsere Grabhügel zurückerobern wollen. Begebt Euch tief in die Schattenfeste und tötet ihn. Gewährt ihm keine Gnade, denn auch er wird Euch keine gewähren.", sourceObjective = "Tötet Prinz Xavalis.", sourceObjectiveStatus = "unverified-source-field" }
quests[28130] = { id = 28130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht die freundlichste Stadt", description = "Seid Ihr schon oben in Rostberg gewesen, {name}? Ich schlage vor, dass Ihr eine scharfe Klinge bei Euch tragt, wenn Ihr in die Richtung geht.\n\nDie Bewohner dieser Stadt sehen ganz in Ordnung aus, aber da geht irgendwas Verdächtiges vor. Wir haben Berichte erhalten, dass sie unsere Soldaten vorne und hinten wegfangen. Wir haben allmählich die Nase voll davon, deshalb müsst Ihr für uns dorthin gehen und ein bisschen aufräumen.\n\nErledigt so viele von ihnen wie Ihr könnt, und meldet Euch dann wieder bei mir, wenn Ihr fertig seid.", sourceObjective = "Kommandant Marcus Johnson hat Euch gebeten, 14 Dorfbewohner in Rostberg zu töten. Rostberg befindet sich nördlich des Basislagers auf der rechten Seite.", completion = "Ich habe Euch ja gesagt, dass das Dorf voller Irrer ist. Aber Ihr habt gut dort aufgeräumt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28131] = { id = 28131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelte Versuchung", description = "Moora und Salia sind die persönlichen Dienerinnen von Schattenlord Fel'dan. Lasst Euch nicht von ihnen in die Irre führen!\n\nDiese widerwärtigen Sukkuben benutzen Listen und finstere Magie, um Sterbliche tief in die Schattenfeste zu locken. Diejenigen, die in ihre Fänge geraten, erhalten eine Gehirnwäsche oder werden von Fel'dan seinen dämonischen Herren geopfert.\n\nDie beiden kämpfen wie aus einem Guss und sind unzertrennlich, was sie zu einer erheblichen Bedrohung macht. Geht tiefer in die Schattenfeste und tötet sie.", sourceObjective = "Tötet Moora und Salia.", sourceObjectiveStatus = "unverified-source-field" }
quests[28132] = { id = 28132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Effiziente Ausgrabungen", description = "Dieses Handbuch beschreibt absonderliche Theorien, wie man große Arbeitergruppen wirksam einteilt, wenn sie mit gewaltigen Ausgrabungsprojekten beschäftigt sind.\n\nNachdem Ihr den Inhalt überflogen habt, wird Euch klar, dass der Verfasser des Buchs die Person sein muss, die für die übermäßig aggressiven Plünderer hier verantwortlich ist.\n\nEine Karte auf der Rückseite des Umschlags zeigt, dass der Verfasser einen Bunker in der südwestlichen Region von Uldum besitzt.\n\nVielleicht wäre es angebracht, sich einmal vorzustellen.", sourceObjective = "Bringt 'Effiziente Ausgrabungen' zu Bellok Leuchtklinge in Schnottz' Landeplatz.\n\nBereitgestellter Gegenstand:", completion = "Sieh mal an, es ist eines von Schnottz' Pamphleten.\n\nIch werde das mal an mich nehmen, wenn Ihr nichts dagegen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28133] = { id = 28133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbändige Wut", description = "Narkralls Drache Torth hat den vergeblichen Angriff auf Donnermar überlebt und jetzt ist die Kreatur von ihrem früheren Herrn befreit.\n\nTorth will sich an dem Drachenmalklan rächen und hat die Blutschlucht bereits einmal bombardiert. Er wird solange wiederkommen, bis wir ihn endgültig aufgespießt haben. Es wird Zeit, dass wir die Dämonenkette einsetzen.\n\nTorths altes Nest ist eine kleine Höhle in den Hügeln westlich von hier. Dort haben wir ein kleines Lager names \"Der Rachen\" aufgeschlagen.\n\nTrefft mich am Rachen und wir werden Torth erledigen.", sourceObjective = "Reist zum Rachen und sprecht mit Zaela. Tötet Torth.", completion = "Einmal frei von der Kette, starb Torth lieber, als sich noch einmal unterwerfen zu lassen. Ich bewundere die Kreatur. Ich werde aus seiner Haut einen Rüstungssatz herstellen lassen.\n\nSo viel weiß ich jetzt: Der Drachenmalklan kann allein nichts ausrichten, wenn die Allianz sich hinter die Wildhämmer stellt. Narkrall hat das bewiesen. Und Ihr habt die Macht der Horde immer wieder unter Beweis gestellt.\n\nIch werde unsere Drachengeschwader neu aufbauen und außerhalb der Bastion des Zwielichts Position beziehen. Ihr solltet weiterhin hier im Rachen und anderswo im Hochland aushelfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28134] = { id = 28134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevorstehende Vergeltung", description = "Jetzt, da Ihr angemessen belohnt worden seid, kann ich hoffentlich offen mit Euch sprechen.\n\nIhr habt meinem Königreich einen großen Gefallen erwiesen, aber Ihr habt auch einen zerbrechlichen Friedensprozess aus dem Gleichgewicht gebracht.\n\nIch habe versucht, die Freilassung meines Bruders auf rein diplomatischem Wege zu erreichen, um Blutvergießen zu vermeiden.\n\nJetzt wird der Feind sicherlich zurückschlagen wollen.\n\nSprecht mit Nomarch Teneth an den Tahretgründen im Osten, mit Sonnenpriester Asaris am Siegel des Sonnenkönigs im Norden und mit Asaq in Mar'at im Westen. Findet heraus, wann der Feind zuschlagen wird.", sourceObjective = "Sprecht mit Nomarch Teneth an den Tahretgründen, mit Sonnenpriester Asaris am Siegel des Sonnenkönigs und mit Asaq in Mar'at.", completion = "Orsis! Natürlich!\n\nWie konnte ich das übersehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[28135] = { id = 28135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Al'Akirs Rache", description = "Hört zu, {name}. Orsis wurde nicht von einem natürlichen Sandsturm getroffen. Das waren die Helfer von Al'Akir.\n\nDer Elementarlord der Luft ist fest mit Todesschwinge verbündet und es war nur eine Frage der Zeit, bevor er seine Untergebenen auf meine Leute hetzte.\n\nOrsis wurde als Warnung für uns angegriffen. Wir müssen uns beeilen und unseren Brüdern jede erdenkliche Hilfe anbieten.\n\nTrefft Euch mit Nadun am Handelsposten Arsad außerhalb von Mar'at. Ich werde Vorbereitungen treffen, damit wir uns um die Versprengten und Verwundeten kümmern können.", sourceObjective = "Sprecht mit Prinz Nadun am Handelsposten Arsad außerhalb von Mar'at in Uldum.", completion = "Seht Ihr, was Todesschwinges Helfer angerichtet haben? Das große Orsis ist jetzt beinahe vollkommen von Sand bedeckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[28136] = { id = 28136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter Euch!", description = "Die drei Anführer Schattenbollwerks sind mächtig und Ihr solltet sie nicht unterschätzen, {name}. Glücklicherweise seht Ihr mit Eurer Verkleidung aus wie ein Schattenhammerkultist.\n\nTragt Eure Verkleidung und sprecht mit Chiffrenmeister Deethuk, Kommandant Luntenschnell und Elementarist Starion getrennt voneinander. Wartet, bis sie Euch den Rücken zuwenden und führt Euren Angriff dann schnell aus!", sourceObjective = "Ermordet Chiffrenmeister Deethuk, Kommandant Luntenschnell und Elementarist Starion.", completion = "Jetzt, da die drei ausgeschaltet sind, sollten die vereinten Streitkräfte Freinwindpostens mit dem Rest der Kultisten hier alleine fertig werden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28137] = { id = 28137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrt einen hungrigen Mann das Fischen... oder das Stehlen", description = "Rostberg. Dieser Ort ist für uns Fluch und Segen, {name}. Ich habe keine Ahnung, wo die Banditen so gut Fischen gelernt haben, aber ich habe jetzt keine Zeit, mir darüber Sorgen zu machen.\n\nIhr müsst Euch dort hinunter begeben und so viele Ihrer Fischvorräte stehlen, wie möglich. Wir leben von Küchenabfällen, seit wir die Insel zurückerobert haben und dies ist die beste Gelegenheit für uns, an vernünftige Essensvorräte zu kommen.\n\nAchtet auf die Verstohlenen dort oben, Berichten zufolge befinden sie sich hauptsächlich innerhalb der Stadtmauern.", sourceObjective = "Ihr müsst 22 Rostbergseebarsche aus Rostberg stehlen. Die Fische befinden sich an Fäden aufgehängt auf Ständern bei den Docks im hinteren Teil des Dorfes. Rostberg befindet sich nördlich des Basislagers auf der rechten Seite.", progress = "Ist Euch der Überfall gelungen und habt Ihr uns Fisch besorgt?", completion = "Diese Fische sind genau das, was wir brauchen, {name}. Sie werden die Truppen ernähren und in guter Verfassung halten und das ist unser wichtigstes Anliegen. Ihr habt Euch wirklich für uns eingesetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28138] = { id = 28138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Menschenbefall", description = "Diese Mine war einst das Herzstück des Bergbaus der Allianz im Hügelland. Jetzt dient sie als Brutstätte für unsere getreuen Spinnen, obwohl die Menschen sie immer noch in gewisser Weise besetzt halten.\n\n<Keyton grinst.>\n\nAber lasst uns zum Geschäft kommen! Aufseher Stillwasser hat um weitere Arbeiter für die Schlickfelder gebeten. Ich möchte, dass Ihr die Mine mit diesen Fußfesseln betretet und Menschen des Hügellands für die Arbeit auf den Feldern gefangennehmt.\n\nHolt sie aus ihrer Netzlähmung und schlagt sie, bis sie sich ergeben, bevor Ihr ihnen die Fußfesseln anlegt.", sourceObjective = "Nehmt 8 Menschen des Hügellands gefangen.", completion = "Die sind genau richtig. Ich frage mich, was der Aufseher mit ihnen vorhat. Das Letzte, was ich gehört habe, war, dass die Schlickfelder von furchtbaren Dingen überrannt worden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28139] = { id = 28139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Code des Chiffrenmeisters", description = "{name}, Magatha wird mit speziell verschlüsselten Fesseln festgehalten. Wir können sie nur befreien, wenn wir den Code besorgen können.\n\nChiffrenmeister Deethuk in Schattenbollwerk südöstlich von hier hat eine Chiffriermaschine. Die Codes sind darin gespeichert.\n\nBesorgt sie!", sourceObjective = "Erhaltet den Code des Chiffrenmeisters.", progress = "Habt Ihr den Code, um die Fesseln der Ältestengreisin lösen zu können?", completion = "Gut. Jetzt gibt es nur noch eine Sache, um die wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28140] = { id = 28140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ältestengreisin", description = "Ihr habt den Code. Jetzt müsst Ihr nur noch in den südlichen Teil des Bollwerks und die Ältestengreisin befreien.\n\nViel Erfolg, {name}. Ich danke Euch für alles, was Ihr bisher für uns getan habt.", sourceObjective = "Deaktiviert das Steuergerät für Magathas Fesseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[28141] = { id = 28141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte des Sonnenkönigs", description = "Das Siegel des Sonnenkönigs dient als Verteidigungsmechanismus für Ramkahen.\n\nAls die Barriere um Uldum fiel, sahen wir, wie die Vorhut der Wüstenläufer aus Tanaris unsere Grenzen überschritt.\n\nSie griffen diese heilige Stätte auf ihrem Weg in den Westen an und raubten die Relikte, die ihr einst ihre Macht verliehen.\n\nHolt die Relikte für uns zurück. Ohne sie sind wir machtlos und können uns nicht gegen ihre Angriffe aus der Wüste verteidigen.", sourceObjective = "Beschafft 4 Relikte des Sonnenkönigs.", progress = "Hattet Ihr Erfolg?", completion = "Danke. Die Gerüchte, die ich über Euch gehört habe, erweisen sich doch als wahr.", sourceObjectiveStatus = "unverified-source-field" }
quests[28142] = { id = 28142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Ödnis", description = "Magatha hat gesagt, sie werde Euch außerhalb von Schattenödnis östlich von hier treffen.", sourceObjective = "Sprecht mit Magatha Grimmtotem in Schattenödnis in Tausend Nadeln.", completion = "Ihr habt lange gebraucht. Meint Ihr, wir sind zum Spaß hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[28143] = { id = 28143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Ödnis", description = "Ihr solltet die Ältestengreisin nicht warten lassen.\n\nSie sagte, dass sie Euch außerhalb der Anhöhung von Schattenödnis östlich von hier treffen wird.", sourceObjective = "Sprecht mit Magatha Grimmtotem in Schattenödnis in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[28144] = { id = 28144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische kleine Monster!", description = "Das lange Stück Küste direkt südlich unseres Standortes, das sich von Westen nach Osten erstreckt, ist bekannt als der Weststrand. Entlang des Weststrands findet Ihr zwei Dinge: Murlocs und gestohlene \"Vorräte\".\n\n<Keyton streckt seine Hände in die Luft und macht das Zeichen für Anführungsstriche mit seinen Fingern.>\n\nDiese verdammten diebischen Murlocs haben hinter unserem Rücken zugeschlagen und unsere \"Vorräte\" gestohlen.\n\nSarus und ich können diesen Posten nicht verlassen. Ihr müsst für uns zum Weststrand gehen und diese \"Vorräte\" wiederbeschaffen!", sourceObjective = "Bergt 6 \"Vorräte\" des Lagers der Verlassenen.", progress = "Bringt unsere \"Vorräte\" zurück, {name}!", completion = "Wenigstens werden wir auf zukünftige Vorfälle vorbereitet sein. \"Vorräte\" wie diese zu bewegen ist ein riskantes Vorhaben. Man weiß nie, wer meint, seine große Klappe aufreißen zu müssen.\n\n<Keyton zieht das, was man für eine Augenbraue halten könnte, hoch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28145] = { id = 28145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenmittel für Giftblut", description = "Iset hat versucht, diesen heiligen Boden gegen die Banditen der Wüstenläufer zu verteidigen, als sie ihn geplündert haben.\n\nAnscheinend haben sie ein starkes Gift verwendet, das von Giftblutskorpiden stammt.\n\nNehmt diese Phiole und sammelt Gift aus ihren Kadavern, damit ich ein Gegenmittel herstellen kann. Ich fürchte, Iset bleibt nicht mehr viel Zeit.", sourceObjective = "Füllt die Gegengiftphiole mit dem Gift von 8 Giftblutskorpidkadavern.", completion = "Danke, {name}. Vielleicht können wir Iset doch noch retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28146] = { id = 28146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delikatessen der Küste!", description = "Meine Spinnen sind hungrig und aufgebracht! Sie haben seit Tagen nichts zu fressen bekommen und beginnen, unsere menschlichen Gefangenen anzuknabbern. Das geht so nicht. Wir brauchen diese Menschen, damit sie in den Schlickfeldern arbeiten.\n\nIch möchte, dass Ihr eine meiner hungrigen Minenspinnen mit hinausnehmt und ihr Murlocs vom Weststrand südlich von hier zum Fraß vorwerft. Sie wird fressen, was immer Ihr tötet! Je mehr, desto besser!", sourceObjective = "Füttert die hungrige Minenspinne mit 12 Murlocs vom Weststrand.", completion = "Das sollte sie für ein paar Tage glücklich und zufrieden machen. Ihr habt da gute Arbeit gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28147] = { id = 28147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lila ist Eure Farbe", description = "Soweit ich das sagen kann, haben sich die Stopfwampenoger direkt vor der Höhle hier noch nicht dem Schattenhammer angeschlossen. Wenn wir schlau sind, können wir die beiden Gruppierungen gegeneinander ausspielen.\n\nLasst uns mit einem kleinen Trick beginnen, den ich in Silithus gelernt habe. Zunächst müssen wir für Euch einen Satz Kultistenroben zusammenbekommen.\n\nBegebt Euch nach Süden und tötet einige Zwielichtwindwirbler im Schattenriss. Abgesehen davon, dass wir sie bei dem, was sie tun, stören, bietet sich Euch die Chance, Gewandungsfetzen zu sammeln.", sourceObjective = "Hebt 8 Zwielichtkleidungsfetzen auf.", progress = "Das ist gut, {name}. Mit Helden wie Euch, die da draußen für Unruhe sorgen, werden wir den Kult von unserer Hauptinvasion ablenken.\n\nHabt Ihr eine Verkleidung?", completion = "Was habt Ihr bekommen? Ich denke, daraus können wir etwas zusammenflicken.\n\nSchließlich wollt Ihr dem Kult nicht beitreten. Wir müssen nur ein paar Oger täuschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28148] = { id = 28148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbten erlegen", description = "Die abscheuliche Verderbnis der Dämonen durchzieht den gesamten Wald. Die Erde, die Bäume, die Tiere... alle tragen die teuflische Magie in sich.\n\nWir vom Smaragdkreis haben geschworen, diesen Wald zu läutern. Das aber bedarf eines ständigen Kampfes. Vieles kann noch geheilt werden - die Bären und Wölfe jedoch, die in der Nähe umherstreifen, sind bereits zu verderbt.\n\nWir müssen ihr Leiden beenden und sicherstellen, dass Ihre Kadaver die Verderbnis nicht noch weiter verbreiten. Jagt sie und bringt mit ihre Bälge.", sourceObjective = "Sammelt 10 verderbte Pelze von Wutklauenbären oder Teufelspfotenwölfen.", progress = "Ich muss die Pelze haben, um sie von der verbliebenen dämonischen Essenz zu säubern.", completion = "Ich werde dafür sorgen, dass sie schnell und sicher verbrannt werden, {name}. Ich danke Euch vielmals.", sourceObjectiveStatus = "unverified-source-field" }
quests[28149] = { id = 28149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern im Wind", description = "Hört Ihr das, {class}? Stimmen aus der Höhle. Sie woll'n reden, aber sie ham keinen Atem.\n\nLasst uns 'ne Möglichkeit finden, zuzuhören. Die vom Schattenhammer, die reden mit dem Wind. Geht zum Schattenriss südlich von hier und holt den Windsprecherglücksbringer vom Lager. Er ist oben auf 'ner Steinsäule.\n\nWir brauchen auch Atem von Elementaren! Tötet die Sturmvortex und nehmt Euch, was Ihr braucht.", sourceObjective = "Beschafft einen Windsprecherglücksbringer und 5 Vortexhauche.", progress = "Pschscht, {name}! Hört mal. Hört mal...", completion = "Das isses, Mann.\n\nHört Ihr sie jetzt? Die Geister, sie sprechen, aber sie sagen nix gutes.\n\nHolen wir sie ans Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28150] = { id = 28150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein arkaner Verbündeter", description = "Der Smaragdkreis hat geschworen, die Hilfe aller anzunehmen, welche die Dämonen des Teufelswalds zu bekämpfen wünschen. Obwohl die arkanen Künste bei meinem Volk lange verpönt waren, können wir uns einen derartigen Vorteil hier nicht versagen.\n\nArkanistin Delaris, eine überlebende Magierin der Hochgeborenen, hilft uns im Kampf gegen die Jadefeuersatyrn. Folgt der Straße nach Norden und Ihr findet sie in unserem Lager, das die Ruinen von Constellas überblickt.\n\nWenn es Euer Wunsch ist, bei der Läuterung des Teufelswalds mitzuwirken, erfüllt ihre Wünsche, wie ihr meine erfüllt habt.", sourceObjective = "Sprecht mit Arkanistin Delaris bei den Ruinen von Constellas.", completion = "Wir haben nicht viel Zeit für Unterhaltungen, {class}. Die Druiden kämpfen tapfer gegen die Satyrn, aber teuflische Magien versperren ihnen den Weg.\n\nZum Glück habe ich einen Plan...", sourceObjectiveStatus = "unverified-source-field" }
quests[28151] = { id = 28151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todschick", description = "Eure Verkleidung ist fertig, {name}. Wenn Ihr in Zukunft nach Norden zu Stopfwampes Anhöhe geht, werden Eure Schattenhammerabzeichen die Oger täuschen.\n\nDer Rest des Plans ist einfach: Ihr tötet ein paar Stopfwampenoger und sie machen den Kult dafür verantwortlich. Seid Ihr bereit, um in dem Ogercamp Verwirrung zu stiften? Das dachte ich mir.", sourceObjective = "Tötet 10 Stopfwampenoger. Eure Schattenhammerverkleidung wird automatisch angelegt, wenn Ihr auf Stopfwampes Anhöhe seid.", completion = "Ha! Ich bin sicher, dass der Schattenhammer diese Oger zu ihren Rängen zählen wollte. Jetzt müssen sie sich wahrscheinlich gegen sie wehren.\n\nDas ist gut, {name}. Mit einem gut platzierten {class} haben wir es geschafft, die Arbeit einer kleinen Armee zu verrichten. Ich werde Kriegsfürst Krogg über Eure Arbeit hier unterrichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[28152] = { id = 28152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaedenar wartet", description = "Die Kultisten, die Ihr als Wachen der Klaue gesehen habt, waren Mitglieder des Schattenrats - widerliche Hexenmeister, die hinter fast jedem Versuch stecken, Dämonen nach Azeroth zu holen.\n\nNördlich von hier ist Jaedenar, das seinen Namen zu Ehren von Kil'jaeden erhielt. Tief darunter erstreckt sich die Schattenfeste, ein früherer Grabhügel und die Festung des Schattenrats hier auf Azeroth.\n\nBringt diese Kräuter nach Norden zu Wildherzens Lager auf der Ostseite der Straße. Greta Mooshuf wird sie für ihren Plan brauchen, die Schattenfeste endgültig zu säubern.", sourceObjective = "Liefert die Arkanistenkräuter bei Greta Mooshuf in Wildherzens Lager ab.", progress = "Seid gegrüßt, {class}. Was führt Euch her?", completion = "Ah, darauf habe ich gewartet. Mit diesen Kräutern sind die Vorbereitungen für Jaedenar beinahe abgeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28153] = { id = 28153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenlord Fel'dan", description = "Schattenlord Fel'dan wartet noch tiefer drinnen, {name}.\n\nSein Zorn wird unvergleichlich sein, da Ihr seine Lieblinge getötet habt. Doch auch ohne Moora und Salia an seiner Seite ist er eine nicht zu unterschätzende Macht.\n\nHütet Euch vor seinen dunklen Kräften, er ist inzwischen beinahe mehr Dämon als Orc.", sourceObjective = "Tötet Schattenlord Fel'dan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28154] = { id = 28154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matschkiemes Flosse oder so...", description = "Das sieht wie Matschkiemes Flosse oder so was aus. Vielleicht gibt es jemanden, den es kümmert, dass Ihr diesen Murloc im Lager am Azurschacht getötet habt. Vielleicht auch nicht, aber einen Versuch ist es wert.\n\nBringt Matschkiemes Rückenflosse oder was immer es auch sein mag zu Hauptmann Keyton am Azurschacht im südwestlichen Hügelland.", sourceObjective = "Liefert Matschkiemes Flosse bei Hauptmann Keyton am Azurschacht im Vorgebirge des Hügellands ab.", progress = "Seh' ich wie ein Murlocforscher aus?", completion = "Matschkieme sagt Ihr. Nie von ihm gehört. Was ist das hier überhaupt? Eine Art Flosse oder so was?", sourceObjectiveStatus = "unverified-source-field" }
quests[28155] = { id = 28155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Schattenfluch", description = "Jetzt lauert nur noch eine Macht in den Tiefen der Schattenfeste: Lord Schattenfluch.\n\nDer Schattenrat hier ist ihm zu Willen und sogar Fel'dan war nur ein Werkzeug für ihn, um dieses Land für eine weitere Invasion der Brennenden Legion vorzubereiten.\n\nSeid auf der Hut, {name}. Ein Schreckenslord ist ein furchterregender Gegner. Seid standhaft und triumphiert!", sourceObjective = "Tötet Lord Schattenfluch.", completion = "Wirklich unfassbar, {name}. Sich einfach in die Höhle des Löwen zu begeben und jeden Feind zu töten, der sich einem in den Weg stellt... Ich bin überwältigt.\n\nDer Smaragdkreis dankt Euch für Eure Arbeit hier im Teufelswald. Was Andalar betrifft, werde ich Späher zu seiner Rettung entsenden. Wir werden ihm einen Heldenempfang bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28156] = { id = 28156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung aus den Tiefen der Mine", description = "<Ihr hört Kagbuhn durch die Spinnweben hindurch sprechen.>\n\nHEY! ÜBERALL SPINNEN! DER HAUPTMANN HAT MICH GESCHICKT, UM DIE WELT ZU RETTEN UND MENSCHEN ZU FANGEN! WAS IST DAS HIER ÜBERHAUPT FÜR EIN ORT? ES IST SO HEISS HIER! ICH...\n\n<Kagbuhn redet immer weiter über seine Lage.>\n\nVielleicht solltet Ihr ihn befreien und ihn in Sicherheit bringen. Ihr könnt ihn auch hier lassen, obwohl es Eure Schuld ist, dass er hier in der Mine feststeckt.", sourceObjective = "Bringt Kagbuhn in Sicherheit!", completion = "Schon mal was von \"Der Stärkste überlebt\" gehört? Was Ihr da tut, steht in Konflikt mit den Naturgesetzen, mein Lieber! Der Idiot hätte in den Minen sterben sollen. Nicht auszudenken, welchen Schaden er sich oder anderen als nächstes zufügt, jetzt, da Ihr ihn vor seinem unausweichlichen Tod bewahrt habt.\n\nUnd Ihr wisst, wessen Fehler das dann sein wird, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[28157] = { id = 28157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vier Elemente des Schattens", description = "Der Schattenhammer hat eine Monstrosität beschworen. Sie ist eine Mischung der vier Elemente, vereint mit der Macht ihres Sonderelementes Elementium.\n\nIhr müsst sie besiegen, wenn Ihr Euer geliebtes Tausend Nadeln vor der Zerstörung retten möchtet. Zuerst werdet Ihr jedoch ein paar Gegenstände brauchen, um sein Schutzschild zerstören zu können.\n\nÖstlich von hier in der Ödnis könnt Ihr die vier Elemente des Schattenhammers finden. Bringt sie zu mir.", sourceObjective = "Sammelt die vier Elemente des Schattens: Luft, Erde, Feuer, und Wasser.", progress = "Habt Ihr alle Elemente, {name}?", completion = "<Magatha starrt Euch mit purer Verachtung an.>\n\nIch werde sie in eine nützliche Form bringen und es für Euch einfach machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28158] = { id = 28158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbändig", description = "Der Schattenhammer hat zwei sehr mächtige Elemente gebunden. Sie benutzen die gebundene Wut und den Vortex, um dem Animus unfassbare Kraft zu verleihen.\n\nWenn der Animus die Macht aufgesaugt hat, wird er explodieren. Tausend Nadeln und ein Großteil der Nachbarländer werden bei der Explosion ausradiert werden.", sourceObjective = "Löst die gebundene Wut und den gebundenen Vortex.", completion = "Eine einfache Aufgabe für einen einfachen Burschen wie Euch. Wir werden sehen, ob Ihr das Zeug habt, diese Aufgabe zu meistern.", sourceObjectiveStatus = "unverified-source-field" }
quests[28159] = { id = 28159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verdammnisstein", description = "Im Kern des Animus befindet sich ein als Verdammnisstein bekanntes Artefakt. Eine seiner Eigenschaften ist die Absorbtion großer Energien.\n\nSo werden die Kultisten versuchen, die Explosion hervorzurufen... indem sie den Stein überladen und seine Macht durch den Elementar verstärken.\n\nBringt mir den Verdammnisstein. Natürlich nur, um ihn sicher zu verwahren.", sourceObjective = "Erhaltet den Verdammnisstein.", progress = "Habt Ihr den Verdammnisstein, {name}?", completion = "Ich bin überrascht... Ihr habt überlebt.\n\nIch danke Euch, dass Ihr diese dreckige Aufgabe für mich erledigt habt, {name}. Nun habe ich nicht nur die Rassel der Knochen, die Niederschrift der Geschichte und die Trommeln des Krieges, sondern auch das ultimative Artefakt: den Verdammnisstein!", sourceObjectiveStatus = "unverified-source-field" }
quests[28160] = { id = 28160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitet Kunde", description = "Für Eure nützlichen Dienste werde ich Euch dem Tod entgehen lassen. Belasst es dabei und verschwindet aus meiner Sicht. Berichtet Eurem Volk von allem, was geschehen ist.\n\nUnd sollte ich Euch jemals wiedersehen, {name}, so werdet Ihr sterben.", sourceObjective = "Sprecht mit Fizzel Kupferbolz auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", completion = "Wow, die ist böse! Aber was bedeutet das für uns, {name}? Wird Magatha uns zerstören? Führt sie den Schattenhammer an?\n\nEgal, was jetzt passieren wird, Ihr habt uns vor unseren Feinden gewarnt. Bitte, erlaubt mir, Euch meine Dankbarkeit zu zollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28161] = { id = 28161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitet Kunde", description = "Für Eure nützlichen Dienste werde ich Euch dem Tod entgehen lassen. Belasst es dabei und verschwindet aus meiner Sicht. Berichtet Eurem Volk von allem, was geschehen ist.\n\nUnd sollte ich Euch jemals wiedersehen, {name}, so werdet Ihr sterben.", sourceObjective = "Sprecht mit Pozzik auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", completion = "Wow, die ist böse! Aber was bedeutet das für uns, {name}? Wird Magatha uns zerstören? Führt sie den Schattenhammer an?\n\nEgal, was jetzt passieren wird, Ihr habt uns vor unseren Feinden gewarnt. Bitte, erlaubt mir, Euch meine Dankbarkeit zu zollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28162] = { id = 28162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sumpfköder", description = "An solchen Orten ist die Versorgung immer schwer, {class}. Seit wir die Insel eingenommen haben, erkunden wir sie, aber es sieht nicht gut aus.\n\nZum Glück haben wir gerade erfahren, dass sich gleich westlich von unserem Basislager ein Sumpf voller Krokis befindet. Deren Bälge werden unseren Lederern gerade recht kommen. Bringt so viele her wie Ihr nur könnt.", sourceObjective = "Ihr habt den Auftrag, auf Tol Barad 8 Krokiliskenbälge von Krokilisken von Baradin zu besorgen. Die Krokilisken findet Ihr im Sumpf, gleich westlich der Baradinfestung.", progress = "Habt Ihr schon im Sumpf aufgeräumt?", completion = "Sieht aus, als habt Ihr die Krokibälge, die wir brauchen. Danke, {name}, Euer Beitrag wird Euch nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28163] = { id = 28163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überreste", description = "Wir haben hart um diese Insel gekämpft, {race}. Den Großteil des Hordenabschaums haben wir ausgelöscht, aber ihr übler Gestank liegt immer noch in der Luft.\n\nKundschaftet die Erzraffinerie, die Hüterwacht und die Eiserne Garnison aus. Tötet alle angehörigen der Horde, die Ihr findet.\n\nIhr kennt ja das Sprichwort: Nur ein toter Hordler ist ein guter Hordler!", sourceObjective = "Ihr habt den Befehl erhalten, 12 Infanteristen der Horde in Tol Barad zu töten. In der Erzraffinerie, der Hüterwacht und der Eisernen Garnison hier auf Tol Barad sind noch Widerständler zu finden.", completion = "Diese dreckigen Hordler hatten nicht die geringste Chance. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28164] = { id = 28164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Bruder Silberheil", description = "Man hat mir gerade mitgeteilt, dass Ihr in Orgrimmar gebraucht werdet, {name}. Bruder Silberheil hat darum gebeten, dass Ihr so schnell wie möglich zur Stadt zurückkehrt. Seine Nachricht enthielt keine weiteren Informationen, aber es schien dringlich zu sein.\n\nSucht nach Bruder Silberheil in den Goblinslums von Orgrimmar.", sourceObjective = "Sprecht mit Bruder Silberheil in den Goblinslums von Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28165] = { id = 28165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "D-Block", description = "Habt Ihr schon einmal vom D-Block gehört, {name}? Das ist einer der Zellenblöcke hier auf der Insel. Das Problem ist, dass er von Dämonen befallen ist. Wir hatten eigentlich vor, dort die übriggebliebenen Hordler, die wir auf der Insel gefunden haben, einzusperren, aber in seinem momentanen Zustand ist das unmöglich.\n\nIhr müsst dort hinuntergehen und diese Dämonen beseitigen. Meldet Euch wieder bei mir, wenn Ihr fertig seid.", sourceObjective = "Ihr habt den Befehl erhalten, 10 beliebige Dämonen im D-Block nordwestlich der Baradinfestung zu töten.", completion = "Der D-Block ist sauber? Gute Arbeit, {name}. Wir werden sofort eine Putzkolonne dort hinunterschicken, die dort aufräumt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28166] = { id = 28166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thogs Nachtlicht", description = "Wir brauchen ein spezielles Licht, damit wir die Geister sehen können. Ein Licht, das das Innere erleuchtet. Das Licht der Seelen.\n\nSeit dem, was wir ihnen in Hyjal angetan haben, benutzt der Schattenhammer sie, um Verräter aufzuspüren. Sie haben eins den Stopfwampenogern geschenkt.\n\nAn Stopfwampes Anhöhe nördlich von hier findet Ihr den riesengroßen Haudrauf Thog. Der hat 'n Licht der Seelen. Wenigstens wird er das haben, bis Ihr es ihm abnehmt.", sourceObjective = "Holt das Licht der Seelen von Stopfwampes Anhöhe.", progress = "Das Licht der Seelen. Habt Ihr es, Mann?", completion = "Ah, das isses, Mann.\n\n<Die Linse glüht hell in Buunus Händen und wirft überirdische Lichtstrahlen im schattigen Höhleneingang.>\n\nJetzt sind wir soweit, die Geister aus den Schatten zu holen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28167] = { id = 28167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Carvo Sprengbolz", description = "Ich werde meine Leute darauf vorbereiten, diesen Ort zu verlassen. Wir können hier nicht mehr länger ausharren. Ich möchte, dass Ihr Euch in eine vorgeschobene Position mitten in dem großen Zimmer vor uns begebt.\n\nDort solltet Ihr Carvo Sprengbolz finden. Er wird Euch weitere Anweisungen geben. Viel Glück, {name} und wir sehen uns an der Oberfläche wieder.", sourceObjective = "Meldet Euch bei Carvo Sprengbolz in Gnomeregan.", completion = "Hat Nevin Euch vorgeschickt? Das bedeutet, er bereitet sich darauf vor, die Mission zu beenden. Doch es müssen immer noch Überlebende gerettet werden. Wir müssen ihnen helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28168] = { id = 28168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an den Schlickfeldern", description = "Aufseher Stillwasser drüben auf den Schlickfeldern nördlich von hier hat einen Notruf geschickt. Die Botschaft war nicht deutlich, aber ich entnehme dem Brief, dass es dort an den Schlickfeldern einen Aufstand gibt und dass die meisten Wachen getötet wurden. Der Aufseher hat ausdrücklich gesagt, dass eventuelle Möchtegern-Helden sich vom Hintereingang her nähern sollten, der sich auf der Westseite der Schlickfelder befindet.\n\nAußerdem hat er um Diskretion gebeten. Er möchte nicht, dass die Nachricht dieses kleinen *räusper* Aufstandes sich verbreitet.", sourceObjective = "Meldet Euch bei Aufseher Stillwasser an den Schlickfeldern im Vorgebirge des Hügellands.", completion = "Wer seid Ihr? Hat Sylvanas Euch geschickt? Alles ist BESTENS! Ja, vollkommen in Ordnung! Ich hab' alles unter Kontrolle!\n\nAlso, den Umständen entsprechend heißt das... Wir haben ein paar Probleme, bei denen Ihr vielleicht helfen könntet, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28169] = { id = 28169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Laderaum zurückziehen!", description = "Ausgezeichnete Arbeit, die anderen Überlebenden einzusammeln! Sie - und Ihr - sind der Grund, dass das S.I.C.H.E.R. Team immer wieder hier hinunter kommt. Nevin gibt keine Ruhe, bis nicht auch der letzte Überlebende gefunden und gerettet ist.\n\nIch schicke meine Leute in den Laderaum, um die Dekontamination vorzubereiten. Bitte folgt ihnen und sucht Gaffer Spulfeder bei Eurer Ankunft auf. Sie wird Euch für die Dekontamination vorbereiten und auf den Weg zur Oberfläche bringen.", sourceObjective = "Folgt den Helfern von S.I.C.H.E.R. zu Gaffer Spulfeder im Laderaum.", completion = "Schön, Euch kennenzulernen, {class}. Wir treffen nur selten Überlebende, die so stark und fähig sind wie Ihr. Ich kann Euch bei der Dekontamination helfen und dabei, hier herauszukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28170] = { id = 28170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken der Nacht", description = "Mein Freund Uchek ist schon in der Höhle. Wir haben da drin drei Schreine aufgebaut. Ihr müsst nur die bösen Geister aus ihnen vertreiben, Mann.\n\nGeht in die Höhle hier und redet mit Uchek. Er versetzt Euch in Trance und in das Reich der Geister. Seid vorsichtig! Wenn Ihr ein Geistungeheuer seht, keine Panik. Lasst das Licht der Seelen für 'nen Moment oder zwei darauf scheinen und das Licht wird sie für immer verscheuchen. Das Licht wird für Eure Sicherheit sorgen. Jetzt geht und säubert die drei Schreine.", sourceObjective = "Sprecht mit Uchek im Rachen. Benutzt das Licht der Seelen aus dem Reich der Geister heraus, um Eure Sicherheit zu gewährleisten, wenn Ihr die drei Schreine in der Höhle besucht.", completion = "Seht Ihr? Man muss keine Angst vor den Toten haben. Ihr habt das Licht in die Dunkelheit getragen, Mann, und nicht mal geblinzelt.\n\nJetzt können wir diese Höhle als Operationsbasis für das nördliche Hochland nutzen. Ihr seid doch der Beste, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28171] = { id = 28171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... und der Himmel färbte sich rot", description = "Da Todesschwinge anderweitig abgelenkt ist, stellt sich uns eine düstere und schwere Aufgabe, in der uns die Königin höchstpersönlich leiten wird. Der schwarze Drachenschwarm muss getilgt werden.\n\nEure Hilfe würde ich gern in Anspruch nehmen, wenn Ihr denn zur Verfügung steht. Sobald Ihr bereit seid, werde ich Euch mit der nächsten Angriffswelle losschicken.", sourceObjective = "Schließt Euch dem Angriff gegen den schwarzen Drachenschwarm an.", completion = "Offensichtlich seid Ihr immer noch bei uns. Ich weiß das irgendwie zu schätzen.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[28172] = { id = 28172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unschuldig", description = "Die Schwarzfelsorcs in der Steppe dienen einem finsteren Meister, der abartige Experimente an lebenden Wesen durchführt, um seine eigene Menagerie der Monstrositäten zu schaffen. Viele seiner Testobjekte sind so verderbt wie ihr Meister, aber ein paar davon sind vollkommen unschuldig.\n\nIn den Schlupfhügeln im Süden ketten sie Jungdrachen am Boden fest, um sie für solche Experimente vorzubereiten. Das lasse ich nicht zu. Zerbrecht ihre Fesseln und bringt die Brutlinge zu mir... in Sicherheit.", sourceObjective = "Beschafft einen befreiten roten Welpling, einen befreiten grünen Welpling, einen befreiten blauen Welpling und einen befreiten bronzefarbenen Welpling.", progress = "Ich hoffe, wir kommen nicht zu spät.", completion = "Ich werde mich darum kümmern, dass diese Drachen versorgt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28173] = { id = 28173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarz vor Augen", description = "Die Zwielichtdrachenjäger haben teuflische Werkzeuge angewendet, um unsere Drachen vom Himmel zu holen. Haken, die sich tief in die Schuppen bohrten und es den Anhängern des Zwielichts gestatteten, unsere Angehörigen gefahrlos zu Boden zu zerren.\n\nWir befinden uns jenseits aller Aussicht auf Frieden. Ohne Hoffnung, daß sie sich rückbesinnen werden. Die Vernichtung, der sie sich so leidenschaftlich hingeben, ist die einzige Gnade, die wir dem schwarzen Schwarm noch gewähren können.\n\nBenutzt diese Haken, um die Obsidianflammenschwingen südlich von hier zu töten. Richtig angewendet, verschaffen sie Euch in der Luft reichlich Bewegungsfreiheit", sourceObjective = "Benutzt die Wyrmjägerhaken, um 8 Obsidianflammenschwingen zu erreichen und tötet diese dann.", completion = "Ihr scheint diese verstörenden Werkzeuge mit Leichtigkeit einzusetzen.\n\nEs tröstet mich zu wissen, dass einige Werkzeuge des Bösen am Ende dazu benutzt werden können, um Leben zu retten. Alles erfüllt einen Zweck.", sourceObjectiveStatus = "unverified-source-field" }
quests[28174] = { id = 28174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Rache", description = "Die Schwarzfelsorcs geben nicht auf. Sie schwärmen über die Schlachtfelder im Osten, bereit, jeden Moment zuzuschlagen.\n\nSie haben mein Heimatland bereits einmal angegriffen. Ich bin hier um sicherzustellen, dass das nicht noch einmal geschieht.\n\nWenn Ihr auch nur im Entferntesten etwas für die Menschheit übrig habt, macht Ihr dasselbe. Also beweist Euch. Begebt Euch nach Süden zu den Schlupfhügeln und tötet ihre Jungdrachenbändiger und die ausgeschlüpften schwarzen Drachen. Beweist mir, dass Ihr für diesen Krieg bereit seid.", sourceObjective = "Tötet 5 Jungdrachenbändiger des Schwarzfels und 5 Flammenschuppenbrutlinge.", completion = "Ihr seid also dabei?\n\nGut.", sourceObjectiveStatus = "unverified-source-field" }
quests[28175] = { id = 28175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht in der Dunkelheit", description = "Der große versteinerte Baum, der sich vor uns im Süden befindet, war einst ein Leuchtfeuer von großem Leben. Unser Leuchtfeuer. Wir haben diesen Wald an den schwarzen Schwarm verloren und seitdem ist er verdorben und versteinert. Es ist fast nicht rückgängig zu machen.\n\nAber noch ist nicht alle Hoffnung verloren. Ich habe ein mächtiges Werkzeug hergebracht, um den Heilungsprozess zu beginnen. Mit viel Zeit und Glück kann der Baum vielleicht noch gerettet werden - und mit ein wenig Anstrengung von Euch vielleicht.\n\nNehmt das hier, Alexstraszas Träne, und benutzt sie im hohlen Inneren des Baums.", sourceObjective = "Benutzt Alexstraszas Träne in der Aushöhlung unter dem Obsidianbaum.", progress = "Der schwarze Schwarm wird wahrscheinlich nie wieder rehabilitiert, aber auch nach all ihrer Zerstörung gibt es immer noch Hoffnung auf neues Leben.", completion = "Ihr habt heute etwas Wunderbares begonnen, mitten in all dem Blutvergießen.\n\nEs mag viele Jahre dauern, aber dieses Verwüstete Land wird wiederhergestellt werden. Es wird wieder wunderschön sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[28176] = { id = 28176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt den Jungen heim", description = "Im südwestlichen Teil des Obsidianwalds werdet Ihr einige Gelege schwarzer Eier finden. Viele Eier können jederzeit zum Schlüpfen gebracht werden, wenn die richtige Flamme sie ein wenig wärmt. Wenn die Welpen schlüpfen, werden sie einen Schrei ausstoßen und nach ihrer Mutter suchen.\n\nKeine Angst, wenn die Auslöschung sich auf die Welpen ausweiten sollte, werde ich Euch diese Aufgabe nicht aufzwingen. Ich möchte nur, dass Ihr sie heraus lasst und ihnen nach Hause folgt, wenn sie ihre Mutter suchen. Mit ihr müssen wir uns auseinandersetzen.", sourceObjective = "Benutzt die Flamme der Mutter auf Obsidianeiern, um Welpen hervorzubringen. Folgt diesen Jungen zum Hort ihrer Mutter.", completion = "Lirastrasza hat mich bereits in der Annahme zum Hort vorausgeschickt, dass der Schwarzdrache, den wir suchen, vielleicht noch hier ist. Den Jungen nach zu urteilen, hat sie wohl recht gehabt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28177] = { id = 28177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstockung", description = "Wenn wir einen Krieg gegen den Schwarzfelsklan führen wollen, müssen wir vorausplanen. Mein Oberst hat bereits einen Plan geschmiedet - jetzt wird es Zeit, ihn in die Tat umzusetzen.\n\nIch brauche Skorpidstachel... die schärfsten, die Ihr finden könnt. Skorpide befinden sich überall in der Steppe, aber die meisten befinden sich in der Schlucht im Westen.\n\nZerbrecht Euch nicht den Kopf darüber, wofür sie sind. Das werdet Ihr noch früh genug herausfinden.", sourceObjective = "Besorgt 5 rasiermesserscharfe Skorpidstachel.", progress = "Schon zurück?", completion = "Man kann diese Skorpiden leicht unterschätzen. Ihr habt Glück, dass Ihr nicht an einem dieser Stachel steckt. Oder vielleicht seid Ihr einfach nur gut.\n\nIch füge sie dem Vorratslager hinzu. Wir sind noch nicht fertig, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28178] = { id = 28178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zukünftiges Projekt", description = "Wir werden Worgbälge brauchen und zwar viele. Es spielt keine Rolle, ob sie zerrissen, verbrannt oder blutig sind. Hauptsache es sind genügend.\n\nWahrscheinlich ist es sogar besser, wenn sie ein wenig ramponiert aussehen.\n\nWorgs findet Ihr im Westen und im Osten.", sourceObjective = "Besorgt 11 Glutworgbälge.", progress = "Dann schauen wir uns die Bälge mal an.", completion = "Glaubt mir, {name}... Ich kann es genauso wenig wie Ihr abwarten, bis wir endlich zum Töten kommen. Aber wir müssen uns an den Plan halten. Das Jüngste Gericht kommt früh genug.\n\nIch werde diese Bälge hier aufbewahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28179] = { id = 28179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammschlacht", description = "Ich hoffe, Ihr habt keine Angst davor, Euch schmutzig zu machen. Aber wenn ich Euch so ansehe, dürfte das kein Problem sein.\n\nIm Norden am Rand der Lava findet Ihr dunkle Schlammhaufen. Den Schlamm brauche ich.\n\nAm besten stellt Ihr keine Fragen und konzentriert Eure Bemühungen darauf, Befehle zu befolgen, {name}.", sourceObjective = "Besorgt 9 Haufen obsidiandurchsetzten Schlamm.", progress = "Ihr solltet Euch vor den Obsidianelementaren hüten. Sie schleichen sich gerne an.", completion = "Das ist genau das, was wir brauchen!\n\nKeine Sorge, {name}... Das Orctöten wird noch früh genug kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28180] = { id = 28180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sand, der Apfelwein und die Kugel", description = "Oberst Trottmann wartet auf uns im Osten. Bevor wir uns auf den Weg machen, sollten wir allerdings noch etwas mehr Zeug zusammensuchen. Diesmal werdet Ihr es einem Hexenmeister mit Namen Gorzeeki Wildaug abnehmen.\n\nWahrscheinlich findet Ihr ihn im Nordwesten in der Nähe des Altars der Stürme. Sagt ihm, dass er uns helfen wird. Wir brauchen den Sand, den Apfelwein und die Kugel.\n\nEr weiß schon, was das bedeutet.", sourceObjective = "Sprecht mit Gorzeeki Wildaug in der Nähe des Altars der Stürme.", completion = "Bah! Wer seid Ihr?\n\nOh, also hat Keeshan Euch geschickt? Gut. Würde es Euch etwas ausmachen, wenn Ihr eine Weile hier bleibt? Nichts großes... Ihr müsst nur ein paar Hexenmeister für mich töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28181] = { id = 28181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexenmeister haben das beste Zeug", description = "Keeshan sagte, er braucht Vorräte? Ich habe reichlich Vorräte! Das Problem ist nur, dass diese Hexenmeister mich aus meinem Zuhause geworfen haben und mich nicht wieder hineinlassen.\n\n<Gorzeeki mustert Euch.>\n\nIhr könntet vielleicht hineingelangen. Geht nach Norden und holt mir meinen Schlummersand, mein Teufelskarussellstöffsche und eine klare Glaskugel. Ich bin mir ziemlich sicher, dass es das ist, was er haben will.\n\nOh, und falls Ihr aus Versehen ein paar dieser Orcs tötet, während Ihr da oben seid, wäre ich bestimmt nicht traurig.", sourceObjective = "Besorgt eine Handvoll Schlummersand, einen Krug Teufelskarussellstöffsche und eine lupenreine Glaskugel.", progress = "Mal sehen, ob Ihr alles bekommen habt.", completion = "Ich hoffe, dass ist das, wonach Keeshan gesucht hat. Im Moment kann ich jedenfalls nicht viel damit anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28182] = { id = 28182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenboxen", description = "Ner'gosh der Schatten ist der Anführer dieser Hexenmeister, die sich nördlich von uns befinden. Er ist der Fiesling, der mich aus meinem Haus vertrieben hat, als diese Schwarzfelsorcs aufgetaucht sind. Nun, eigentlich sind sie alle Fieslinge, aber er ist der fieseste.\n\nWenn ich jemals in die Nähe des Altars zurückkehren möchte, muss Ner’gosh verschwinden.", sourceObjective = "Tötet Ner'gosh den Schatten.", completion = "So wie ich diese Orcs kenne, wird bald ein anderer seinen Platz einnehmen. Ich werde versuchen, mich zurück in den Altar zu schleichen, bevor das passiert.\n\nHabt Dank, mein Bester.", sourceObjectiveStatus = "unverified-source-field" }
quests[28183] = { id = 28183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Keeshan", description = "Ich schätze, ich bin hier mit Euch fertig. Ich werde diese anderen Orcs davonscheuchen, sobald ich den Mut dazu gefunden habe.\n\nHier, vergesst Eure Vorräte nicht.", sourceObjective = "Bringt die Hexenmeisterausrüstung zurück zu John J. Keeshan am Flammensternposten in der Brennenden Steppe.", progress = "Sieht aus, als wärt Ihr mit Gorzeeki gut zurecht gekommen.", completion = "<Keeshan wirft einen Blick in die Kiste.>\n\nGut, gut, gut. Wir können weiter. Unser Krieg führt uns nach Osten, weg vom Schwarzfels... fürs Erste.", sourceObjectiveStatus = "unverified-source-field" }
quests[28184] = { id = 28184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meißelgriff, das Herz der Steppe", description = "Wir sind auf dem Weg nach Meißelgriff, das sich genau im Herzen dieser Steppe befindet. Wir treffen uns dort mit der Thoriumbruderschaft und außerdem mit Trottmann.\n\nSeid Ihr mit der Bruderschaft vertraut? Diese Dunkeleisenzwerge haben mir mehr als einmal geholfen. Wir brauchen ihre Hilfe vielleicht erneut.\n\nWir kommen auf unserem Weg dorthin durch den Schwarzzahnunterschlupf. Was haltet Ihr davon, wenn wir unterwegs ein paar Orcs töten? Ich werde in diesem Lager langsam ein wenig unruhig.", sourceObjective = "Tötet 15 beliebige Schwarzfelstruppen auf Eurem Weg nach Meißelgriff.", completion = "Ihr müsst mich entschuldigen, aber wir empfangen derzeit keine Besucher. Ich bitte Euch, Meißelgriff auf demselben Weg wieder zu verlassen, den Ihr gekommen seid.\n\nOh, Keeshan... Seid Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[28185] = { id = 28185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svarnos", description = "Ihr habt bei der Eroberung der Insel ausgezeichnete Arbeit geleistet, {class}. Jetzt, wo wir die Insel in Besitz genommen haben, müssen wir diese Zellenblocks für Gefangene herrichten. Der D-Block erweist sich als besonders schwer zu säubern. Unglücklicherweise wird er von zahlreichen Dämonen und Ähnlichem heimgesucht.\n\nWir konnten die Dämonen etwas dezimieren, aber ein großer Kernhund hat sich aus seiner Zelle freigekämpft und richtet dort unten Chaos und Verwüstung an. Ihr müsst ihn töten und mir sein Halsband bringen.", sourceObjective = "Ihr müsst Svarnos im D-Block töten und mit seinem verfluchten Halsband zurückkehren. Svarnos hält sich im D-Block auf, direkt nordwestlich der Baradinfestung.", progress = "Ist der Kernhund tot?", completion = "Svarnos ist endlich tot? Sieht so aus, als ob wir uns zu guter Letzt an die Arbeit machen können, den Zellenblock herzurichten. Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28186] = { id = 28186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchte Fesseln", description = "Wart Ihr schon im D-Block, {name}? Jedes Mal wenn wir den verseuchten Zellenblock leerräumen, scheinen diese Dämonen ziemlich schnell zurückzukehren. Wir haben herausgefunden, dass sie sich mithilfe der verfluchten Fesseln regenerieren, die in dieser Gegend verstreut herumliegen. Und da kommt Ihr ins Spiel, {name}.\n\nIhr müsst so viele dieser Fesseln wie möglich einsammeln und zu mir bringen. Wir werden sie dann unverzüglich zerstören.", sourceObjective = "Ihr wurdet gebeten, 8 verfluchte Fesseln aus dem D-Block zu beschaffen, der direkt nordwestlich der Baradinfestung liegt.", progress = "Habt Ihr viele Fesseln gefunden? Den Berichten zufolge liegen sie dort überall verstreut herum.", completion = "Die Fesseln! Wir werden sofort mit der Zerstörungsprozedur dieser Fesseln beginnen, {name}. Habt Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28187] = { id = 28187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um Haaresbreite!", description = "Also gut, {race}! Aus Spaß ist gerade Ernst geworden!\n\nJemand glaubt wohl, dass er mich so leicht loswerden kann, wie?\n\nDas werden wir ja sehen! Nichts kann diese Arbeit aufhalten! Nichts!\n\n<Schnottz sieht auf das Feuer, das sich überall ausbreitet.>\n\nWir sollten vermutlich von hier verschwinden.\n\nBeeilung! Keine Zeit verschwenden!", sourceObjective = "Sprecht mit Kommandant Schnottz, wenn Ihr bereit seid, ihn aus dem brennenden Gebäude zu geleiten.", completion = "In Zeiten wie diesen, stellt man fest, wer seine wahren Freunde sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[28188] = { id = 28188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangenenaufstand", description = "Die Insel gehört uns. Jetzt müssen wir unsere Anlagen hier einsatzbereit machen. Wir haben einen aufgegebenen Zellenblock südwestlich von hier gefunden und wir müssen ihn auskundschaften, {name}.\n\nBerichten zufolge ist er voller Gefangener, die dort drinnen seit Jahren festsitzen. Tut, was immer ihr müsst, um den Ort zu säubern. Meldet Euch bei mir, wenn Ihr fertig seid.", sourceObjective = "Ihr wurdet beauftragt, 10 beliebige Gefangene im Loch zu töten, das südwestlich der Baradinfestung liegt.", completion = "Ihr habt das Gebiet gesäubert? Es sieht so aus, als ob Ihr Euch als nützlicher erweist, als wir dachten, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28189] = { id = 28189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Richtige tun", description = "Euch bietet sich ein entsetzlicher Anblick. Jemand hat alle Menschen bis zum Hals eingegraben, sodass sie aussehen wie eingepflanzt. Die Ghule, die anscheinend dieses Feld von menschlichen Keimlingen pflegen, springen in regelmäßigen Abständen zum nächstgelegenen Menschen und fressen seine Kopf!\n\nIhr könnt dies hier und jetzt beenden. Nehmt diese Schaufel und \"rettet\" die Menschen.\n\nTut das Richtige.", sourceObjective = "\"Rettet\" 15 menschliche Keimlinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[28190] = { id = 28190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der besudelte Schlamm", description = "Dies alles begann mit Winna Hazzard. Sie war eine Apothekerin der Verlassenen im Blutgiftposten, die Methoden erforschte, wie man den dämonischen Schlamm gegen die Allianz einsetzen könnte.\n\nWir haben sie davor gewarnt, sie würde zu weit gehen, aber sie wollte nicht hören. Und wir haben nicht schnell genug gehandelt. Jetzt sind sie und jeder andere im Blutgiftposten nichts weiter als hirnlose Schleimkreaturen...\n\nDie widerlichen Schlämme, die sie verwendet hat, streifen noch immer in der Nähe der Tümpel im Süden umher. Ich flehe Euch an, {class}, zerstört sie, sodass sie nicht weiterhin so viel Böses verbreiten können.", sourceObjective = "Vernichtet 8 besudelte Schlämme.", progress = "Schon allein der Gedanke an diese ekelerregenden Kreaturen macht mich krank! Urgh...", completion = "Mein Zorn wird durch diese Neuigkeiten gemildert... Vielleicht wird es mir jetzt leichter fallen, mich zu erholen und zu genesen.\n\nUnd vielleicht wird sich mein Magen ebenfalls beruhigen. Urgh...", sourceObjectiveStatus = "unverified-source-field" }
quests[28191] = { id = 28191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein passendes Ende", description = "Die Obsidianwyrmkin sind überall über die Landschaft südlich von uns verstreut. Sie sind nicht in der Lage, uns zurückzuschlagen, aber man kann nie wissen, welche neuen Gefahren die Schlacht mit sich bringt.\n\nIch will, dass Ihr die Wyrmkin angreift. Vernichtet sie, sodass wir damit fortfahren können, dieses Land von der verunreinigenden Anwesenheit des schwarzen Drachenschwarms zu befreien.", sourceObjective = "Tötet 10 Obsidianwyrmkin.", completion = "Ihr habt Euch als ein wichtiger Verbündeter erwiesen. Nach unserer ersten Begegnung hätte ich niemals damit gerechnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[28192] = { id = 28192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemand kommt hier lebend heraus", description = "Dieser Hof ist abgeriegelt! Nichts und niemand kommt hier heraus! Wir analysieren noch immer die Lage und versuchen, herauszufinden, was genau geschehen ist. Aber meiner Theorie nach aßen die Arbeiter die Pilze und sind irgendwie zu abscheulichen, untoten Monstern mutiert. Ich meine, wie sonst könnte so etwas passiert sein? Dies ist nur ein Hof! Wir produzieren hier Pilze! Und Schlamm! Ja, Schlamm!\n\nSeht Euch um, {class}, denn jetzt wo Ihr hier seid, könnt Ihr nicht fort, bis diese Angelegenheit geklärt ist.\n\nSeht selbst!", sourceObjective = "Schätzt die Situation auf den Schlickfeldern ein.", completion = "Wie Ihr sehen könnt, sie sind alle zu Monstern geworden! Die meisten meiner Wachen starben und diejenigen, die es geschafft haben, zu entfliehen, verteidigen jetzt die Barrikaden, um zu verhindern, dass diese möglicherweise gefährlichen Kreaturen herauskommen.\n\nWir brauchen Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[28193] = { id = 28193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgeriegelt!", description = "Das Gebäude ist nicht von alleine explodiert!\n\nJemand hat versucht, mich abzumurksen und Ihr werdet nicht ruhen, bis ich herausgefunden habe wer!\n\nBleibt bei den Gästen. Mischt Euch unter sie, beobachtet ihr Verhalten und dann meldet Euch wieder bei mir.\n\nWenn sie irgendetwas wissen sollten, werde ich sie verhören lassen!\n\nWegtreten!", sourceObjective = "Kommandant Schnottz will, dass Ihr die Gäste in Schnottz' Landeplatz überwacht.", completion = "Sie wissen nichts, sagt Ihr?\n\nAlso gut. Die Suche geht weiter...", sourceObjectiveStatus = "unverified-source-field" }
quests[28194] = { id = 28194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Flucht", description = "Bitte, {class}! Wir brauchen Eure Hilfe!\n\nWir werden gegen unseren Willen in diesem Gebäude gefangen gehalten. Und da der Kommandant so schlecht gelaunt scheint, wissen wir nicht, was er uns antun wird.\n\nWenn Ihr uns ein paar Uniformen ergattern könntet, können wir uns davon schleichen.\n\nWir hätten niemals hierher kommen sollen. Das ist mir jetzt klar.\n\nWenn Ihr uns helft, zu fliehen, werde ich die WAHRHEIT über das aufschreiben, was hier passiert ist.\n\nDie Männer auf den Schiffen tragen alle die Kleidung, die wir benötigen.", sourceObjective = "Der produktive Schriftsteller in Schnottz' Landeplatz will, dass Ihr 6 frische Seemannsuniformen von Seemännern von Schnottz einsammelt.", progress = "Wart Ihr in der Lage, uns ein paar Uniformen zu besorgen, {race}?", completion = "Die sind perfekt, {class}.\n\nWünscht uns Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[28195] = { id = 28195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Botschaft senden", description = "Ich habe meine Augen und Ohren in jedem Winkel dieser Gegend, {race}.\n\nIch habe gehört, was unter meinen Truppen getuschelt wird. Ich war diesem erbärmlichen Verhalten gegenüber äußerst tolerant – bis jetzt!\n\nIch werde eine Botschaft an jeden in meinen Reihen senden. Zwietracht wird nicht länger geduldet! \n\nIhr sollt die Kapitäne auf den Schiffen in meiner Anlegestelle töten. Sie sind von der besonders entrüsteten Sorte.\n\nWenn das vollbracht ist, werde ich die Ohren weiter spitzen und entscheiden, was als nächstes zu tun ist. \n\nWegtreten!", sourceObjective = "Kommandant Schnottz will, dass Ihr Kapitän Margun, Kapitän Cork und Kapitän Kronkh tötet.", completion = "Sehr gut, {race}...", sourceObjectiveStatus = "unverified-source-field" }
quests[28196] = { id = 28196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um das Hügelland", description = "Das Tagebuch beschreibt die letzten 62 Tage aus Amtmann Horatio Weißross' Leben. Es enthält vernichtende Behauptungen gegen Aufseher Stillwasser und seine Taten auf den Schlickfeldern.\n\nIhr solltet es dem Aufseher zeigen. Er wird für das, was in diesem Tagebuch beschrieben steht, zweifellos eine Erklärung haben.", sourceObjective = "Bringt \"Kampf um das Hügelland\" zu Aufseher Stillwasser bei den Schlickfeldern im Vorgebirge des Hügellands.", progress = "Was ist das?", completion = "<Aufseher Stillwasser blättert durch das Tagebuch und liest leise.>\n\nGeschwafel eines Verrückten! Er hatte offensichtlich zu viele Pilze gegessen. Es ist gut, dass Ihr mir das gebracht habt, {name}. Ich werde es eigenhändig verbrennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28197] = { id = 28197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskretion ist der Schlüssel", description = "Wir müssen alle Beweise vernichten, {name}! Sagte ich Beweise? Ich meinte natürlich verrückte Untote! Auf jeden Fall ist Vorsicht die Mutter der Porzellankiste. Wir dürfen nicht zulassen, dass diese wilden Untoten aus den Schlickfeldern entkommen und niemand außerhalb dieser Anlage darf wissen, was hier geschehen ist!\n\nGenau südöstlich von hier liegt das, was mal der Pilzhof war. Dort findet Ihr einen wiederbelebten Feind namens Bürger Wilkes mit seinem Kollegen Amtmann Horatio Weißross. Sie haben meinen Wachen einige Probleme bereitet. Findet sie und tötet sie!", sourceObjective = "Tötet Bürger Wilkes und Amtmann Horatio Weißross.", completion = "Gut gemacht! Wilkes wurde gehängt, nachdem wir herausgefunden haben, dass er massenhaft von diesen Pilzen und andere hochgiftige Substanzen zu sich genommen hat. Nach seinem Tod wurde er als untoter Geist wiedergeboren. Viele meiner Wachen fielen Wilkes zum Opfer, bevor er davonrannte und sich versteckte. Wir fürchten, dass so etwas noch einmal passieren könnte und verbrannten deshalb den Amtmann, bis nur noch Knochen von ihm übrig waren!\n\nWarum sie freiwillig, giftige Substanzen zu sich genommen haben? Ich habe keine Ahnung! Dies ist ein gewöhnlicher Hof, mein Herr, nichts weiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[28198] = { id = 28198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das schwächste Glied", description = "Man sagt, eine Kette sei immer so stark wie das schwächste Glied.\n\nIch unterschreibe diese Theorie und baue sie sogar noch weiter aus.\n\nAnstatt das schwächste Glied zu entfernen, muss man es... stärken. \n\nDie anderen Glieder werden ihre Leistungen aus Angst erhöhen, dass sie selbst das schwächste Glied werden.\n\nIm Falle meiner Armee, hat unser schwächstes Glied einen Namen. Salhet.\n\nIhr findet ihn beim Üben am Fuße dieser Stufen.\n\nFangt bei ihm mit etwas Leichtem an. Die Hyänen auf den Hügeln im Westen vielleicht.", sourceObjective = "Sprecht mit Salhet am Außenposten der Legion von Ramkahen in Uldum.", completion = "Es ist eine große Ehre, Euch kennen zu lernen, {name}! Ich habe viel von Euch gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[28199] = { id = 28199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Wissenschaft!", description = "Proben... jaaa... brauche Proben! Diese, öhm, Experimente... Ich meine, diese unglücklichen Arbeiter müssen untersucht werden.\n\nReist nach Südosten zum ersten Hof und tötet die auferstandenen Ghule. Ihr müsst aus ihren verfaulten Körpern Fleischproben entnehmen. Bringt diese zu mir!\n\n<Arnauld reibt sich die Hände und lacht wie wahnsinnig - ohne erkennbaren Grund.>\n\nMuss forschen!", sourceObjective = "Beschafft 6 Fleischproben.", progress = "Für die Wissenschaft!", completion = "Diese Proben werden uns ein besseres Verständnis dieser hirnlosen Untoten geben. Nehmt diese Münzen als Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[28200] = { id = 28200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versorgungslücke", description = "Ihr habt sicher bemerkt, dass wir für eine Schlacht eher leidlich gerüstet sind. \n\nDie Stämme der Tol'vir standen Jahrtausende lang vor keiner Auseinandersetzung dieses Ausmaßes.\n\nSämtliche Kampfprotokolle, welche die Titanen unseren Vorfahren einprogrammierten, sind aber noch vorhanden. Manche sind Teil unserer Instinkte, andere werden als Tradition weitergegeben.\n\nAber das alles kann eine Versorgungslücke nicht ausgleichen. Wir brauchen Waffen. Wir brauchen Rüstungen.\n\nDie besten Rüstungen sind mit dem Leder der Flusskrokilisken aus dieser Gegend gefüttert. Helft uns, ein paar zu sammeln.", sourceObjective = "Sammelt 20 gehärtete Krokiliskenbälge.", progress = "Es freut mich, zu sehen, dass Ihr Euch nicht über diese Art von Aufgabe erhaben fühlt.", completion = "Gute Arbeit, {name}. Ihr glaubt vielleicht nicht, dass dies sonderlich nützlich ist, aber es kann für einen unserer Soldaten durchaus den Unterschied zwischen Leben und Tod ausmachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28201] = { id = 28201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflugscharen zu Schwertern", description = "Wir haben eine beachtliche Armee, aber ich befürchte, dass das herannahende Kräftemessen mit den Tol'vir der Neferset es erforderlich macht, alle Tol'vir von Ramkahen und Orsis in den Kampf mit einzubinden.\n\nIch will, dass Ihr an der Spitze unserer Rekrutierungsbemühungen steht.\n\nBegebt Euch über den Fluss zu den Feldern von Akhenet und rekrutiert die Arbeiter, die dort ihrem Tagewerk nachgehen.", sourceObjective = "Rekrutiert 8 Arbeiter von Ramkahen.", completion = "Ihr seid ein geborener Anführer, {name}. Es wäre gut, Euch an unserer Seite zu wissen, wenn der Krieg diese Länder erreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28202] = { id = 28202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als einen Orc verkleiden. Ihre Armee besteht hauptsächlich aus Orcs, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", completion = "Das soll sie sein? Das ist Eure Verkleidung?\n\nIch habe das Gefühl, dass unsere Chancen rapide sinken. Es war schön, Euch kennengelernt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28203] = { id = 28203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Oger verkleiden. Die Oger der Feuermägen haben immer für die Schwarzfelsorcs gearbeitet, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", completion = "Das soll sie sein? Das ist Eure Verkleidung?\n\nIch habe das Gefühl, dass unsere Chancen rapide sinken. Es war schön, Euch kennengelernt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28204] = { id = 28204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Goblin verkleiden. Die Schwarzfelsorcs haben schon immer goblinische Söldner angeheuert, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", sourceObjectiveStatus = "unverified-source-field" }
quests[28205] = { id = 28205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Troll verkleiden. Die Gluthauertrolle haben stets mit den Schwarzfelsorcs zusammengearbeitet, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", completion = "Das soll sie sein? Das ist Eure Verkleidung?\n\nIch habe das Gefühl, dass unsere Chancen rapide sinken. Es war schön, Euch kennengelernt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28206] = { id = 28206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schönling auf Abwegen", description = "Es war erst gestern, dass ich ihn losschickte, um den Bauernhof östlich von hier zu untersuchen, aber es fühlt sich an wie eine Ewigkeit!\n\nWahre Perfektion. Wie seine blonden Locken sein makelloses Elfengesicht umrahmen... Und erst diese Stärke. Ich wollte ihn gar nicht gehen lassen, aber er hat darauf bestanden! Und wie könnte ich ihm einen Wunsch abschlagen, wenn er mich mit seinen strahlenden Augen ansieht...\n\nAber jetzt ist Johnny Imba nicht zurückgekehrt! Ich befürchte das Schlimmste, {name}. Findet ihn!", sourceObjective = "Findet Johnny Imba in den Schlickfeldern im Vorgebirge des Hügellands.", completion = "<Johnny schluchzt laut.>\n\nGl... Glitzer!!! Di... Er hat sie getötet!\n\n<Johnny heult weiter.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28207] = { id = 28207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schleimige Angelegenheit", description = "Dieser arme Tauren hier ist bei der Flucht aus dem Blutgiftposten nur knapp mit dem Leben davon gekommen! Wenn wir verhindern wollen, dass er sich, wie all die anderen, in eine Schleimkreatur verwandelt, werden wir die Infektion behandeln müssen.\n\nIn der Nähe der hellen, grünen Gewässer in dieser Gegend wachsen viele Pilze. Zum Beispiel am Teich im Osten, zwischen den Wasserfällen. Die meisten von ihnen sind zu nichts zu gebrauchen... Aber die hellgrün leuchtenden müsst Ihr für mich sammeln!\n\nAus ihnen kann ich etwas Schmackhaftes zubereiten, das dem Armen hilft. Lasst Euch nicht zu viel Zeit!", sourceObjective = "Sammelt 7 smaragdgrüne Schimmerkappen.", progress = "Denkt daran, die hellgrün leuchtenden Pilze!", completion = "Die meisten Leute denken, dass das grüne Leuchten auf dämonische Verderbnis hinweist... aber wenn man ein Auge für Farben und Schattierungen hat, dann kann man sehen, dass dies die Energien des Smaragdgrünen Traums sind! Diese kleinen Pilze werden nicht durch die Gewässer verdorben, sondern sie tun ihr Bestes, um sie zu läutern!\n\nJetzt pürieren wir sie und machen einen leckeren Brei für den Herrn Tauren. Wenn er die gegessen hat, wird er sich besser fühlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28208] = { id = 28208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winnas Kätzchen", description = "Herr Tauren hat mir viel darüber berichet, was am Blutgiftposten geschehen ist. Er sagte Winna Hazzard ist noch immer dort!\n\nSie ist nicht mehr zu retten, aber was von ihr übrig ist, produziert reichlich neuen Schleim. Wir müssen ihn aufhalten!\n\nGlücklicherweise habe ich einen Plan. Herr Tauren sagte, Winna hätte früher ein Kätzchen gehabt. Sie hat ihm verdorbenes Schleimwasser zu trinken gegeben. Daraufhin ist es in die Wälder gelaufen. Ich sah im Südosten hinter dem Blutgiftturm etwas herumschleichen, aber es war größer als ein Kätzchen! Seht mal nach, ob das Miezekätzchen eine Ohrmarke trägt...", sourceObjective = "Beschafft Miezis Ohrmarke von Winnas Kätzchen.", progress = "Habt Ihr das Kätzchen gefunden?", completion = "Armes kleines Miezekätzchen, leidet schon so lange dort draußen in den Wäldern! Ihr habt dem armen Ding etwas Gutes getan, {name}. Und auch all den Reisenden, die es noch gefressen hätte.\n\nDiese Ohrmarke wird sich als nützlich erweisen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28209] = { id = 28209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für Lydon", description = "Das hier ist kein Hof! Stillwasser hat an den Menschen vom Hügellandhof Experimente durchgeführt. Diese Monstrositäten hier sind alles seine Schöpfungen.\n\nDas ist nicht das Schlimmste daran, {class}. Diese Entartungen, die den Schlüssel zu meinen Käfig haben, sind ehemalige Verlassene. Stillwassers Experimente haben die Nebenwirkung, Verlassene in hirnlose Zombies zu verwandeln. Warum glaubt Ihr, dass er so viel Angst davor hat, dass dies hier herauskommt? Er weiß, dass so ein Verbrechen mit dem endgültigen Tod bestraft wird.\n\nHolt mich hier raus! Die infizierten Schlickwachen dort draußen haben den Schlüssel!", sourceObjective = "Findet Lydons Käfigschlüssel.", progress = "Findet den Schlüssel!", completion = "<Lydon nimmt Euch den Schlüssel ab.>\n\nIch lasse mich selbst raus, danke.\n\nIch war noch nie so wütend! Stillwasser kommt damit nicht davon. Ich werde seinen Kopf persönlich der Bansheekönigin präsentieren.\n\nWir beide arbeiten zusammen, {name}.\n\nIch weiß ja nicht, was den Burschen da angeht, aber am liebsten wäre mir, wenn er zurückbleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28210] = { id = 28210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Form bringen", description = "Hochkommandant Kamses hat eine spezielle Aufgabe für mich?\n\nWartet... sagt es mir nicht. Es sind wieder die Hyänen, richtig?\n\nNun gut, ich werde mein Bestes geben.\n\nTrefft mich am Sonnenbehütergrat.\n\nIch werde Euch nicht enttäuschen.", sourceObjective = "Helft Salhet dabei, 8 Murrbluthyänen zu töten.", progress = "Wie viele haben wir?", completion = "Nun... Das war nicht so richtig gut, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[28211] = { id = 28211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Elementarflammen gehärtet", description = "Das Wichtigste zuerst: Wir werden Munition brauchen. Munition, die stark genug ist, die Panzerhaut eines Schwarzdrachen zu durchschlagen. \n\nWestlich von Donnermar ist eine Stadt des Wildhammerklans, die von unbändigen Feuerelementaren überrannt wurde. Jede Waffe, die in dem Großbrand zurückgelassen wurde, wird in den Elementarflammen gehärtet worden sein. Es ist jetzt härter als alles, was ich in dieser Schmiede auf die Schnelle herstellen könnte!\n\nBringt mir Speere aus der Humboldtfeuersbrunst, {name}. Je spitzer desto besser.", sourceObjective = "Sammelt 8 gehärtete Speere.", progress = "Speere, ja? Meine Schnellfeuerspeerharpune wäre ohne sie nutzlos.", completion = "Seht Euch das an – AUTSCH! Spitz! Heiß!\n\nDiese Speere sollten durch den Drachenpanzer schneiden wie ein elektrischer Käsehobel durch warme Butter.", sourceObjectiveStatus = "unverified-source-field" }
quests[28212] = { id = 28212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißes Zeug", description = "Ich habe einen Plan, wie wir das empfohlene Drehmoment für eine Speerharpune dieser Größe vervierfachen könnten, aber meinen Berechnungen zufolge würde das Abfeuern dieser Waffe das Gehäuse zerspringen lassen. Und eventuell noch den Planeten in zwei Teile spalten.\n\nIch kann ein Gehäuse zusammenschweißen, das hundertmal stärker ist, wenn ich eine zuverlässige Quelle reiner Elementarflammen für die Verhüttung hätte.\n\nUngebundene Glutbiesten wüten in der Gegend westlich von hier in der Humboldtfeuersbrunst. Wenn man sie tötet, sollten sie auf die Größe von Kügelchen glühenden Zorns schmelzen. Bringt mir ein paar!", sourceObjective = "Sammelt 5 Kügelchen glühenden Zorn.", progress = "Habt Ihr den glühenden Zorn? Nein, nein, gebt sie mir nicht in die Hand. Hier, verwendet die Zangen!", completion = "Wunderbar! Ich werde dieses Erz zu einer köstlichen Suppe verschmelzen. Eine glühende Suppe. Aus flüssigem Metall.", sourceObjectiveStatus = "unverified-source-field" }
quests[28213] = { id = 28213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftmüllbeseitigung", description = "Winna ist in die Quelle des Schleims am hinteren Ende des Blutgiftpostens im Westen eingeklinkt. Sie sorgt dafür, dass der Schleim weiter fließt und der Brunnen sorgt für ihren Schutz! Aber wenn Ihr ihre Aufmerksamkeit erregen könnt...\n\nNehmt die Ohrmarke und zeigt sie Winna. Wenn nur ein kleines Bisschen von der alten Winna in ihr übrig ist, kommt es vielleicht zum Vorschein. Vielleicht wird ihr Bedauern für ihre arme, verlorene Miezi Oberhand gewinnen, vielleicht wird sie noch einmal Mitleid haben und sie wird vielleicht aus dem Schleim herauskommen!\n\nUnd dann könnt Ihr sie vielleicht töten und den Schleim aufhalten. Juhu!", sourceObjective = "Verwendet Miezis Ohrmarke, um Winna Hazzards Aufmerksamkeit zu erregen und dann vernichtet sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[28214] = { id = 28214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Blutgiftposten säubern", description = "Hurg...\n\nKönntet Ihr... uh... Könntet Ihr bitte... HUÄRG!\n\nEntschuldigt, mir ist ein wenig... uh, mein Magen. Wenn Ihr Euch zum Blutgiftposten im Westen begebt, könntet Ihr bitte HUURG...\n\nBe... Befreit einfach das, was von meinen Freunden übrig ist, von ihrem Elend. Und geht JETZT. In Eurem eigenen Interesse. Uuuuurg...", sourceObjective = "Tötet 6 Schleimsklaven des Blutgiftpostens.", completion = "Habt Dank, {class}. Ich fühle mich viel besser und es ist gut, dass diese Monstrositäten fort sind.\n\nIhr solltet Euch vielleicht trotzdem ein wenig von mir fernhalten. Sicherheitshalber...", sourceObjectiveStatus = "unverified-source-field" }
quests[28215] = { id = 28215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potentielle Energie", description = "Wie Ihr wisst, ist die Menge an Energie, die in einer herkömmlichen Feder gespeichert ist, gleich der Hälfte der Elastizität der Feder multipliziert mit der Weggröße im Quadrat. Es sei denn, man verwendet eine Elementiumfeder. Dann werden die Zahlen irrsinnig groß! Mathematisch gesehen grotesk! \n\nIch brauche ein paar Elementiumkreise für meine Geheimwaffe und wie es nun mal so ist: Die Schattenhammerkultisten verwenden Spulen wie diese, um die Erdelementare zu binden.\n\nFindet sie an den Obsidiansteinsklaven östlich von hier in der schrecklichen Region, die Schwarzer Riss genannt wird.", sourceObjective = "Sammelt 10 gewundene Spulen aus Elementium.", progress = "Wenn Ihr jetzt haufenweise Elementiumspulen aus Eurem Rucksack zieht, dann macht Ihr mich zu einem sehr glücklichen Gnom!", completion = "Ausgezeichnet! Diese Schätzchen werden sich mit der Kraft von tausend Sonnen entspannen!\n\nDas ist natürlich nur eine grobe Schätzung. Macht mich ja nicht für diese Zahlen verantwortlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[28216] = { id = 28216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmalord Falthazar", description = "Ich habe gerade die schlimmen Nachrichten aus dem Westen gehört. Wir haben Humboldts Siedlung verloren. Sie wurde einfach von einer Feuerwand von dieser Welt getilgt!\n\nSchuld daran ist der Schattenhammer. Die Überlebenden sagen, es wäre das Werk eines gewissen Magmalord Falthazar. Er ist einer der Aszendenten. So nennen sie den höchsten Rang unter den Schattenhammerkultisten, die eins mit den Elementen werden. Er ist ein Wesen aus reinem Feuer.\n\nUnd bald wird er ein Wesen aus reinem Tod sein! Tötet Falthazar bei der Humboldtfeuersbrunst und bringt mir seinen Kopf!", sourceObjective = "Sammelt den Kopf von Magmalord Falthazar.", progress = "All die Jahre dachte der alte Humboldt, Stopfwampes Oger auf dem Gebirgskamm wären sein größtes Problem. Doch dann kam der Schattenhammer.\n\nIn nur einem Wimpernschlag setzten sie das ganze Tal in Flammen, als wäre es eine Geburtstagstorte. Herzlos.", completion = "Jep, genau das ist er. Kaum vorzustellen, dass das hier einmal ein Mensch war.\n\nDa seht Ihr das wahre Gesicht des Schattenhammers. Was sie nicht vernichten, verderben sie.\n\nVielen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28217] = { id = 28217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Der Dämonenjäger", description = "Seit der Jadefeuerbach von den Dämonen zurückerobert wurde hat der Smaragdkreis viele Druiden geschickt, um die langwierige Läuterung der Ruinen zu beginnen. Letzte Nacht wurden gleich mehrere von ihnen ermordet... von einem Nachtelf!\n\nZeugen berichten, dass der Täter ein Dämonenjäger war, einer von Illidans geisteskranken Schülern. So etwas sieht man nicht alle Tage. Ohne Zweifel hat die Macht ihn wahnsinnig gemacht, genau wie seinen Meister.\n\nIch bezahle ein überragendes Kopfgeld für einen Todesbeweis dieses Mörders. Man hat ihn zuletzt abseits der Straße in Norden in einem Tal unter dem Jadefeuerbach gesehen.", sourceObjective = "Tötet Feronas Sündschwelger.", completion = "Wie edel von Euch... einfach ohne zu fragen auf eine Mordmission zu gehen und meinen Kopf zu verlangen, nur weil ein anderer Euch darum bittet.\n\nZügelt Euren Zorn und hört Euch zuerst meine Geschichte an. Ihr werdet sehen, was edles Unwissen diesem Land angetan hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[28218] = { id = 28218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schicksal voll Feuer und Leid", description = "Meinesgleichen wurde schon immer für das gehasst, was wir tun... Verabscheute Ausgestoßenene, denen eine nicht mehr heilbare Verderbtheit vorgeworfen wurde.\n\nDoch es ist der Verdienst eines Dämonenjägers, dass diese Wälder hier nicht die größte Bastion der Brennenden Legion in Azeroth sind. Ich spreche von meinem Meister Illidan Sturmgrimm, dem \"Verräter\".\n\nSeht selbst. Seht, was hier geschehen ist, als Illidan befreit wurde und die dämonischen Mächte des Schreckenslords Tichondrius ohne Gegenwehr über diesen Wald herrschten...", sourceObjective = "Nehmt an Illidans Schlacht gegen Arthas teil.", completion = "Und so machte sich mein Meister auf, um den Schädel zu suchen... Er riskierte erneut sein Leben im Kampf gegen eine Armee von Dämonen, um den Quell der Verderbnis des Teufelswalds zu finden. Stellt Euch nur vor, er hätte es nicht getan! Stellt Euch vor, wie es hier aussehen würde, wenn der Schädel von Gul'dan sein Werk ungehindert fortgesetzt hätte...", sourceObjectiveStatus = "unverified-source-field" }
quests[28219] = { id = 28219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brummer fürs Baby", description = "<Der winzige Setzling breitet seine Blätter weit aus, wie ein Jungvogel, der gefüttert werden möchte. Er spricht mit sehr leiser Stimme:>\n\nHunger... will... Käfer...\n\n<Ihr könnt aus dem Süden das Summen von Wespen hören. Ob die sind, was der Kleine fressen möchte?>", sourceObjective = "Tötet 10 Eisenholzbrummer, um den Beschützersetzling zu füttern.", completion = "<Der Setzling reibt sich mit einem wurzeligen Arm den Stängel, als wäre er satt. Er scheint auch ein wenig gewachsen zu sein!>", sourceObjectiveStatus = "unverified-source-field" }
quests[28220] = { id = 28220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodensuche", description = "<Der winzige Setzling tapst herum und lenkt eure Aufmerksamkeit nach Süden. Ihr könnt gerade so eine leise Stimme hören.>\n\nBoden...<Offenbar möchte er frischen Erdboden. Vielleicht solltet ihr ihn zu einem der Flecken begleiten, die am fruchtbarsten aussehen.>", sourceObjective = "Bringt den Beschützersetzling zu 7 Flecken fruchtbaren Bodens.", completion = "<Der Setzling kräuselt seine Wurzeln, offenbar entzückt.>\n\nWachsen... groß...", sourceObjectiveStatus = "unverified-source-field" }
quests[28221] = { id = 28221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurzeln, wie zum Stampfen gewachsen", description = "Es gibt hier noch so viele andere Geister, die in verrottenden Körpern gefangen sind...\n\nSeht Ihr? Die Donnerstampfer der Eisenstämme im Norden. Die sind vor Dämonenzeug ganz krank und mit Pilzschlabber bewachsen. Die armen Geister in ihnen können nicht entkommen.\n\nIhr könnt helfen! Fällt sie und die Geister können raus. Ich stecke mir die Geister ein und wir können alle Freunde sein, wenn ich groß bin. Helft Ihr ihnen? Bitte?", sourceObjective = "Tötet 10 Donnerstampfer der Eisenstämme.", completion = "So glücklich! Könnt Ihr uns hören? Wir sind jetzt so viele Freunde.\n\nImmer größer und größer, mit Platz für alle Freunde...", sourceObjectiveStatus = "unverified-source-field" }
quests[28222] = { id = 28222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wochenend und Sonnenschein", description = "Wir wachsen immer großer... Zeit, dass wir strahlen! Zeit, unsere Blätter der Sonne entgegenzurecken!\n\nBringt mich zur Sonne! Die Sonne ist weit weg, aber ihre Strahlen kommen zu uns. Ihr Licht macht uns wieder groß und stark. Das Licht kommt die großen Äste hinunter zu den kleinen, wie unseren.\n\nDa drüben! Die Sonne kommt im Norden zu uns! Nehmt uns mit, nehmt uns zum Tanz!", sourceObjective = "Begleitet den Beschützersetzling zu 5 Sonnenstrahlen im Eisenwald.", completion = "So warm und frisch und voller Leben. Wir lieben die Sonne, sie macht uns stärker.\n\nBald nun, bald, ist die Zeit zum Wachsen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28223] = { id = 28223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wärter", description = "Wir haben es fast geschafft, die aufständischen Gefangenen im Loch zu beseitigen, doch ein Problem bleibt: Der Wärter.\n\nWärter Silva ist ihr Meister. Für ihn tun sie alles. Wenn wir ihn ausschalten, schalten wir alle aus. Tötet ihn und bringt mir seine Schlüssel. Mit den Schlüsseln können wir den Zellenblock weiter erkunden und hoffentlich auch zur Wasserversorgung der Insel vordringen.", sourceObjective = "Tötet Wärter Silva im Loch und kehrt mit seinen Schlüsseln zurück. Das Loch ist südwestlich der Baradinfestung.", progress = "Ist der Wärter endlich tot?", completion = "Aah, die Schlüssel des Wärters. Wieder einmal habt Ihr gute Arbeit geleistet, {name}. Diese Schlüssel werden sich noch als nützlich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28224] = { id = 28224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Beschützer", description = "Ahhh... ich danke Euch, <kleiner/kleine> {race}. Ich und andere haben schon so oft versucht, in diesem Wald zu wachsen, waren jedoch nie erfolgreich.\n\nDer siechende Beschützer, der im Norden sein Unwesen treibt, ist das einzige Urtum, der es seit der Verseuchung dieses Waldes zur Reife geschafft hat, aber sein Körper ist krank und sein Geist verrückt. So wie wir auch die Geister der Treants gerettet haben, möchte ich auch die Geister retten, die in ihm wohnen, anstatt sie ihrem Schicksal zu überlassen.\n\nBesiegt ihn und lasst seine Geister sich mir anschließen, bevor ich Wurzeln schlage.", sourceObjective = "Besiegt den siechenden Beschützer.", completion = "Ja... die Zeit ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28225] = { id = 28225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweist Eure Loyalität", description = "Ihr könnt gern für 'ne Weile hier in Meißelgriff bleiben, aber ich muss wissen, ob Ihr ein Freund seid.\n\nWir von der Thoriumbruderschaft sind nich' die einzigen Dunkeleisenzwerge hier in der Steppe. Ganz im Gegenteil. Wir sind ziemlich deutlich in der Unterzahl gegenüber den Dunkeleisenzwergen vom Schwarzfels. Unser Stützpunkt hier in Meißelgriff ist ausreichend sicher, aber sie stören uns noch immer aus den nahegelegenen Ruinen von Thaurissan im Norden.\n\nStellt Euch uns unter Beweis, {race}. Tötet sie für mich.", sourceObjective = "Tötet 10 Dunkeleisenzwerge in den Ruinen von Thaurissan.", completion = "Na, so was sieht man doch gern! Ihr seid in Ordnung, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28226] = { id = 28226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschrottete Golems", description = "Wir halten hier Wächtergolems. Die Zwerge nördlich von hier halten auch Golems, aber ich weiß nicht genau, warum.\n\nFürs Töten in erster Linie, denke ich zumindest.\n\nWir könnten Ersatzteile für unsere Golems brauchen, und ich habe auch schon einen Plan, wie wir sie bekommen können: Tötet deren Golems und sucht nach Teilen, die auf den Boden gefallen sind. Plündert alles, was nützlich ist. Ihr werdet nicht alles tragen können, also wählt die Teile mit Bedacht.", sourceObjective = "Tötet Kriegshäscher in den Ruinen von Thaurissan und sucht dann nach 3 Obsidiankolben, 3 Fluxausstoßsieben, 3 Thoriumgetriebewellen und nach einem steinernen Kraftkern unter den Kriegshäscherteilen, die zu Boden fallen.", progress = "Wir haben diese Golems selbst gebaut, wisst Ihr. Ein wenig mechanisches Handwerk, ein wenig elementares Handwerk... das Resultat ist gar nich' mal so schlecht, wenn Ihr mich fragt.", completion = "Das ist genau das, was wir brauchten. Ich lass die Jungs gleich mit der Arbeit am nächsten Schwung Golems anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28227] = { id = 28227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golemausbildung", description = "Ihr erweist Euch als ziemlich hilfreich, {race}. Ich hab' mir gedacht, Ihr könntet bei einer letzten Sache helfen.\n\nUnsere Wächter sind stark, aber nich' so stark, wie Ihr. Ich hab' mir gedacht, Ihr könntet, wenn Ihr nichts dagegen habt, ein paar unserer Golems bei ihrem Training helfen? Sprecht einfach einen an und kämpft ein paar mal mit ihm. Hoffentlich lernen sie was von Euren Kampfkünsten und werden besser.", sourceObjective = "Helft 4 gemeißelten Golems bei ihrer Kampfausbildung.", completion = "Ihr seid ein Lebensretter, {name}. Mit Golems wie diesen werden wir von den Dunkeleisenzwergen, den Schwarzfelsorcs... sogar von den Drachen nichts zu befürchten haben müssen!\n\nWenn Ihr jemals etwas von der Thoriumbruderschaft benötigen solltet, zögert nicht, uns zu fragen. Das gilt auch für Eure Freunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[28228] = { id = 28228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in den Wald", description = "Es ist jetzt Zeit, Lebewohl zu sagen. Ihr habt mich von Setzlingswurzeln an begleitet, und so kurz die Zeit auch war, muss ich mich jetzt wieder dem Wald anschließen.\n\nBringt mich zurück auf den Hügel, auf dem Ihr mich gefunden habt. Dort werde ich meine Wurzeln schlagen und im Schatten der Urtume wachsen, die vor mir kamen.", sourceObjective = "Bringt den erblühenden Beschützer zurück zu dem Hügel in der Mitte des Eisenwaldes.", sourceObjectiveStatus = "unverified-source-field" }
quests[28229] = { id = 28229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veranlagung und Umwelt", description = "Die Urtumbeschützer des Eisenwalds im Norden sind schon seit Jahren tot und ihre leblosen Hüllen sind ein Mahnmal für den Schaden, der diesem Land zugefügt worden ist.\n\nVier Mal im Jahr tragen wir Wasser von diesem Mondbrunnen zu ihnen und bewässern den Boden dort - in der Hoffnung, dass daraus neues Leben entspringen wird. Wenn Ihr möchtet, könnt Ihr das Wasser selbst dorthin bringen.\n\nEs ist eine ausgezeichnete Gelegenheit, in sich zu gehen. Nehmt diese Phiole und füllt sie am Mondbrunnen, gießt sie dann auf der Spitze des kleinen Hügels zwischen den drei Urtumen aus.", sourceObjective = "Füllt die Phiole am Mondbrunnen im Wisperwindhain und gießt sie auf dem Boden zwischen den toten Urtumbeschützern im Eisenwald aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28230] = { id = 28230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallregelung", description = "Bevor der Aufseher sein Fett weg kriegt, müssen wir uns um diesen Ausbruch kümmern. Wir können es nicht riskieren, diesen Erreger auf die Welt loszulassen.\n\nIm Arbeiterquartier direkt nördlich von hier treibt sich eine Monstrosität herum, die von Stillwasser aus drei Bauern zusammengeflickt wurde. Dieses Ungeheuer muss zerstört werden, wenn wir die Schlickfelder sichern wollen. Die Notfallregelungen verlangen es so.", sourceObjective = "Tötet die Ray-Getz-Kalaba-Monstrosität.", completion = "Sobald wir uns um die restlichen Untoten gekümmert haben, ziehen wir Stillwasser zur Rechenschaft!", sourceObjectiveStatus = "unverified-source-field" }
quests[28231] = { id = 28231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Glitzer", description = "Aufseher Stillwasser hat mich ins Feld geschickt, um diesen Ausbruch zu untersuchen. Als ich hier ankam, sind Glitzer und ich von dieser schwerfälligen Monstrosität namens Verringtan angegriffen worden. Ich fiel von Glitzers Rücken und rannte sofort um mein Leben. Glitzer hielt aber die Stellung und hielt das Biest auf. Leider wurde sie aber überwältigt und anschließend in den Boden gepflanzt, als wäre sie so eine Art glorreicher Sternenponysetzling.\n\nSie hat ihr Leben gegeben, um mich zu beschützen. Ich will Rache! Wenn Ihr es für nichts anderes tun wollt, dann tut es für Glitzer!", sourceObjective = "Tötet den Schmied Verringtan.", completion = "Sie kommt jetzt in den großen Pferdehimmel in den Sternen. Wir werden dich niemals vergessen, Glitzer. NIEMALS!", sourceObjectiveStatus = "unverified-source-field" }
quests[28232] = { id = 28232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essen von unten", description = "Uns gehen die Vorräte im Lager aus, {name}. Wir haben vor Kurzem von einem Zellenblock südwestlich von hier gehört, in dem nach jahrelangem Betrieb noch Rationen übrig sind. Wir brauchen so viele Rationen wie ihr tragen könnt hier im Lager.\n\nOh, und noch etwas: in dem Zellenblock wimmelt es von Gefangenen, also seid vorsichtig.", sourceObjective = "Ihr wurdet gebeten, 12 Rationen aus dem Zellenblock aus dem Loch südwestlich der Baradinfestung zu besorgen.", progress = "Konntet Ihr die Rationen ausfindig machen? Berichten zufolge kann man sie über den ganzen Ort verteilt finden.", completion = "Die Rationen werden unseren Truppen sehr helfen, {name}. Vielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28233] = { id = 28233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Bruder", description = "Mein Bruder Bahrum ist verschwunden!\n\nEr war einer der ersten, die die Gegend ausgekundschaftet haben. Alle anderen sind zurückgekehrt, aber von ihm fehlt jegliche Spur. Papa meint, dass er nur irgendwo herumschlawenzelt, aber er ist mein einziger Bruder, und ich habe meiner Mutter versprochen, auf ihn aufzupassen. Könnt Ihr ihn finden?", sourceObjective = "Findet Bahrum Schmiedehammer.", completion = "He, nicht schauen! Ich hab keine Hosen an!", sourceObjectiveStatus = "unverified-source-field" }
quests[28234] = { id = 28234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Hosen!", description = "Warum ich in der Kornkiste stehe? Mh, um es zusammenzufassen, da waren Hornissen und Anhänger des Drachenmalklans, die zu einem recht ungünstigen Zeitpunkt aufgeschlagen sind. Ich konnte mich in Sicherheit bringen, aber meine Beinschützer haben die Bastarde an sich genommen! Meine Schwester hat sie selbst für mich angefertigt und sogar meinen Namen eingearbeitet... Ich würde sterben vor Scham, wenn sie rausfindet, dass ich sie verloren habe.\n\nBitte, findet sie für mich. Ich habe gesehen, wie der Hosendieb in die Festung dort drüben gegangen ist. Ich werde mich hier weiterhin *räusper* bedeckt halten. Und fragt einen Wildhammer nie, was er unter seinem Kilt trägt!", sourceObjective = "Findet Bahrums Beinschützer.", progress = "Habt Ihr sie gefunden? Das Korn kratzt ganz schön.", completion = "Vielen Dank! Und jetzt dreht Euch um, damit ich sie anziehen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[28235] = { id = 28235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uferbach muss sterben", description = "Magistrat Uferbach war einst der Bürgermeister dieser Gegend. Zu Lebzeiten war er ein mächtiger Gegner in der Schlacht um das Hügelland. Im Untod wird er unsere Fähigkeiten sicher auf die Probe stellen.\n\nUferbach kanalisiert mächtige arkane Magie im nordwestlichen Teil der Schlickfelder. Führt uns dorthin und gemeinsam werden wir seiner Herrschaft ein für alle Mal ein Ende bereiten.", sourceObjective = "Tötet Magistrat Uferbach.", progress = "Verschwendet nicht meine Zeit, {name}.", completion = "Jetzt lassen wir Aufseher Stillwasser Gerechtigkeit erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[28237] = { id = 28237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Seuche überzieht das Land", description = "Nun da der Ausbruch des Untodes eingedämmt wurde, ist es an der Zeit, Aufseher Stillwasser und seine Gefolgsleute zur Rechenschaft zu ziehen. Auch wenn wir eine Tragödie verhindert haben, deren Ausmaß dem der Invasion der Geißel geglichen hätte, müssen wir sicherstellen, dass so etwas nie wieder geschehen kann. Sie werden alle den wahren Tod erleiden!\n\nKommt, {name}! Ich will Stillwassers Kopf rollen sehen.", sourceObjective = "Schlagt Aufseher Stillwasser den Kopf ab.", progress = "Verschwendet nicht meine Zeit, {name}.", completion = "Ich werde diesen Kopf persönlich der Bansheekönigin überbringen. Natürlich werde ich Eure Rolle bei alldem erwähnen, {name}.\n\nWas Eure Belohnung betrifft - nehmt Euch aus Stillwassers Vorräten, was immer Ihr wollt. Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[28238] = { id = 28238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtufer", description = "Die Zeit ist gekommen, {class}. Nun da Sturmwind sicher ist, werden wir die Schlacht zu unseren Feinden tragen. Auf ins Hochland!\n\nDer Großteil unserer Flotte ist schon unterwegs, dank Eurer Bemühungen. Aber Fargo Flintlocke hat ein Wasserflugzeug vorbereitet, in dem Ihr die Reise doppelt so schnell hinter Euch bringen könnt.\n\nSprecht unten am Hafen mit Flintlocke, und sagt ihm, dass Ihr bereit seid, ihn ins Hochland zu begleiten. Er wird sich am Wasser befinden. Gute Reise, {name}.", sourceObjective = "Sprecht mit Fargo Flintlocke im Hafen von Sturmwind.", completion = "Ein Flug ins Hochland soll's also sein? Da hab' ich genau das Richtige!\n\nIch mach' Euch mal ein bisschen Platz in meinem Wasserflugzeug. Ich werd' wohl das Katzenfutter wieder rauswerfen müssen - Ihr wisst schon, falls wir in den Bergen abstürzen und wochenlang keine Aussicht auf Rettung haben.\n\nWenn ich's mir so überlege, nehmt das Katzenfutter doch einfach auf den Schoß, aye.", sourceObjectiveStatus = "unverified-source-field" }
quests[28239] = { id = 28239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schwarzzahnunterschlupf", description = "Das ist nicht unbedingt die... überzeugendste Verkleidung, die ich je gesehen habe, aber sie wird schon ausreichen. Bei verdeckten Ermittlungen geht es ja auch eigentlich fast nur um Wichtigtuerei. Verhaltet Euch einfach, als hättet Ihr alles Recht der Welt, dort zu sein und es wird schon klappen.\n\nEure Kontaktperson im Schwarzzahnunterschlupf ist ein Orc mit Namen Rüstmeister Kaoshin. Er weiß NICHT Bescheid, dass Ihr ein Spion seid, also haltet Euch bedeckt.\n\nErfüllt, worum auch immer Kaoshin Euch bittet. Oberst Trottmann wird mittels des Gnomcorders Kontakt mit Euch halten und Euch genauere Anweisungen geben.\n\nViel Glück da draußen, <Soldat/Soldatin>.", sourceObjective = "Sprecht mit Rüstmeister Kaoshin im Schwarzzahnunterschlupf in der Brennenden Steppe.\n\nBereitgestellter Gegenstand:", completion = "Wo bleibt Ihr denn, Grunzer? Ihr seid spät dran! Gebt mir auch nur einen Grund, warum ich Euch nicht auf der Stelle einen Kopf kürzer machen sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[28240] = { id = 28240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgebrannt", description = "Hört her, {name}. Ihr wisst ja, dass ich nur dafür da bin, Euch zu unterhalten und dass ich mir alle Mühe gebe, Euch angenehm beschäftigt zu halten und so weiter.\n\nAber wie es der zufall nun will sind mir völlig die Ideen ausgegangen.\n\nDas war's!\n\nNormalerweise fallen mir beim Questen mit Euch immer ein paar Dinge ein, die ich Euch als nächstes tun lassen kann, was mir wiederum Zeit verschafft, das nächste großartige Ziel auszudenken. Aber damit ist es jetzt vorbei.\n\nIch stehe mit leeren Händen da. Völlig eingebungslos. Könnte mir nicht mal etwas einfallen lassen, wenn mein Leben davon abhinge.\n\nOh, moment mal! Ich weiß, was wir machen können!\n\nSprecht noch einmal in ein bis zwei Wochen mit mir...", sourceObjective = "Harrison Jones möchte, dass Ihr in ein bis zwei Wochen noch einmal mit ihm sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28241] = { id = 28241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vision des Zwielichts", description = "Cho'gall bleibt über seine Diener durch diese seltsamen magischen Kugeln informiert: \"Die Augen des Zwielichts\".\n\nWenn Ihr eine davon beschaffen könntet, glaube ich, dass wir Cho'gall ausspionieren und sehen können, was seine Diener treiben. Besorgt mir eine!\n\nSucht im Schwarzen Riss östlich von hier, nördlich des Flusses. Findet ein Auge des Zwielichts, und tut, was auch immer getan werden muss, um es zu mir zu bringen.", sourceObjective = "Findet ein Auge des Zwielichts im Schwarzen Riss.", completion = "<Das Auge liegt vor Euch und summt unheilvoll vor dunkler Energie.>\n\n<Ohne Warnung dreht sich die Kugel, als sehe sie Euch an. Ihr spürt die Anwesenheit des Bösen, als sei die Kugel lebendig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28242] = { id = 28242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir müssen alle Opfer bringen", description = "<Das Auge spricht mit Euch; seine 'Stimme' scheint aus allen Richtungen zugleich zu erschallen.>\n\nIhr wünscht einen Blick durch mich zu werfen, {race}? Meine Macht ist nur für einen bestimmten Preis zu haben. Diese Jünger des Zwielichts haben mich mit dem Blut der Wildhammerzwerge beehrt, aber ich verspüre immer noch Durst. Vielleicht könntet Ihr es besser machen.\n\nTötet meine alten Herren und meine Visionen gehören Euch. Ehrt mich, indem Ihr Schamanen der Schwärze tötet. Schließlich ist ein Blut so gut wie das andere.", sourceObjective = "Tötet 10 Schamanen der Schwärze.", progress = "Ich habe Euch beobachtet, {race}.", completion = "<Das Auge glänzt dunkel und Farben huschen über seine dunkle Oberfläche.>\n\nAh, die saftige Genugtuung eines erloschenen Lebens. Könnt Ihr es spüren, {class}? Genießt Ihr es so sehr wie ich?\n\nNein, wie ich sehe, ist dem nicht so. Ihr kämpft, um das Leben Anderer zu schützen. Wie schade.", sourceObjectiveStatus = "unverified-source-field" }
quests[28243] = { id = 28243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Auge des Betrachters", description = "Nun gut, {race}. Ihr habt Euch meine Dienste mit Blut erkauft. Bringt mich zum \"Unterschamanen\" von Donnermar.\n\nOh ja, ich weiß bereits, wohin Ihr mich bringen werdet. Blundys mittelmäßige, biergetränkte Fähigkeiten sind uninteressant. Ihr jedoch - Ihr fasziniert mich, {race}. Stellt Euch nur vor, welche Verwüstung wir in dieser erbärmlichen Welt mit meiner Sicht und Euren Fähigkeiten gemeinsam anrichten könnten...", sourceObjective = "Bringt das Auge des Zwielichts zum Unterschamanen Blundy in Donnermar im Schattenhochland.", progress = "Ihr wieder? Wat? Wat bringt'n Ihr mir da?", completion = "Ihr habt eins gefunden? Ein richtig echtes Auge des Zwielichts? Lasst mal sehen.\n\nIhr Götter. Es guckt mich an. Glotzt ja genau zurück!\n\nIch brauch 'nen Kurzen. Könnt Ihr das Ding zur Wand drehen, oder so?", sourceObjectiveStatus = "unverified-source-field" }
quests[28244] = { id = 28244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe was, was Ihr nicht seht...", description = "Ich will ehrlich sein, {name}. Das Ding macht mich nervös. Aber wo Ihr Euch so viel Mühe gemacht habt, es hierher zu bringen, denke ich mal, wir sollten auch Gebrauch davon machen.\n\nIhr zuerst.\n\nSchaut in das Auge und lasst es Euch das Innere von Cho'galls Bastion des Zwielichts zeigen. Wir finden schon noch heraus, was der dicke, zweiköpfige Schlingel im Schilde führt und benutzen das dann gegen ihn.", sourceObjective = "Schaut in das Auge des Zwielichts für den Unterschamanen Blundy.", completion = "Was habt Ihr gesehen, {name}? Cho'gall? Moment - er hat EUCH gesehen?\n\nOh, aye. Dieses tückische kleine Auge! Das schaut in beide Richtungen. Dieser freche Glubscher! Wo is' mein Hammer!?", sourceObjectiveStatus = "unverified-source-field" }
quests[28245] = { id = 28245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grunzertreiberei", description = "Pah! Ihr habt Glück, dass mir heute die Arbeitskräfte fehlen. Sonst hätte ich Euch für diese Woche zu <meinem Prügelknaben/meinem Prügelmädchen> gemacht.\n\nDie Stiefel der Offiziere und hochrangigen Soldaten müssen gewienert werden. Sie stehen draußen vor ihren Hütten.\n\nIch möchte mich darin spiegeln können, Grunzer! An die Arbeit!", sourceObjective = "Poliert 7 Paar Schwarzfelsstiefel sehr gründlich.", completion = "Hmpf. Gute Arbeit, Grunzer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28246] = { id = 28246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personaleinsparungen", description = "<Rauschen> {name}... {name}, könnt Ihr mich hören? Hier spricht Trottmann.\n\nHört zu, wir haben gerade erst neue Informationen für Eure nächste Mission erhalten. Wir möchten, dass Ihr drei Personen unschädlich macht. Das erste Ziel ist Voodooist Timan, den Ihr oben auf der Aschensäule findet. Worgmeisterin Othana hält sich in den Worgzwingern in der Mitte des Lagers auf. Das letzte Ziel, Gorlop, befindet sich in der Nähe der Lavateiche im Süden.\n\nIhr findet die Skorpidstachel, die Ihr gesammelt habt, in Euren Habseligkeiten. Wendet die Stachel zur richtigen Zeit auf die Zielpersonen an.", sourceObjective = "Benutzt den rasiermesserscharfe Skorpidstachel, um Voodooist Timan auf der Aschensäule, Worgmeisterin Othana in den Worgzwingern und Gorlop bei den Lavateichen auszuschalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28247] = { id = 28247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte ihrer Art", description = "Obsidia ist eins der letzten ausgewachsenen Drachenweibchen, die die Blutlinie des schwarzen Drachenschwarms fortsetzen könnte. Sie muss getötet werden.\n\nWenn Ihr sie erfolgreich töten könnt, solltet Ihr Lirastrasza sofort von Eurem Sieg unterrichten. Sie arbeitet schon lang auf dieses Ziel hin.\n\nDanke, dass Ihr in diesen Schlachten unsere Speerspitze wart. Ihr habt Euch als <ein mächtiger Verbündeter/eine mächtige Verbündete> herausgestellt.", sourceObjective = "Tötet Obsidia.", completion = "Ihr habt Obsidia in ihrem eigenen Hort besiegt? Beeindruckend, {race}. Es tut mir leid, dass ich nicht dabeisein konnte.\n\nIhr steht zu Eurem Wort und Eure Versprechen sind nicht nur Schall und Rauch. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28248] = { id = 28248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gipfel des Siegers", description = "Ihr habt Eure Absichten und Fähigkeiten mehr als bewiesen. Nun, da Grim Batol abgeschnitten und die Schwarzdrachen verjagt wurden, sitzen die Schattenhammerkultisten in ihrer Zitadelle in der Falle.\n\nSucht Eure Anführer auf. Sie sollten nordöstlich von hier am Gipfel des Siegers sein. Lasst sie wissen, dass zu Beginn des Angriffs auf die Schattenzitadelle die roten Drachen in den Himmeln kreisen werden. Ihr werdet nicht für all die Taten Eurer Verbündeten Buße tun können, aber in diesem einen Kampf werden wir an Eurer Seite sein.\n\nDer Schattenhammer wird fallen!", sourceObjective = "Sprecht mit Kurdran Wildhammer am Gipfel des Siegers.", completion = "Ihr habt gute Arbeit geleistet, {name}. Wir sind gerade dabei, den Angriff vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28249] = { id = 28249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmetterschlagposten", description = "Ihr habt Euren Willen und Eurer Können mehr als ausreichend bewiesen. Jetzt, da Grim Batol abgeschnitten ist und die schwarzen Drachen besiegt sind, sitzt der Schattenhammer in seiner Zitadelle in der Falle.\n\nGeht zu Euren Anführern. Ihr findet sie im Westen, im Schmetterschlagposten. Lasst sie wissen, dass der rote Drachenschwarm die Himmel zum Beben bringen wird, wenn der Angriff auf die Schattenzitadelle beginnt. Vielleicht könnt Ihr nicht für alle Sünden büßen, die Eure Verbündeten begangen haben, aber in dieser Schlacht werden wir Euch zur Seite stehen.\n\nDer Schattenhammer wird fallen.", sourceObjective = "Sprecht mit Kriegsfürstin Zaela im Schmetterschlagposten.", completion = "Ihr habt gute Arbeit geleistet, {name}. Wir sind gerade dabei, den Angriff vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28250] = { id = 28250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Pflücker", description = "Ich habe nicht den glanzvollsten Beruf in der Welt.\n\nKriegsangelegenheiten und die tiefen Geheimnisse der Hallen von Uldum oder sonst was kümmern mich wenig.\n\nIch trage die Verantwortung über diesen Boden... und dieser Boden lässt Datteln wachsen.\n\nNun sind diese Dattelpflücker gefräßig genug geworden, sich gegenseitig auf die Schultern zu steigen und zu versuchen, meine kostbaren Früchte zu stehlen.\n\nDamit ist jetzt Schluss.\n\nNehmt diesen Hammer - er wurde von den Titanen gefertigt und trägt den Segen der Sonnenkönige und wer weiß was noch alles - und macht diese Kümmerlinge platt!", sourceObjective = "Vermöbelt 30 Sandpygmäen mit dem Hammer der Tahretdynastie", completion = "Ihr habt diesen diebischen Plagegeistern gezeigt, wo der Hammer hängt. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[28251] = { id = 28251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Süderstade", description = "Ich war in Süderstade stationiert, bevor man mich gefangengenommen und eingesperrt hat. Bei den Ruinen habe ich in erster Linie Schlammproben entnommen und sichergestellt, dass die Seuche, die wir freigesetzt hatten, sicher verbreitet wird. Das wäre ohne die ständigen Angriffe der Worgen eine leichte Arbeit gewesen.\n\nIch möchte, dass Ihr Euch nach Süderstade begebt und nach meinem Lehrling Serge Hinott sucht. Ich muss wissen, ob es ihm gut geht, und er muss wissen, dass ich zurückkommen werde, wenn meine Arbeit hier beendet ist.\n\nDie Ruinen von Süderstade sind in der Nähe der Küste, südöstlich von hier.", sourceObjective = "Sprecht mit Serge Hinott bei den Ruinen von Süderstade im Vorgebirge des Hügellands.", completion = "Die Situation mit den Worgen hat sich nicht verbessert und Helcular macht mir echt Angst.", sourceObjectiveStatus = "unverified-source-field" }
quests[28252] = { id = 28252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn des Kodorufers", description = "Nun gut, ich habe richtige, ehrliche und sogar wichtige Arbeit für Euch! Wir müssen die Kodos rufen, die in den Gebieten südlich von hier grasen. General Thorg'izog sagt, dass wir bald ins Rotkammgebirge aufbrechen, und ich kann nicht zulassen, dass wir ohne die Kodos aufbrechen.\n\nBenutzt dieses Horn in der Nähe eines Kodos. Sobald es den Ruf hört, wird es sich auf in Richtung Lager machen.\n\nIhr müsst aber aufpassen. Manchmal sind die Kodos ein bisschen angriffslustig, und es kann sein, dass Ihr ein bisschen mit ihnen 'spielen' müsst, bevor sie auf Euch hören.", sourceObjective = "Benutzt das Horn der Rufer, um 7 Kriegskodos des Schwarzfels zurück zum Lager zu rufen. Bekämpft feindselige Kodos, bis sie aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28253] = { id = 28253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir behalten das Horn", description = "{name}, Trottmann hier. Ich will, dass Ihr dieses Horn behaltet. Ich bin sicher, dass wir improvisieren können, um es in unseren Plan einzubinden.\n\nIch bin etwas besorgt über das, was Kaoshin zum Angriff auf das Rotkammgebirge gesagt hat. Wir wussten, dass ein neuer Angriff aussteht, aber wir haben uns um mehrere Tage verrechnet.\n\nKehrt mit dem Horn zu mir zurück. Wir werden hier in Meißelgriff weitersprechen. Versucht, Eure Verkleidung nicht zu verlieren. Ihr seid mit Eurer verdeckten Arbeit noch nicht fertig.", sourceObjective = "Bringt das Horn der Rufer zurück zu Oberst Trottmann in Meißelgriff in der Brennenden Steppe.", progress = "Willkommen zurück, Soldat.", completion = "Ich hatte nicht damit gerechnet, einen Gegenstand wie diesen erhalten zu können. Unsere Pläne werden dementsprechend geändert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28254] = { id = 28254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nadel im Höllhaufen", description = "Ihr und ich können uns zu zweit keiner Armee stellen, {name}. Wir werden zahlenmäßig überwältigt werden. Deswegen müssen wir uns genau an Trottmanns Plan halten.\n\nFür den nächsten Schritt laut Plan bedarf es etwas Feingefühls... und darin bin ich nicht besonders gut. Hier kommt Ihr ins Spiel.\n\nSprecht mit Thelaron Düsternadel, dem Schneider hier vor Ort. Ich habe ihm bereits die Bälge und den Schlamm gegeben, die Ihr gesammelt habt. Er muss Eure Maße nehmen.\n\nGenau, {name}: Wir werden Euch als einen der Feinde verkleiden.", sourceObjective = "Sprecht mit Thelaron Düsternadel in Meißelgriff in der Brennenden Steppe.", completion = "Ihr braucht eine Verkleidung? Nun, da seid Ihr genau am richtigen Ort, Schätzchen.\n\nLasst mich mal sehen.... mm-hmm. Ich weiß genau, was wir machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28255] = { id = 28255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was kommt als Nächstes?", description = "Wie wird das alles enden? Hmm?\n\nWerde ich mich gegen meinen dunklen Meister stellen, wer auch immer das sein mag?\n\nWerde ich zu einem einfühlsameren und teilnahmsvolleren Anführer werden?\n\nOder werde ich meine Ambitionen umsetzen, mit allen Mitteln voranstürmen und nicht ruhen, bis ganz Azeroth mir gehört?\n\nUnd was dann, hmm?\n\nVielleicht klärt sich ja alles nächste Woche...\n\n... oder vielleicht die Woche darauf...", sourceObjective = "Kommandant Schnottz will doch nur umarmt werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[28256] = { id = 28256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schädel des Gul'dan", description = "Illidan ist aufgebrochen, um den Schädel des Gul'dan zu finden. Er hat ganze Armeen von Dämonen bekämpft und sie mit einer Kraft getötet, die ihn zu einem verhassten Ausgesetzten gemacht haben.\n\nStellt Euch ihm in der Schlacht, {name}. Werdet Zeuge vom stärksten Kämpfer gegen die Verderber Teufelwalds und erledigt ihn.", sourceObjective = "Erlebt Illidans Kampf um den Schädel von Gul'dan.", completion = "Nun werdet Ihr bald verstehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28257] = { id = 28257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz von Tichondrius", description = "Ja, Illidan hat die Macht des Schädels von Gul'dan erlangt.\n\nAber ist er damit in die Dunkelheit geflohen? Hat er sie für seinen eigenen Ruhm genutzt? Nein... seine erste Tat mit der neuerlangten Macht war es, den Schreckenslord Tichondrius anzugreifen!\n\nWerdet Zeuge seines Triumphs, {name}. Werdet Zeuge davon, wie Illidan Teufelswald von den Dämonen befreite... und von dem Dank, den er dafür erhalten hat.", sourceObjective = "Erlebt Illidans Kampf mit Tichondrius.", completion = "Habt Ihr es gesehen? Mein Meister hat das getan, was getan werden musste, um die Dämonen aus diesen Ländern zu vertreiben, und zum Dank wurde er verbannt.\n\nDie Druiden richten nun alles und klopfen sich auf die Schultern, weil sie die Überreste der Streitmächte der Legion vertrieben haben.\n\nDas ist aber nicht der Grund, warum ich sie getötet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28258] = { id = 28258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Ander Germaine", description = "Ander Germaine hat Euch eine Nachricht zukommen lassen. Er möchte, dass Ihr ihn in der Kommandozentrale in Sturmwinds Altstadt besucht, so schnell Ihr könnt. Es klang sehr wichtig, {name}.", sourceObjective = "Sprecht mit Ander Germaine in der Kommandozentrale südlich von Sturmwinds Altstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28259] = { id = 28259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Demisette Cloyce", description = "Soeben habe ich eine Nachricht von Demisette Cloyce in Sturmwind erhalten. Sie fordert Euch auf, sie im Gasthaus Zum Geschlachteten Lamm zu treffen. Genaueres zu diesem Treffen hat sie nicht angegeben, aber ich hatte den Eindruck, dass es sich um etwas Wichtiges handelt.", sourceObjective = "Sprecht mit Demisette Cloyce im Keller des Gasthauses Zum Geschlachteten Lamm im Magierviertel von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28260] = { id = 28260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Wulf Hansreim", description = "Wulf Hansreim hat aus Sturmwind Kunde geschickt - er möchte Euch so bald wie möglich treffen. Ihr werdet ihn in der Kommandozentrale südlich der Altstadt von Sturmwind auffinden können.", sourceObjective = "Sprecht mit Wulf Hansreim in der Kommandozentrale südlich von Sturmwinds Altstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28261] = { id = 28261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrüger in unserer Mitte", description = "Nun, da Ihr in der Unvoreingenommenheit unterrichtet wurdet, möchtet Ihr vielleicht erfahren, WARUM ich diese Druiden getötet habe.\n\nDie Antwort ist einfach: Sie sind keine Druiden.\n\nDämonen suchen die Ruinen noch immer heim und haben die Gestalt von friedlichen Hütern angenommen. Seht es Euch mit eigenen Augen an - diese Augenbinde hier ist von dem Blut eines Dämonen getränkt. Nehmt sie und geht zur Jadefeuerschlucht in den Hügeln nördlich von hier, und verbindet Euch dort die Augen damit. Sie ermöglicht es selbst dem nichtsahnendsten Narren, die wahre Natur eines Dämonen zu erkennen.", sourceObjective = "Tötet 12 Jadefeuerschleicher in der Jadefeuerschlucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28262] = { id = 28262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Lord Tony Romano", description = "Lord Tony Romano, einer der erfahrensten Schurkenlehrer von Sturmwinds SI:7, hat verlauten lassen, dass er Euch sprechen möchte. Begebt Euch so bald wie möglich nach Sturmwind und sucht ihn im Gebäude des SI:7 südlich von Sturmwinds Altstadt auf.", sourceObjective = "Sprecht mit Lord Tony Romano im Hauptquartier von SI:7 südlich von Sturmwinds Altstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28263] = { id = 28263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Maginor Dumas", description = "Soeben habe ich eine Nachricht von Maginor Dumas, dem führenden Magierlehrer in Sturmwind erhalten. Er bittet Euch, ihn im Magiersanktum in Sturmwind zu besuchen, sobald Euch die Reise möglich ist.", sourceObjective = "Sprecht mit Maginor Dumas im Magiersanktum im Magierviertel von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28264] = { id = 28264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Navarax' Schachzug", description = "Ich habe diesen betrügerischen Dämonen lange aufgelauert und endlich den Standort ihres Anführers ausfindig gemacht. Es handelt sich dabei um keinen geringeren als den Erzdruiden Navarax, Anführer des Smaragdkreises.\n\nDer Dämon schützt sich selbst durch Unschuldige. Wenn ich den Wisperwindhain betreten würde, um ihn zu jagen, so würden mich seine unwissenden Beschützer abhalten... aber Ihr! Ihr könnt ihn unbemerkt erwischen.\n\nBegebt Euch erneut zum Wisperwindhain. Steigt den Druidenturm hinauf - ganz oben werdet Ihr Navarax finden, in seinem Raum inmitten der Zweige.", sourceObjective = "Tötet den Dämonen, der als Erzdruide Navarax erscheint.", completion = "Es fällt mir schwer, Euch das alles zu glauben, aber die Leiche des Dämons ist Beweis genug.\n\nIch werde umgehend eine Untersuchung der Druiden am Jadefeuerbach in die Wege leiten, und dafür sorgen, dass meine Vorgesetzten alle wissen, dass der Dämonenjäger wohl kein Problem damit hat, im Exil zu bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28265] = { id = 28265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Thorg'izog", description = "Kaoshin hat sich als hilfreicher herausgestellt, als wir vermutet hatten, aber jetzt brauchen wir ihn nicht mehr. Es ist an der Zeit, mit dem General zu sprechen. Ich glaube, Ihr seid bereit.\n\nGeneral Thorg'izog ist einer der \"großen Drei\", die die Bodentruppen in der Brennenden Steppe anführen. Er befindet sich in der Schwarzfelsfestung im Nordwesten. Zieht Eure Verkleidung an und sprecht mit ihm. Versucht, sein Vertrauen zu gewinnen. Trottmann wird sich bei Euch melden, sollte ich noch etwas von Euch brauchen.", sourceObjective = "Sprecht mit General Thorg'izog.", completion = "Noch mehr Außenstehende? Was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[28266] = { id = 28266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmataufe", description = "Ich muss aus dieser Situation das Beste machen. Diese Goblinsöldner haben mir diesen riesigen Feuerelementar als \"Dankeschön\" geschickt, weil ich sie angeheuert habe. Was soll ich denn hier in der Steppe mit einem Elementar anfangen? Das ist ja fast, wie Wasser zum Meer zu tragen.\n\nWenn Ihr nach Arbeit sucht, so könnt Ihr Euch nun beweisen. Sprecht mit diesem Goblin hier und fordert seinen Elementar zum Kampf heraus. Ich werde dem Sieger meinen Respekt zollen und meine Zeit geben.", sourceObjective = "Sprecht mit Würtl Sprillhuper und bittet ihn, Magmalord Kolob freizulassen. Besiegt danach Magmalord Kolob im Kampf.", progress = "Was ist los? Habt Ihr Angst?", completion = "Ich hatte fast damit gerechnet, dass Ihr als Sieger hervortreten würdet. Mir gefällt Eure Art, zweifellos.", sourceObjectiveStatus = "unverified-source-field" }
quests[28267] = { id = 28267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschießungskommando", description = "Folgt mir nach draußen, {race}.\n\nIch möchte, dass Ihr etwas mitanseht.", sourceObjective = "Sprecht mit Kommandant Schnottz.", completion = "Schnottz arbeitet also für Todesschwinge?\n\nDas ist weitaus beunruhigender, als Ihr Euch vorstellen könnt...", sourceObjectiveStatus = "unverified-source-field" }
quests[28268] = { id = 28268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Lord Grayson Schattenbruch", description = "Lord Grayson Schattenbruch der Kathedrale des Lichts in Sturmwind hat Euch einen Nachricht geschickt. Er möchte, dass Ihr Euch bei ihm meldet, wenn Ihr das nächste Mal in der Stadt seid. Ihr könnt ihn im Kathedralenviertel finden.", sourceObjective = "Sprecht mit Lord Grayson Schattenbruch bei der Kathedrale des Lichts in Sturmwinds Kathedralenviertel.", completion = "Ich wünschte, Ich hätte gute Nachrichten für Euch, {name}, aber leider habe ich Euch hierher gebeten, weil wir Euer Talent brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28269] = { id = 28269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft mich in Vir'sar", description = "Hört mir gut zu, {name}.\n\nIch wusste, dass die Obelisken etwas mit der Lade der Verheißung zu tun haben, aber das ist noch nicht alles.\n\nEs scheint, dass es mit der Lade etwas sehr Wichtiges auf sich hat - etwas, das die Schöpfer die Hallen des Ursprungs nennen.\n\nNun, da wir wissen, dass dieser Schnottz und seine Truppe mit Todesschwinge im Bunde sind, ist es nur noch dringlicher, dass wir die Lade zuerst bekommen.\n\nIch werde nördlich von hier in der Oase Vir'sar auf Euch warten.\n\nBeeilt Euch! Sie haben bereits einen Vorsprung!", sourceObjective = "Sprecht mit Harrison Jones in der Oase Vir'sar.", completion = "Ahh, freut mich, dass Ihr es geschafft habt.\n\nIch könnte hier etwas Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28270] = { id = 28270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sozius", description = "In Ordnung, {name}, ich stehe kurz davor, den letzten Obelisken aktivieren zu können.\n\nMir fehlen nur noch ein paar Informationen, und mit ein bisschen Glück werden wir sie vor Ort finden können.\n\nDie Vorräte sind schon eingepackt. Sagt Bescheid, wenn Ihr bereit seid.", sourceObjective = "Begleitet Harrison zur Oase Vir'sar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28271] = { id = 28271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Produktivitätseinbußen", description = "Also, {name}. So viel konnte ich herausfinden.\n\nAn einem Ort namens Hallen des Ursprungs gibt es ein Gerät der Titanen. Es soll eine Art Notfallschalter sein, der alles Leben in Azeroth zurücksetzt. Wenn er aktiviert wird, wird jedes Lebewesen auf der ganzen Welt vernichtet!\n\nNatürlich ist es nur für den absoluten Notfall gedacht, aber wenn es Todesschwinge gelingt, die titanischen Wächter zu verderben, kann er den Inhalt der Lade benutzen, um das Gerät auszulösen.\n\nGeht zum Obelisken des Mondes, {name}. Haltet sie auf!", sourceObjective = "Tötet 15 Ausgräber von Schnottz oder Aufseher von Schnottz.", completion = "Schnottz' Männern habt Ihr es gezeigt.\n\nEure Lektion werden sie so schnell sicher nicht vergessen.\n\nHoffentlich hat uns das die nötige Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[28272] = { id = 28272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlende Stücke", description = "Mir fehlen nur noch ein paar spezielle Informationen.\n\nSobald diese Lücken geschlossen sind, werden wir bereit sein, den letzten Obelisken zu aktivieren. Dann beginnt der Wettlauf um die Lade der Verheißung gegen Schnottz und seine Handlanger.\n\nDie Narren graben diesen Ort so schnell sie können um. Sie richten mehr Schaden an, als sie finden.\n\nGeht zum Obelisken und durchsucht ihre Beute, {name}.\n\nSchaut, ob Ihr unsere fehlenden Puzzleteile finden könnt.", sourceObjective = "Sammelt 7 uralte Kupferschriftrollen.", progress = "Konntet Ihr etwas Interessantes finden, {name}?", completion = "<Harrison überfliegt die Rollen zügig.>\n\nJa... ja... Perfekt!\n\nIch werde etwas Zeit brauchen, um sie zu entschlüsseln, aber die Informationen sind darin enthalten.\n\nGute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28273] = { id = 28273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Freund eines Freundes", description = "Ich muss auspacken und die Gegend ein wenig auskundschaften. In der Zwischenzeit möchte ich, dass Ihr einen alten Freund von mir trefft.\n\nSullah und ich kennen uns seit Ewigkeiten. Man kann ihm vertrauen, und das ist schon selten heutzutage.\n\nWarum geht Ihr nicht zu ihm und begrüßt ihn?", sourceObjective = "Harrison möchte, dass Ihr mit Sullah in der Oase Vir'sar sprecht.", completion = "Willkommen, {class}!\n\nWir beide werden uns gut verstehen! Das kann ich jetzt schon sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28274] = { id = 28274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Zelte", description = "Seht Euch an! Das Abenteuer steht Euch förmlich ins Gesicht geschrieben!\n\nIhr müsst Euch aber auch ein wenig erholen. Ihr seht angespannt aus und das macht einen schnell müde.\n\nVertraut mir, mit Erholung kenne ich mich aus!\n\nA propos Erholung: Jonesy hat mir anscheinend die Zelte gebracht, um die ich ihn gebeten habe.\n\nKommt. Reitet mit mir!", sourceObjective = "Begleitet Sullah zu Sullahs Fahrendem Zirkus", completion = "Da wären wir, {name}!\n\nGroßartige Dinge werden hier stattfinden... magische Dinge!", sourceObjectiveStatus = "unverified-source-field" }
quests[28275] = { id = 28275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bom-ben-los!", description = "Wellsons Werft empfängt dauernd Vorräte von den Küstengewässern aus und das muss aufhören. Sie haben Kanonen an den Docks aufgestellt, um sich zu verteidigen, aber wenn Ihr zu ihnen durchbrechen könnt, können wir mit ihnen die Versorgungsschiffe zerstören.\n\nBegebt Euch dorthin und seht mal, was Ihr tun könnt. Erstattet mir über Eure Fortschritte Bericht.", sourceObjective = "Zerstört 10 scheußliche Versorgungsboote.", completion = "Ausgezeichnete Arbeit mit den Versorgungsbooten, {name}! Wir wussten, dass Ihr was taugt!", sourceObjectiveStatus = "unverified-source-field" }
quests[28276] = { id = 28276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salhets Geheimnis", description = "Hört gut zu, {name}. Bevor Ihr Euer Vertrauen in mich verliert, würde ich Euch gerne noch etwas zeigen.\n\nWie Ihr wisst, bin ich kein Kämpfer. Meine Koordination ist nicht gut.\n\nIch sehe mich eher als Taktiker an.\n\nTrefft mich am südlichen Ende des Grats und ich werde Euch zeigen, was ich meine.", sourceObjective = "Findet Salhet am südlichen Ende des Sonnenbehütergrats in Uldum.", completion = "Sind sie nicht wunderschön?", sourceObjectiveStatus = "unverified-source-field" }
quests[28277] = { id = 28277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salhet der Taktiker", description = "Schon als ich ein Junges war, wollte ich unbedingt ein General werden.\n\nIch wollte unbedingt der Armee beitreten. Aber wie Ihr gesehen habt, ist es um meine Kampfkünste schlecht bestellt.\n\nIch wurde schon früher zum Hyänentöten geschickt. Ich wurde schon so oft hierher geschickt, dass ich mich inzwischen mit den Löwen angefreundet und sie trainiert habe, das zu machen, was ich will.\n\nSie sind meine Soldaten, folgen meinen Befehlen und töten massenweise Hyänen. Seht selbst!", sourceObjective = "Sprecht mit Salhet und tötet 30 Murrblutaasfresser", completion = "Nicht schlecht, was? Vielleicht könnt Ihr beim Hochkommandanten ein gutes Wort für mich einlegen?\n\nVielleicht erteilt er uns Zuständigkeit über unsere eigene Einheit!", sourceObjectiveStatus = "unverified-source-field" }
quests[28278] = { id = 28278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin das Gesetz und dessen starker Arm", description = "Ich war auf der Suche nach <einem starken Soldaten/einer starken Soldatin> wie Euch. Ich brauche jemanden, der dafür sorgt, dass meine Truppen sich benehmen.\n\nAußerhalb der Festung bereiten sich die Orcs, Oger und Trolle auf einen Angriff auf das Rotkammgebirge vor. Meine Unteroffiziere halten sie zwar auf Trab, aber sie brauchen Hilfe.\n\nNehmt diesen Knüppel und diszipliniert ein paar meiner Soldaten.\n\nEs ist mir egal, ob sie in Reih und Glied stehen oder sich fehlverhalten - ich will nur, dass sie eine Tracht Prügel bekommen. Ich will, dass sie sich konzentrieren, auf die Schlacht vorbereitet und abgehärtet sind, und gefolgsam.\n\nGeht nun.", sourceObjective = "Benutzt den Disziplinarknüppel des Schwarzfels bei 20 Einheiten in den Feldern der Ehre. Wenn jemand merkt, wer Ihr seid, so erschlagt ihn, bevor er Eure Maskierung aufheben kann.", completion = "Ich habe das Gefühl, dass wir von Euch noch viel hören werden, Soldat. Ich freue mich darauf, an Eurer Seite im Rotkammgebirge zu kämpfen.\n\nWegtreten!", sourceObjectiveStatus = "unverified-source-field" }
quests[28279] = { id = 28279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtmissbrauch", description = "{name}? Trottmann hier.\n\nWie es scheint, habt Ihr Thorg'izogs Vertrauen gewonnen, denn er hat Euch für die Disziplinierung eingeteilt. Das ist ein Glück.\n\nWir müssen diese Feldwebel loswerden. Ihr findet sie außerhalb der Schwarzfelsfestung in den Feldern der Ehre auf Wölfen reitend. Benutzt den Knüppel so oft wie nötig, bis sie sterben. Ihr müsst schnell handeln, denn wenn sie merken, dass Ihr <keiner/keine> von ihnen seid, dann werden sie versuchen, Eure Maskierung aufzuheben. Seid schnell und zügellos, {name}.\n\nTrottmann aus.", sourceObjective = "Tötet 5 Feldwebel des Schwarzfels mit dem Disziplinarknüppel des Schwarzfels. Besiegt sie schnell, bevor sie Eure Maskierung aufheben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28280] = { id = 28280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reißt sie vom Himmel!", description = "Um Himmels Willen! Sie sind hier, {name}. Sie sind hier!\n\nIch hatte gehofft, eine ganze Armee mit meinen tragbaren Drachenfäusten ausrüsten zu können, aber ich habe nur einen einzigen, extrem teuren und viel zu wenig getesteten Prototypen. Hier, nehmt ihn!\n\nSchießt auf die Schwarzdrachen des Drachenmals, die um Donnermar kreisen, und lasst sie vom Himmel stürzen!", sourceObjective = "Benutzt den tragbaren Drachentöter, um 8 Schwarzdrachen des Drachenmals zu töten.", completion = "Ihr habt es geschafft, {name}! Wieder einmal hat die Genialität der Allianz den Tag gerettet.\n\nNatürlich habe ich jetzt nichts, mit dem Ihr die abgestiegenen Reiter auf dem Boden bekämpfen könntet. Aber Ihr seid ein {class}. Improvisiert!", sourceObjectiveStatus = "unverified-source-field" }
quests[28281] = { id = 28281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letztes Gefecht in Donnermar", description = "Ich überlasse es Euch und Euren Freunden von der Allianz. Ihr habt es dem Drachenmalklan bisher schon gut gezeigt!\n\nViele ihrer berittenen Kämpfer sind bereits ihre Reittiere los, aber sie kommen immer noch in unsere Richtung und meine Verteidiger kommen ohne Hilfe nicht zurecht.\n\nTötet die Himmelskrallen des Drachenmalklans ohne Reittiere und Donnermar wird für immer in Eurer Schuld stehen!", sourceObjective = "Tötet 8 Himmelskrallen des Drachenmalklans ohne Reittiere.", progress = "Wir sollten eine Kampfpause einlegen und die Feuer löschen, oder Donnermar wird aussehen wie der Rest der Welt, die in Trümmern liegt...", completion = "Ihr müsst Euch auf dem Schlachtfeld gut zurechtfinden können, {class}. Es scheint, als sei ein neuer Einfall geplant.\n\nWir brauchen nur noch einen entscheidenden Schlag...", sourceObjectiveStatus = "unverified-source-field" }
quests[28282] = { id = 28282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narkrall, der Drachenzähmer", description = "Narkrall vom Drachenmalklan wird auch der \"Drachenzähmer\" genannt. Ich weiß nicht, wie er die Macht erlangt hat, diese Bestien zu befehligen, aber der schwarze Terror, den er reitet, ist der grausigste Drache, der in den ganzen Hochländern zu finden ist.\n\n{name}, Narkrall ist ein Feind, der das Leben meines Vaters genommen und Donnermars Schicksal in meine Hände gelegt hat.\n\nIch kann mich ihm nicht alleine stellen, aber ich habe gesehen, zu was Ihr in der Lage seid, {class}. Vielleicht können wir diesem Schrecken gemeinsam ein Ende bereiten.\n\nLasst mich wissen, wenn Ihr bereit seid, und wir werden Narkrall gemeinsam bekämpfen!", sourceObjective = "Tötet Narkrall Harkenklaue. Sprecht mit Colin Donnermar, wenn Ihr bereit seid.", completion = "Wir haben es geschafft, {name}! Narkrall Harkenklaue liegt tot zu meinen Füßen und Donnermar hat einen Sturm von Drachen abgewehrt!\n\nOhne die Hilfe der Allianz wäre das nicht möglich gewesen. Die Schuld, in der ich stehe werde ich wohl nie begleichen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28283] = { id = 28283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist das für eine Rassel?", description = "Habt Ihr die leuchtende Rassel gesehen, die vor Ishas Hütte auf dem Boden liegt?", sourceObjective = "Untersucht die Rassel der Knochen in Düsterwolkengipfel in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[28284] = { id = 28284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist das für eine Rassel?", description = "Habt Ihr die leuchtende Rassel gesehen, die vor Ishas Hütte auf dem Boden liegt?", sourceObjective = "Untersucht die Rassel der Knochen in Düsterwolkengipfel in Tausend Nadeln.", completion = "Interessant...", sourceObjectiveStatus = "unverified-source-field" }
quests[28285] = { id = 28285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Hohepriesterin Laurena", description = "Ich habe eine Schriftrolle aus der Kathedrale des Lichts erhalten, {name}. Hohepriesterin Laurena schickt Kunde, dass sie Euch sprechen möchte. Ihr solltet sie so bald wie möglich treffen.", sourceObjective = "Sprecht mit Hohepriesterin Laurena bei der Kathedrale des Lichts im Kathedralenviertel von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28286] = { id = 28286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug Schaden für einen Tag", description = "Wir haben keine weitere strategische Verwendung für Thorg'izog oder die Bodentruppen des Schwarzfels. Wir müssen nun die nächste Phase des Plans einläuten.\n\nWenn Ihr bei der Festung fertig seid, kehrt zurück zu uns in Meißelgriff.", sourceObjective = "Kehrt zu Oberst Trottmann in Meißelgriff zurück.", completion = "Alles in Ordnung?\n\nGut. Ihr habt gute Arbeit geleistet, {name}. Packt Eure Sachen zusammen. Wir ziehen ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[28287] = { id = 28287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Scharfseherin Umbrua", description = "Eine Nachricht von Scharfseherin Umbrua hat mich soeben erreicht, {name}. Es gibt ein wichtiges Anliegen, das sie mit Euch besprechen möchte, und sie bittet darum, dass Ihr sie im Gasthaus Zum Goldenen Fass im Zwergendistrikt in Sturmwind aufsucht, sobald Ihr könnt.", sourceObjective = "Sprecht mit Scharfseherin Umbrua im Gasthaus Zum Goldenen Fass im Zwergendistrikt von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28288] = { id = 28288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Öffnet ihre Augen", description = "Bevor Ihr geht...\n\nIch habe meine Zeit allein mit Impsy hier genutzt, um ein paar interessante Fakten über Wichtel herauszufinden. Er hat mir nämlich von einer Sache erzählt, die alle Wichtel am meisten fürchten. Etwas, das sie regelrecht in Angst und Schrecken versetzt.\n\nIch fand das sowohl nützlich als auch interessant, also habe ich ein paar geringere Beschwörungen durchgeführt. Dieses Prisma wird ein Bild projizieren von... nun, von dem, was Impsy beschrieben hat.\n\nIm Schattenlauergrat wimmelt es immer noch nur so von Wichteln. Warum geht Ihr nicht dorthin und schaut für mich, wie sie darauf reagieren?", sourceObjective = "Benutzt Delaris' Prisma, um 20 Jadefeuerwichtel zu erschrecken.", completion = "Ich verstehe... Ihre Augen sind geöffnet.\n\n<Delaris lächelt amüsiert.>\n\nVielleicht behalte ich Impsy doch noch eine Weile bei mir. Er kann mir noch viel beibringen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28289] = { id = 28289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondlichtung ruft", description = "Ich habe Nachrichten aus Mondlichtung erhalten. Unsere Brüder bitten um Eure Hilfe, {name}. Ihr solltet Euch auf die Reise machen und Loganaar in Nachthafen aufsuchen.", sourceObjective = "Reist nach Mondlichtung und sprecht mit Loganaar in Nachthafen.", completion = "Gut, Euch wieder zu sehen, {name}. Ich wünschte, ich könnte Euch gute Nachrichten überbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28290] = { id = 28290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Grezz Zornfaust", description = "Grezz Zornfaust hat Euch eine wichtige Nachricht geschickt, {name}. Er möchte, dass Ihr ihn umgehend im Tal der Ehre in Orgrimmar aufsucht. Er scheint ein wichtige Aufgabe für Euch zu haben.", sourceObjective = "Sprecht mit Grezz Zornfaust im Tal der Ehre in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28291] = { id = 28291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Lager zurückkehren", description = "Was meint Ihr, {name}? Vielleicht gibt mir der Hochkommandant ein paar Leute, die ich befehligen kann.\n\nVielleicht können wir zusammen ein Regiment aufstellen. Was meint Ihr?", sourceObjective = "Kehrt zu Hochkommandant Kamses am Außenposten der Legion von Ramkahen zurück.", completion = "Salhet? Ein Taktiker, sagt Ihr?\n\nHah! Na ja, wenn Ihr Euch für ihn verbürgt, können wir bestimmt etwas arrangieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28292] = { id = 28292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist keine Pyramide!", description = "Die Pyramide bei der Terrasse des Schöpfers in Uldum ist nicht wirklich eine Pyramide im klassischen Sinne. Es ist eine große Maschine, die für unzählig viele Funktionen umprogrammiert werden kann.\n\nTodesschwinge wollte, dass der Schattenhammer sie in eine riesige Waffe umfunktioniert!\n\n{name}, Ihr müsst das Portal benutzen, um Harrison Jones in Sturmwind diese Information zukommen zu lassen. Er wird wissen, was zu tun ist.", sourceObjective = "Sprecht mit Harrison Jones in Burg Sturmwind in Sturmwind.", completion = "Uldum? Was ist damit?", sourceObjectiveStatus = "unverified-source-field" }
quests[28293] = { id = 28293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist keine Pyramide!", description = "Die Pyramide bei der Terrasse des Schöpfers in Uldum ist nicht wirklich eine Pyramide im klassischen Sinne. Es ist eine große Maschine, die für unzählig viele Funktionen umprogrammiert werden kann.\n\nTodesschwinge wollte, dass der Schattenhammer sie in eine riesige Waffe umfunktioniert!\n\n{name}, Ihr müsst das Portal benutzen, um Bellok Leuchtklinge in Orgrimmar diese Information zukommen zu lassen. Er wird wissen, was zu tun ist.", sourceObjective = "Sprecht mit Bellok Leuchtklinge in der Feste Grommash in Orgrimmar.", completion = "Uldum? Was ist mit Uldum? Sprecht, schnell!", sourceObjectiveStatus = "unverified-source-field" }
quests[28294] = { id = 28294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gipfeltreffen in Kirthafen", description = "Dank der Abreibung, die wir dem Drachenmal verpasst haben, werden ihre Angriffe auf Donnermar wohl aufhören. Vielleicht haben die Wildhämmer einen Platz in der Allianz - Donnermar steht in jedem Fall in Eurer Schuld.\n\nUnser großer Schamane, Lachlan MacGraff, hat versucht, ein Gipfeltreffen der Anführer der überlebenden Wildhammerfamilien zu veranstalten. Es ist keine leichte Aufgabe, alle zusammenwirken zu lassen, aber ich werde es zumindest versuchen.\n\nFliegt nach Kirthafen und sprecht mit Lachlan MacGraff. Ich werde Euch dort treffen!", sourceObjective = "Sprecht mit Lachlan MacGraff in Kirthafen im Schattenhochland.", completion = "Hallo, {class}! Keegan Feuerbart hier hat mir schon viel von Euren Heldentaten im Süden berichtet. Ich danke Euch für Eure Bemühungen, uns Wildhämmern zu helfen.\n\nWie ich sehe, ist auch Colin Donnermar eingetroffen. Unser Gipfeltreffen kann beginnen! Bitte, bleibt und seht, wie die Dinge sich entwickeln...", sourceObjectiveStatus = "unverified-source-field" }
quests[28295] = { id = 28295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Karawane treffen", description = "Die Pyramide in der Terrasse des Schöpfers in Uldum kann als eine Art Superwaffe benutzt werden, die alles Leben in Azeroth auslöschen wird.\n\n<Harrison denkt einen Augenblick lang nach.>\n\nIhr müsst Eure Untersuchungen zu Ende führen. Reist ans südliche Ende Kalimdors, zur Tanariswüste. Dort findet Ihr eine Karawane, die nach Uldum aufbrechen wird.\n\nVielleicht könnt Ihr Euch anschließen.", sourceObjective = "Sprecht mit Adarrah in Disteltal in Tanaris.", completion = "Harrison schickt Euch also?\n\nNa so ein Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[28296] = { id = 28296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Karawane treffen", description = "Die Pyramide in der Terrasse des Schöpfers in Uldum kann als eine Art Superwaffe benutzt werden, die alles Leben in Azeroth auslöschen wird.\n\n<Belloc denkt einen Augenblick lang nach.>\n\nIhr müsst also mit Euren Untersuchungen fortfahren. Reist nach Süden zur Tanariswüste. Dort findet Ihr eine Karawane, die nach Uldum aufbrechen wird.\n\nVielleicht könnt Ihr Euch anschließen.", sourceObjective = "Sprecht mit Adarrah in Disteltal in Tanaris.", completion = "Bellok schickt Euch also?\n\nNa so ein Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[28297] = { id = 28297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Ormak Grimmschlag", description = "Ich habe eine Schriftrolle von Ormak Grimmschlag aus Orgrimmar erhalten. Er möchte, dass Ihr Euch auf den Weg zum Tal der Ehre begebt und ihn so schnell wie möglich aufsucht. Es klang sehr dringlich, {name}.", sourceObjective = "Sprecht mit Ormak Grimmschlag im Tal der Ehre in Orgrimmar.", completion = "Die Horde benötigt Eure Fähigkeiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28298] = { id = 28298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Gordul", description = "Gordul, der Anführer der Schurken der Zerschmetterten Hand, möchte Euch treffen. Begebt Euch so schnell wie möglich nach Orgrimmar, {name}, und sucht ihn der Kluft der Schatten auf. Er scheint eine wichtige Aufgabe für Euch zu haben.", sourceObjective = "Sprecht mit Gordul in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28299] = { id = 28299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Zevrost", description = "Ich habe soeben eine Nachricht von Zevrost erhalten, dem mächtigsten Leher für Hexenmeister. Er wünscht, dass Ihr nach Orgrimmar reist und ihn in der Kluft der Schatten trefft. Es klang, als habe er eine wichtige Aufgabe für Euch.", sourceObjective = "Sprecht mit Zevrost in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28300] = { id = 28300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Ureda", description = "Ich habe eine Schriftrolle aus Orgrimmar für Euch, {name}. Sie ist von Ureda, eine der Magierlehrerinnen. Sie möchte, dass Ihr Euch in der Kluft der Schatten mit ihr trefft, wenn Ihr das nächste Mal in der Stadt seid.", sourceObjective = "Sprecht mit Ureda in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28301] = { id = 28301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Kardris Traumsucher", description = "Ich habe eine wichtige Nachricht für Euch erhalten, {name}. Sie ist von Kardris Traumsucher, einer Schamanenlehrerin aus Orgrimmar. Sie möchte, dass Ihr Euch so schnell wie möglich ins Tal der Weisheit in Orgrimmar begebt und dort mit ihr sprecht.", sourceObjective = "Sprecht mit Kardris Traumsucher im Tal der Weisheit in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28302] = { id = 28302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Sonnenläufer Atohmo", description = "Ihr solltet so schnell wie möglich nach Orgrimmar aufbrechen, {name}. Sonnenläufer Atohmo hat Kunde geschickt, dass er Euch in einer wichtigen Angelegenheit der Horde sprechen möchte. Sucht ihn im Tal der Weisheit auf.", sourceObjective = "Sprecht mit Sonnenläufer Atohmo im Tal der Weisheit in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28303] = { id = 28303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Meister Pyreanor", description = "Meister Pyreanor hat Euch eine wichtige Nachricht zukommen lassen, {name}. Er bittet Euch, ihn in der Feste Grommash im Tal der Stärke aufzusuchen, wenn Ihr das nächste Mal in der Stadt seid. Es klang, als habe er eine wichtige Aufgabe für Euch.", sourceObjective = "Sprecht mit Meister Pyreanor in der Feste Grommash in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28304] = { id = 28304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft die dunkle Klerikerin Cecille", description = "Die dunkle Klerikerin Cecille, eine Angehörige der Delegation der Bansheekönigin in Orgrimmar, hat darum gebeten, dass Ihr sie bei Eurem nächsten Besuch in der Stadt trefft. Sie ist in der Feste Grommash im Tal der Stärke in Orgrimmar. Es muss sich um eine wichtige Angelegenheit handeln, wenn sie direkt nach Euch schickt.", sourceObjective = "Sprecht mit der dunklen Klerikerin Cecille in der Feste Grommash im Tal der Stärke in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28305] = { id = 28305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal Blutgiftpostens", description = "Während wir uns um Jaedenar gekümmert haben, ist eine Freundin von mir zum Blutgiftposten aufgebrochen. Wir hatten früher unregelmäßige Besuche von den Tauren von dort, aber in letzter Zeit haben wir von ihnen nichts mehr gehört.\n\nKelnir Blattlied ist noch nicht zurückgekehrt. Könntet Ihr nach Norden reisen, um nach ihr zu suchen und die Lage in Blutgiftposten erkunden?\n\nWenn Ihr Kelnir finden solltet, müsst Ihr achtsam sein... Dryaden wie sie werden von vielen anderen Völkern als seltsam empfunden.", sourceObjective = "Sprecht mit Kelnir Blattlied beim Blutgiftposten.", completion = "Oh, hi! Hat Farlus Euch geschickt? Wie schön, dass er sich daran erinnert hat!\n\nBlutgipfelposten ist voll und ganz von diesen furchtbaren Schleimdingern überfüllt und dieser arme Tauren hier ist der Einzige, der noch übrig ist! Wir müssen ihm helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28306] = { id = 28306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisperwindhain", description = "Ihr wart hier so eine große Hilfe!\n\nIch werde hier bleiben und mich um den armen Herrn Tauren kümmen, bis er sich nicht mehr ganz so oft übergibt. Warum geht Ihr solange nicht nach Wisperwindhain? Da ist es wirklich schön, und alle Druiden sind richtig nett!\n\nBitte richtet Frau Purhain aus, dass es mir gut geht. Sie soll sich keine Sorgen machen, wenn ich mal länger weg bin. Vielleicht wird sie Euch bitten, ihr mit den Blumen zu helfen. Das macht soo viel Spaß!", sourceObjective = "Sprecht mit Hüterin Purhain in Wisperwindhain.", completion = "Kelnir? Hahaha...\n\nManchmal frage ich mich, ob ihr Geschwätz der Grund für das Verschwinden der anderen Dryaden war. Aber ich bin froh, dass es ihr gut geht.\n\nWillkommen in Wisperwindhain, {class}. Wenn Ihr Frieden im Herz habt, so kann Euch Wisperwindhain eine gute Heimat sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[28307] = { id = 28307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Tyelis", description = "Tyelis, ein Mitglied der Delegation Silbermonds in Orgrimmar, hat Euch zu einem Treffen aufgefordert, wenn Ihr das nächste Mal in der Stadt seid. Ihr könnt ihn in der Feste Feste Grommash in Orgrimmars Tal der Stärke finden. Es muss eine wichtige Angelegenheit sein, wenn er Euch so direkt auffordert, {name}.", sourceObjective = "Sprecht mit Tyelis in der Feste Grommash im Tal der Stärke in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28308] = { id = 28308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Seherin Liwatha", description = "Seherin Liwatha schickt ihre Grüße aus dem Tal der Weisheit in Orgrimmar, {name}. Sie hat mich gebeten, eine Einladung für Euch auszusprechen. Sie möchte, dass Ihr sie besucht, wenn Ihr das nächste Mal in der Stadt seid. Es klang, als habe sie ein wichtiges Anliegen mit Euch zu besprechen.", sourceObjective = "Sprecht mit Seherin Liwatha im Tal der Weisheit in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28309] = { id = 28309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Schattenläufer Zuru", description = "Schattenläufer Zuru, ein angesehener Priesterlehrer, hat um ein Treffen mit Euch in Orgrimmar gebeten. Ihr könnt ihn im Tal der Geister bei den anderen Lehrern vom Stamm der Dunkelspeere finden. Es muss sehr wichtig sein, wenn sie so direkt nach Euch schickt, {name}.", sourceObjective = "Sprecht mit der dunklen Klerikerin Cecille in der Feste Grommash im Tal der Stärke in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28310] = { id = 28310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgans Wacht", description = "Unsere Arbeit hier in Meißelgriff ist abgeschlossen; in erster Linie, weil Ihr uns geholfen habt. Nun werden wir uns in Richtung Osten begeben, zu Morgans Wacht.\n\nWir wurden informiert, dass Morgans Wacht leersteht, weil die meisten Einwohner zum Schwarzfels gezogen sind, um ihren Kampf gegen die Orcs des Schwarzfelsklans zu führen. Morgans Wacht sollte ein guter Operationspunkt für die letzten Phasen unseres Vorhabens sein.\n\nNatürlich wird Keeshan Euch begleiten. Und ich auch.", sourceObjective = "Meldet Euch bei Oralius in Morgans Wacht in der Brennenden Steppe.", completion = "Ihr seid angekommen! Und gerade rechtzeitig zur Freundschaftszeremonie!\n\n<Oralius blickt wehmütig über seine Schulter zu dem Ogerkopf und verfällt in Panik.>\n\nHauptmann Winky! Wo ist Hauptmann Winky hin?\n\nOh, bitte, sagt nicht, dass er kalte Füße bekommen hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[28311] = { id = 28311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschwärzte Asche", description = "Ihr müsst für mich noch etwas besorgen, bevor wir uns dem Rest der Schwarzfelsarmee annehmen können. Wenn wir das hier tun wollen, sollten wir es richtig tun, und das bedeutet, dass wir uns vorbereiten müssen.\n\nIch brauche Asche, {name}. Nicht irgendwelche Asche... Asche von den großen Obsidianelementaren, die sich in den Ebenen im Nordwesten aufhalten. Das Zeug ist tiefschwarz, und genau das brauchen wir für unsere nächste Verkleidung.\n\nKeine Sorge, Ihr habt schon eine Verkleidung. Diese ist für jemanden... naja, für ETWAS... anderes.", sourceObjective = "Sammelt 9 Haufen Obsidianasche.", progress = "Die Asche der Obsidianelementare ist besonders dunkel - und genau, was wir für unser Vorhaben benötigen.", completion = "Ja, die sind gut genug. Ich werde sie für Euch schön einpacken.", sourceObjectiveStatus = "unverified-source-field" }
quests[28312] = { id = 28312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafende Dämonen des Landes", description = "Die Lavaseen westlich von hier sind die Heimat der Flammkin, eine besondere Art Feuerdämonen, die die Steppe schon lange beheimaten. In der Schwarzfelsarmee sieht es so aus, als könnten wir - wenn wir vorsichtig genug sind - ein paar der Flammkin hinter die feindlichen Linien schmuggeln, um für Verwüstung zu sorgen.\n\nBringt mir die Leichen von mehreren Flammkin. Als Dämonen kann man sie leicht wiederbeleben, und dann für seine eigenen Zwecke einsetzen.", sourceObjective = "Sammelt 18 gefallene Flammkin.", progress = "Die Flammkin sind schwach, aber sie reisen in Rudeln. Seid vorsichtig.", completion = "Für das ungeübte Auge sehen sie aus wie Wichtel.\n\nWir müssen sie nur diesem eben ungeübten Auge unterjubeln. Ich werde sie jetzt für den Einsatz vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28313] = { id = 28313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein köstlicher Haufen Worg", description = "Wir brauchen frisches Fleisch und deshalb werdet Ihr Euch auf die Worgjagd machen. Die Worgs auf dieser Seite der Steppe sollten die sein, auf die Ihr Euch bei der Jagd konzentriert.\n\n<Trottmann holt eine große Klinge hervor und händigt sie Euch aus.>\n\nMacht Jagd auf die riesigen Glutworgs. Benutzt diese Säge, um die besten Fleischstücke aus den frisch getöteten Worgs zu schneiden. Worgs sind überall in der Steppe zu finden; nordöstlich von hier ist gleich das erste Rudel.", sourceObjective = "Benutzt die Worgsäge, um aus den frisch getöteten riesigen Glutworgs 40 Worgschnitzel zu schneiden.", progress = "Glück bei der Jagd gehabt?", completion = "Das Fleisch sieht gut aus... aber ich glaube, wir müssen es noch ein bisschen \"würzen\". Ich werde sicherstellen, dass sich jemand darum kümmert.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28314] = { id = 28314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutrunde", description = "Meine Beine werden schon wieder ein wenig rastlos. Habt Ihr Lust, eine kleine Runde zu drehen, {name}?\n\nWir werden uns auf eine Reise um den Schreckensfels begeben. Ich möchte die Schwarzfelsarmee erst ein wenig unter die Lupe nehmen, bevor wir zuschlagen. Da dachte ich mir, wir könnten auch ein paar von ihnen töten, wenn wir schon auf dem Weg sind.", sourceObjective = "Tötet 25 schwarze Großdrachenbrut oder Schwarzwyrmkin.", completion = "<Keeshan trieft vor Blut und Schweiß.>\n\nGenau das hatte ich im Sinn!", sourceObjectiveStatus = "unverified-source-field" }
quests[28315] = { id = 28315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenvorhut", description = "Die Schwarzfelsorcs kommen nicht allein. Die Oger der Feuermägen und Trolle der Gluthauer, die an ihrer Seite kämpfen, habt Ihr bereits gesehen. Leider haben sie aber auch die schwarzen Großdrachen auf ihrer Seite.\n\nDie Orcs und Drachen haben bereits ihre Champions zu Sammelpunkten geschickt, um Wache zu stehen. Ihr könnt sie an den Drachenschädeln auf Piken erkennen, die herumstehen. Wir beide werden diese Sammelpunkte finden und die Vorposten ausschalten, bevor die Schlacht beginnt.\n\nSeid Ihr bereit?", sourceObjective = "Tötet Minyoth, Welpenbändigerin Akumi, Terromath den Versengten und Tugnar Blutschlund.", progress = "Kommt schon, {name}, es sind noch ein paar von ihnen übrig. Unsere Arbeit ist noch nicht erledigt.", completion = "Ihr werdet immer besser, {name}! Jetzt fallen sie, so wie wir es wollten.\n\nUnd wir werden siegen. Das Rotkammgebirge wird NIEMALS diesen Feiglingen gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[28316] = { id = 28316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Handel mit einem Drachen", description = "Auf unserer Reise um den Schreckensfels gibt es noch einen Zwischenstopp.\n\nErinnert Ihr Euch noch an die Brutlinge, die Ihr aus den Schlupfhügeln befreit habt? Trottmann hat sich um sie gekümmert. Jetzt werden wir sie zu jemandem bringen, der besser für sie sorgen kann als wir. Er hält sich am Schlitterfels auf, nordöstlich des Schreckensfels.\n\nSein Name ist Acride. Er ist vielleicht der Schlüssel zum Sieg in der bevorstehenden Schlacht.", sourceObjective = "Bringt die geretteten Welplinge zu Acride im Schlitterfels in der Brennenden Steppe.", progress = "Da seid Ihr ja, {name}.", completion = "Ja, die Welplinge. Ich werde mich um sie kümmern.\n\nUnd was die Vereinbarung angeht, die ich zuvor mit Eurem Oberst Trottmann getroffen habe, sagt ihm, dass ich meinen Teil des Handels erfüllen werde. Ich werde Euch Euren Drachen für die Schlacht gegen die Orcs schicken.\n\nWir hegen zwar keine Sympathien für das Rotkammgebirge, aber wir teilen Eure Verachtung dem Schwarzfelsklan gegenüber.", sourceObjectiveStatus = "unverified-source-field" }
quests[28317] = { id = 28317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lieferung für Thorg'izog", description = "General Thorg'izog ist bei den Ogern im Ofen der Feuermägen, eine Höhle in der Westwand des Schreckensfels. Bringt diese Lieferung zu ihm und den Ogern.\n\nDarin befinden sich die Worgschnitzel, die Ihr besorgt habt. Sie wurden in dem Teufelskarussellstöffsche mariniert, das wir vom Altar der Stürme erhalten haben.\n\nIhr solltet nichts davon essen, wenn es Euch irgendwie möglich ist.\n\nBringt die Schnitzel zu General Thorg'izog. Er wird sich darum kümmern, dass seine Streitmächte Essen im Magen haben und mit ein bisschen Glück isst er auch etwas davon.", sourceObjective = "Tragt Eure Schwarzfelsverkleidung und bringt die in Karussellstöffsche marinierten Schnitzel zu General Thorg'izog im Ofen der Feuermägen in der Brennenden Steppe. Sprecht mit Oberst Trottmann, wenn Ihr eine neue Schwarzfelsverkleidung braucht.", progress = "Was habt Ihr da, Soldat?", completion = "Nun seht Euch das an! Jetzt weiß ich, wer mein Lieblingssoldat ist!\n\nIch werde die Schnitzel unter den Ogern verteilen.\n\nIch werde Euch am Rotkamm wieder sehen, Soldat. Für die Ehre des Schwarzfels!", sourceObjectiveStatus = "unverified-source-field" }
quests[28318] = { id = 28318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lieferung für Neeralak", description = "Die Hexenmeister des Schwarzfelsklans üben ihre Magie oft in der Schädelhöhle östlich des Schreckensfels. Ihr Anführer Xi'lun ist gerade andernorts beschäftigt, sodass die Höhle derzeit von einem anderen der großen Drei beaufsichtigt wird: Drachenlord Neeralak. Neeralaks Fachgebiet sind Drachen, nicht die Totenbeschwörung.\n\nIch habe die Flammkin, die Ihr gefangen habt, mit dem Schlummersand bestreut. Überzeugt Neeralak davon, dass es sich dabei um Hexenmeisterwichtel handelt, nicht um Flammkin. Wenn sie aufwachen, werden sie alles andere als glücklich sein.", sourceObjective = "Legt Eure Schwarzfelsverkleidung an, schleicht Euch in die Schädelhöhle und überzeugt Drachenlord Neeralak, Eure Kiste voller schlafender Flammkin anzunehmen. Sprecht mit Oberst Trottmann, wenn Ihr eine neue Schwarzfelsverkleidung benötigt.", progress = "Was?", completion = "Was soll das sein? Aha, das sind also Wichtel?\n\nIch bin mir sicher, dass Wichtel nicht einfach so in Kisten schlafen!\n\nAber ich nehme Euch beim Wort. Ich verstehe nichts von diesem Hexenmeisterquatsch. Stellt sie in der Ecke ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[28319] = { id = 28319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lieferung für Xi'lun", description = "Man hat uns berichtet, dass der oberste Hexenmeister Xi'lun, das letzte Mitglied der großen Drei, sich in einer Höhle auf dem Gipfel des Schreckensfels aufhält und seinen großen Augenblick vorbereitet.\n\nEr erwartet eine Lieferung: eine Kugel der Herrschaft, mit der er ein mächtiges Beschwörungsritual durchführen kann. Ich möchte, dass Ihr ihm das hier gebt.\n\n<Trottmann reicht Euch eine Glaskugel.>\n\nDies ist die klare Glaskugel, die Ihr aus dem Altar der Stürme befreit habt. Sie ist machtlos. Gebt sie Xi'lun und betet, dass er den Unterschied nicht bemerkt.", sourceObjective = "Legt Eure Schwarzfelsverkleidung an und bringt die klare Glaskugel zum obersten Hexenmeister Xi'lun auf dem Schreckensfels in der Brennenden Steppe.", progress = "Ich habe keine Zeit für Spielchen, Narr. Geht mir aus den Augen.", completion = "Pff! Ihr seid spät dran! Wisst Ihr, wie lange ich schon warte, dass Ner'gosh mir endlich diese Kugel bringt?\n\n<Xi'lun schaut auf die Kugel, dann wieder zu Euch.>\n\nEtwas ist merkwürdig an dieser Kugel... Sie ist zu...\n\n<Xi'lun verstummt.>\n\nAch, schon gut. Meine Nerven liegen wohl einfach blank. Vielen Dank für die Lieferung. Für Blut und Donner!", sourceObjectiveStatus = "unverified-source-field" }
quests[28320] = { id = 28320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Schreckensfels", description = "Das ist es also, {name}! Hier soll es geschehen. Hier fügen sich alle Teile zusammen.\n\nSchnallt Euch an und kommt mit mir. Wir werden mit Acride sprechen und den Gefallen einfordern, den er uns schuldet. Dann werden wir die Invasion im Rotkammgebirge aufhalten, bevor sie überhaupt begonnen hat.", sourceObjective = "Tötet 200 Eindringlinge des Schwarzfels. Wenn Ihr Euer Fahrzeug verlieren solltet, benutzt das Horn der Rufer, um es herbeizurufen.", completion = "Habt Ihr gesehen, wie sie gerannt sind? Sie hatten keine Ahnung, wie ihnen geschieht! Wunderbar!\n\nUnsere Aufgabe ist fast erledigt, {name}. Es ist Zeit, ihnen den Todesstoß zu versetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28321] = { id = 28321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhm im Chaos", description = "Ihr und Keeshan geht zurück zu diesem Berg. Drei Orcs haben den Angriff überlebt, und wir geben keine Ruhe, bis sie den Tod gefunden haben.\n\nGenau, ich spreche von den großen Drei.\n\nGeneral Thorg'izog ist in den Ofen der Feuermägen gekrochen und Drachenlord Neeralak hat sich in der Höhle auf dem Berggipfel verschanzt. Xi'lun hält sich im hinteren Teil der Schädelhöhle auf und schmiedet Pläne mit seinen Hexenmeisterfreunden.\n\nMacht Euch einen Namen, {name}. Jagt diese Jammerlappen des Schwarzfels und zeigt ihnen die Macht des Rotkammgebirges!", sourceObjective = "Tötet General Thorg'izog, Drachenlord Neeralak und oberster Hexenmeister Xi'lun.", completion = "<Oberst Trottmann strahlt vor Freude.>\n\nWillkommen daheim, Jungs.", sourceObjectiveStatus = "unverified-source-field" }
quests[28322] = { id = 28322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsbeute", description = "Wir haben heute einen Riesen überwältigt, {name}. Die Schwarzfelsorcs schwirren zwar immer noch im Berg herum, aber ich bezweifle, dass ihre Pläne sie in nächster Zeit auch nur in die Nähe des Rotkammgebirges führen. Das habt Ihr und Keeshan ihnen sicher ausgetrieben.\n\nIch muss sagen, dass wir hier in der Brennenden Steppe nicht mit Einfallsreichtum gegeizt haben. Diese Hexenmeisterausrüstung, die wir gesammelt haben, war äußerst praktisch, und auch die Obsidianasche, mit der wir unseren Drachen versteckt haben, war ein cleverer Schachzug.\n\nWir haben jedoch noch ein paar Gegenstände übrig. Bitte, sucht Euch etwas aus, bevor Ihr die Steppe wieder verlasst und weiterzieht.", sourceObjective = "Untersucht die Kiste mit übriggebliebenen Vorräten in Morgans Wacht in der Brennenden Steppe.", completion = "Ihr schaut hinein und findet...", sourceObjectiveStatus = "unverified-source-field" }
quests[28323] = { id = 28323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit Bruder Silberheil", description = "Bruder Silberheil wünscht Euch zu sprechen. Wenn Ihr das nächste Mal in Orgrimmar seid, sucht ihn in den Goblinslums auf. Es klang, als hätte er etwas Wichtiges mit Euch zu bereden.", sourceObjective = "Sprecht mit Bruder Silberheil in den Goblinslums von Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28324] = { id = 28324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Studien der Tödlichkeit", description = "Wir haben einen ziemlich mächtigen Erregerstamm der Seuche gegen die Menschen in Süderstade eingesetzt. Und wie Ihr seht hat es wunderbar funktioniert. Das Problem beim Einsatz der Seuche ist jedoch, dass sie nachdem sie ihren Zweck erfüllt hat nicht so einfach verschwindet.\n\nIch möchte, dass Ihr diese Testausrüstung nehmt und eine Tödlichkeitsanalyse an dem Seuchenschlamm vornehmt, den wir in der Gegend ausgesetzt haben. Benutzt den Tödlichkeitsanalysator am Seuchenschlamm, der in den Schleimpfützen umherschleimt. Kehrt zu mir zurück, wenn Ihr ein paar handfeste Daten gesammelt habt.", sourceObjective = "Sammelt 250 Seuchenproben.", completion = "Oh je. 250? Dieses Ding zeigt maximal 250 an. Ihr habt Glück, dass Ihr noch steht. Ihr solltet eigentlich schon längst zu einer Schleimpfütze zerflossen sein. Diese Nachrichten werden Sylvanas gar nicht gefallen. Vielleicht können wir innerhalb von ein paar Jahrzehnten die Tödlichkeitswerte in dieser Gegend verringern, aber dann geraten wir immer noch etwa hundert Jahre ins Hintertreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28325] = { id = 28325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Denkt grün!", description = "Recycling! Das ist in letzter Zeit in aller Munde. Die Bansheekönigin hat befohlen, dass wir Ressourcen schützen müssen, wenn wir als Volk erblühen wollen. Und jeder muss schließlich seinen Teil beitragen, nicht wahr? Also werdet Ihr unseren Teil für uns erledigen.\n\nEs liegen bestimmt Tausende von Seuchenkanisterteilen in ganz Süderstade verstreut. Wir können diese Kanister gut für weitere aufregende Seuchenangriffe nutzen. Geht einfach in die Ruinen hier und nehmt alles mit, was Ihr finden könnt.", sourceObjective = "Sammelt 8 gebrauchte Seuchenkanister.", progress = "Bringt mir diese Kanister!", completion = "Ausgezeichnete Arbeit, {name}. Ihr seid unglaublich widerstandsfähig gegenüber dieser Seuche. Wir müssen bei Gelegenheit einmal ein paar Tests an Euch durchführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28326] = { id = 28326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstellung der Bauern", description = "{name}. Ihr und Keeshan scheint Eure Aufgaben erledigt zu haben. Ich bin ebenfalls mit meiner fertig.\n\nKehrt zu Morgans Wacht zurück. Ich habe ein paar Pakete für die großen Drei vorbereitet: Thorg'izog, Neeralak und Xi'lun. General Thorg'izog habt Ihr ja schon getroffen. Jetzt habt Ihr die Gelegenheit, auch den anderen beiden zu begegnen.\n\nBevor wir sie töten meine ich natürlich.", sourceObjective = "Kehrt zu Oberst Trottmann in Morgans Wacht in der Brennenden Steppe zurück.", completion = "Gut, Ihr seid zurück.\n\nIch hoffe, Ihr habt die Verkleidung noch. Ihr werdet Euch wieder mitten unter die Feinde begeben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28327] = { id = 28327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geladen und entsichert", description = "{name}, bitte melden. Könnt Ihr mich hören?\n\nDie Schlacht beginnt gleich. Ich hoffe, Ihr habt alle Pakete ausgeliefert.\n\nIch brauche Euch hier in Morgans Wacht, SOFORT.", sourceObjective = "Meldet Euch bei Oberst Trottmann in Morgans Wacht in der Brennenden Steppe.", completion = "{name} ist da! Wir können loslegen.\n\nDas ist der Moment, auf den wir gewartet haben, {name}. Ich hoffe, Ihr seid in Bestform.", sourceObjectiveStatus = "unverified-source-field" }
quests[28328] = { id = 28328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtränke", description = "Der Einfluss des Schattenhammers reicht weit. Sie sind unablässig auf der Suche nach Verbündeten in ihrer Schlacht gegen uns und rekrutieren jetzt sogar die Dunkeleisenzwerge der Schwarzfelstiefen für ihre Sache.\n\nMoira hat die Dunkeleisenzwerge nur dürftig im Griff. Jeden Tag wenden sich mehr und mehr ihrer Leute von ihrer Herrschaft ab. Wir müssen ihre Rekrutierung sabotieren.\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher zu verbrennen, die der Schattenhammer dort verteilt.", sourceObjective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[28329] = { id = 28329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böser Schlamm! Böser Schlamm!", description = "Dieser Seuchenschlamm scheint wirklich wütend zu sein. In seinem Ektoplasma kann man sogar ganz schwach die Konturen eines wütenden humanoiden Gesichts sehen. Hinott wäre sicher nicht allzu erfreut, wenn seine Schleimpfützen mit unkooperativem Schlamm übersät sind.\n\nTötet den wütenden Seuchenschlamm und versucht, einer ihrer Brutpfützen Herr zu werden.", sourceObjective = "Tötet 5 wütende Seuchenschlamme.", sourceObjectiveStatus = "unverified-source-field" }
quests[28330] = { id = 28330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreckige Spuren", description = "Die Spur aus Dreck und Wut führt in die Ruinen des Rathauses. Sicherlich befindet sich eine Brutpfütze in dem Gebäude. Kämpft Euch hinein und macht kurzen Prozess mit dem wütenden Schleimzüchter, den Ihr dort findet!\n\nWenn Ihr Erfolgt habt, solltet Ihr Serge Hinott in den Ruinen von Süderstade unbedingt davon berichten.", sourceObjective = "Tötet Chet den Schleimzüchter.", completion = "Jetzt, da Chet vernichtet ist, sinken die Tödlichkeitswerte an diesem Ort vielleicht schneller. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
